/* 令和7年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r07.committeeSessions.push(...[{"id":"r07-20250120-6","meetingId":"r07-cm01","date":"2025年1月20日","dateIso":"2025-01-20","committee":"区民委員会","time":"午後 １時００分～午後 ２時５７分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を47件整理しています。","topics":[{"id":"topic-01","title":"「公共の場所における喫煙に関する規制強化および公衆喫煙所の整備促進の考え方」に係るパブリックコメントの結果","agenda":"「公共の場所における喫煙に関する規制強化および公衆喫煙所の整備促進の考え方」に係るパブリックコメントの結果","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"こういうふうなことを考えていますという区の見解というのですかね、そうかもしれないですけれども、そういった見解をつけるのでしょうか。現状で何かそういう課題とかで適正に対策していくというのは、どういうことを言っているのか、もう少し伺いたいなというのが２点目です。","respondent":"河合生活安全担当課長","answer":"公園の設置につきましては、こちらは例外という説明を簡単にしていますけれども、個別に課題があった場合に限り検討するという形になります。具体的な検討というところは、公園課のほうで検討する形になりますので、こちらではちょっと回答を控えさせていただきたいと思います。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"将来的に喫煙者を減らしていくという考えがあるのか伺いたいと思いますし、区内の喫煙者の数ですとか、率は減っているのでしょうか。直近で、もし比較できる数字などをお持ちでしたら、ご紹介ほしいと求めました。","respondent":"河合生活安全担当課長","answer":"やはり、影響があるという考えにのっとってやっておりますので、こちらとしては喫煙者が減っていく方向で考えていくべきではないかと考えております。東京都でも１５％を切るような形になっておりますので、減少傾向は続いていると認識しております。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"ほかの関連部署と連携して、本人にとっても喫煙しないで済むなら、少なくとも健康にとってはいいわけですから、ぜひその点からも必要な部署と連携して喫煙者を減少させていくという立場でお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"おぎの委員","kind":"質問・要望","question":"たった７人でも２３％とかになってしまうような統計ですので、ちょっと周知が足りていなかったのかなという気がします。規制をこれから変更していきますよという周知にもなりますので、そういった今後の広報も含め、少し方針があればお聞かせほしいと求めました。","respondent":"河合生活安全担当課長","answer":"今回は条例改正というところで広くご意見を頂戴したいということで、しなメールとＳＮＳを個別的に対応させていただいた状況です。今後、トラブルがあった喫煙所等での周知や掲示というものは、今後の参考にさせていただきたいと思いますのでよろしくお願いします。","id":"exchange-004"},{"speaker":"ゆきた委員","kind":"質問","question":"１１月の委員会で申し上げましたが、努力義務から罰則なしの禁止規定に変わることは、非常に歓迎したい内容だと思っています。パブリックコメントの周知の仕方、ここについて検討された内容と実施された周知の仕方について具体的なところがあれば、お聞きしたいと思います。","respondent":"河合生活安全担当課長","answer":"パブリックコメントを実施しておりますとか、そういった形で対応させていただいたため、マイク広報は実施せず。","id":"exchange-005"},{"speaker":"ゆきた委員","kind":"確認","question":"声かけもやっていただいたということを確認しました。不特定多数のところで幅広い意見を集約していくことも必要だと思いますが、この辺について最後にお聞きできればと思います。","respondent":"河合生活安全担当課長","answer":"考え方についての意見の募集としましては、一応こちらのほうで整理させていただいています。今後の周知のところで、委員からありましたＱＲコードの読み取りとか、そういったことは今後の参考とさせていただきたいと思います。","id":"exchange-006"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"以前から要望してきた内容が、今回の意見にまさに集約されているのではないかと思います。たばこ税を含んだたばこを購入しているわけですから、吸う人にも吸わない人にも非常に分かりやすいと思うので、ぜひその辺は検討していただきたい。","respondent":"河合生活安全担当課長","answer":"たばこ税を使っているかどうか、ちょっと私もまだ勉強不足で分かりませんので、主管課と確認しながらできるものから検討してまいります。個別に企業のほうにそういった申入れ的なものを行うような形で対応しているのですが…","id":"exchange-007"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"これは要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"せお委員","kind":"質問・要望","question":"４月から規制していく、規制のほうが先で、絶対整備までのブランクがあるわけではないですか。喫煙所が不足しているエリアの把握というのはどのようにされているのか説明を求めました。","respondent":"河合生活安全担当課長","answer":"嗜好品の面もありますので、そういったところは喫煙所を整備しながら、そういったご紹介ができるように対応していきたいと考えております。今ご説明したクラブＪＴのマップも含めて、こちらで喫煙所を設置しているところ、そういった予測はできております。","id":"exchange-009"},{"speaker":"せお委員","kind":"意見","question":"３か月ぐらいあるとしても、３か月で設置というのはなかなか難しいのかなと思っているので、ぜひそこら辺の働きかけをお願いしたいなと思っていますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"藤原委員","kind":"質問・要望","question":"それともう一点は、ちょっとすみません、具体的な質問になってしまうのですけれども、西大井駅前はどうなっているのですか。今日はパブリックコメントだけれども、公共の施設、喫煙所という意味で、何回も要望している西大井の駅前はどうなっているのか尋ねました。","respondent":"河合生活安全担当課長","answer":"先ほどの私の説明がちょっと不足していたようで、私が勉強するというのは、そこは確認させていただきたいという趣旨で答弁させていただきました。３月２日ぐらいから着工で、今あくまでも予定なのですけれども、３月２１日にＪＴから引渡しを受けるという計画ができております。","id":"exchange-011"},{"speaker":"藤原委員","kind":"質問・要望","question":"勉強不足だ、勉強不足ではないということを伺っているのではなくて、どんどん要望していくべきではないですかと。それは僕たち議員がいろいろな委員会で求めていくということになるわけですから、その辺の答弁をほしいと求めました。","respondent":"河合生活安全担当課長","answer":"喫煙所設置のときには、補正予算でも対応をお願いしますという申出をいろいろしていますので、今後もそういったところでやはり状況に応じて対応できるように検討したいと考えております。","id":"exchange-012"},{"speaker":"藤原委員","kind":"質問・要望","question":"補正予算を組んでもやってほしいと財政課のほうに言っていたのですね。財政課のほうにしっかり私も議員の１人として要望していきたいと考えていますので、これだけ言ったのですから、その辺についてはいかがか尋ねました。","respondent":"河合生活安全担当課長","answer":"こちらがまだ不足しているところもありますので、そこは財政課と連携しながらやっておりますので、財政課がつけてくれないということではありません。必要になったとき、その状況に応じて補正予算で対応しようかという検討はしておりますので…","id":"exchange-013"},{"speaker":"吉田副委員長","kind":"質問","question":"周知は広報しながわの１２月１日号、何かもう少し、なるべく広く意見を出してほしいというような姿勢を見せてほしかったなと。品川区がそもそも短いのです、その中で１か月頑張りましたということなのか、その辺について伺いたいと思います。","respondent":"河合生活安全担当課長","answer":"こちらのほうはスケジューリングとかを含めて、戦略広報課と調整をして大体このぐらいの期間ということで決めたものです。実際、そういったところで広報しながわとホームページの両方に掲載する１２月１日から周知というような形を取らせていただきました。","id":"exchange-014"},{"speaker":"吉田副委員長","kind":"質問","question":"もう少し出しやすい方法を考えてほしいというのを、ごめんなさい、やっぱりあらかじめの周知はしないという理由がよく分からない。１２月２７日が仕事納めの日だということは承知しているので、もう少し先まで延ばすとか、そういうことは考えられなかったのか改めて伺います。","respondent":"河合生活安全担当課長","answer":"規定の中では１４日以上３０日以内というような形になっておりまして、ほかのパブリックコメントが３件あったのですけれども、１２月２７日というところで設定をさせていただきました。","id":"exchange-015"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"そういう意味では、私はそうあってほしいと思いますし、広報と併せて今後多くの区民が出しやすいような方向でぜひ検討してほしいと求めました。これは要望にとどめておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"}]},{"id":"topic-02","title":"「おくやみハンドブック」の配布","agenda":"「おくやみハンドブック」の配布","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"その辺をお伺いしたいのと、ハンドブックの５ページの臨海斎場ですが、結構複雑なのでしたか。未記載の理由というのですか、できれば記載したほうがいいのではないかなと思うのですが、そこについてはいかがか尋ねました。","respondent":"築山戸籍住民課長","answer":"おくやみコーナーにつきましては、令和６年１月から開始いたしまして、ちょうど丸１年たったところです。２つ目のご質問で、臨海斎場は３年に一度料金の改定を行っておりますので、その関係で記載はしておりません。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"ぜひ料金のことも知らせてほしいので、そういった工夫もしていただけたらなと思うのですけれども、いかがでしょうか。そういうふうになっているよということであればそれでいいのですけれども、それはいかがか尋ねました。","respondent":"築山戸籍住民課長","answer":"今設置しているか、統一的な対応はしておりませんので、窓口等でお声があったときにお渡しをしているというような形でしております。ただ、十分な配置場所があれば設置はしたいと思うのですけれども、ない場合に無理やり場所を作ってというところまでの対応はしていないところで…","id":"exchange-018"},{"speaker":"安藤委員","kind":"意見","question":"高齢化社会ということもありますし、本当に身近な課題になってくると思いますので、無理やりということは申しません。そういった意味では、事前に必要だなと思う人が取れるようにしてほしいと求めましたので、意見として言わせていただきますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"おぎの委員","kind":"確認","question":"これはＡ４サイズになって字が大きくなったということで、高齢者の方も非常に見やすくて、配慮があっていいなと思います。事前に見ておきたい方という意見も今ありましたけれども、配布のタイミングというのをもう一度確認でお願いします。","respondent":"築山戸籍住民課長","answer":"配布のタイミングですが、こちらは死亡届が提出された際にお配りしている形になります。ただ実際は、葬儀会社の方が代行される場合がありますので、葬儀会社を経由してご遺族の方に届くというような形になっているかと思います。","id":"exchange-020"},{"speaker":"おぎの委員","kind":"質問","question":"死亡届のときにお渡しするということで、区民葬儀の対象の葬儀会社も、対象の案件については、品川区から費用が出るということですけれども、受け取ったタイミングで葬儀会社を別のところにお願いしていたりすると、品川区の区民葬儀の対象になるのかどうなのか、その辺はどうなのか尋ねました。","respondent":"築山戸籍住民課長","answer":"取扱いのメニュー等につきましては、記載のとおり様々あります。おっしゃるとおり、取扱いしている事業者は限られておりますので、こちらに記載されている事業者のみのサービスという形になっています。","id":"exchange-021"},{"speaker":"おぎの委員","kind":"質問","question":"霊柩車、火葬料金、遺骨収納容器が価格を抑えた形で区民の方はやっていただけているということで間違いないでしょうか。これは、こちらの区民葬儀取扱店に区から助成金とかそういうのが入っていたりするのか尋ねました。","respondent":"築山戸籍住民課長","answer":"区民葬儀の対象になるのは、こちらの取扱店で扱った場合になります。助成金等については、区からは一切入っておりません。","id":"exchange-022"},{"speaker":"おぎの委員","kind":"意見","question":"分かりました。ちなみに今何％ぐらい活用されているとか、そういったデータというのは分かりますかとの意見を述べました。","respondent":"築山戸籍住民課長","answer":"区民葬儀券を品川区のほうからお渡ししているのですけれども、直近の交付実績でいきますと、令和５年度は１６０件の交付になっております。","id":"exchange-023"},{"speaker":"おぎの委員","kind":"質問・要望","question":"１５ページの相続税のところで、最近、外国籍の方が亡くなられたときの土地の取得をされた方の相続税というのはどうなっているのかなと。以上２点、お願いします。","respondent":"築山戸籍住民課長","answer":"２つご質問いただいているところですが、１２ページの区民相談室についてですが、どういった内訳かというのは把握しておりません。もう一つ、相続税につきましても、税についてはこちらのほうでは所管しておりませんので、申し訳ございません。","id":"exchange-024"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"ただ、注釈でここは３年に１回変更される可能性があるので、詳細は会場にご確認くださいみたいなので可能なのではないかなと思う。相手側が何を情報として求めるのかというのが大事で、ぜひ次回を含めて、増刷されるときには検討していただければと思うので。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"藤原委員","kind":"質問・要望","question":"なぜかというと、利用方法で、「区役所で死亡届を提出する際に区民葬儀券の交付を受け」と書いてあるではないですか。だから具体的に伺いたいのですけれども、その辺はいかがか尋ねました。","respondent":"築山戸籍住民課長","answer":"葬儀の内容によって、個々によって金額が異なってくるものだと認識しております。区の行政の窓口で、区民葬儀券というのが必要になりますので、そこは周知が必要ということで掲載をさせていただいているところです。","id":"exchange-026"},{"speaker":"藤原委員","kind":"質問","question":"これはどう考えても調査をしても安価ですと、いや、ちょっと方向性が違ってくると思うからこういう質問をさせていただいているのですよ。大体、これだけ安いのですというしっかりした担保を持っていないと私は違うと思っているので、その辺についてはいかがか尋ねました。","respondent":"築山戸籍住民課長","answer":"この区民葬につきましては、安いということを保証しているものではありませんので、あくまで制度として、区民葬儀というものがあって、その取扱店が区民葬として定められた価格で葬儀を提供しているというところの紹介をしているものです。","id":"exchange-027"},{"speaker":"藤原委員","kind":"質問・要望","question":"でも、どう見ても高かったら、何なのとなってしまうではないですか、後から。その辺について、しっかり押さえていっていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"築山戸籍住民課長","answer":"やはり、なかなか一般的な葬儀の価格帯がどのラインが妥当かというのは、こちらで判断するのは非常に難しいかと認識しております。記載のとおり負担軽減を目的として価格を設定して提供しているサービスですので、そちらを紹介させていただいているというところになります。","id":"exchange-028"}]},{"id":"topic-03","title":"品川歴史館リニューアル特別記念展「品川の海と海苔」","agenda":"品川歴史館リニューアル特別記念展「品川の海と海苔」","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"現状はどうなっているのかというのと、この期間中に訪れる学校とかはあるのでしょうか、説明を求めました。","respondent":"大森文化観光戦略課長","answer":"リニューアル後の６月２５日から、後地小学校３年生をはじめ、先々ですと２月２１日の荏原平塚学園の生徒までが予定されております。１,２３８人、１例だけ、大井第一小学校だけ６年生とか２年生が視察に来ているといった状況です。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問","question":"小学校３年生が主にということですけれども、後期課程というのですか、感想を述べさせていただきました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"おぎの委員","kind":"質問","question":"私からは２点だけ。どういった配置になっているのかというのと、今、茶室の利用率というのはどれぐらいか尋ねました。","respondent":"大森文化観光戦略課長","answer":"正規の職員の学芸員が１人と、それから会計年度任用職員ということで３人の計４人が学芸員として館のほうに詰めているという状態です。すみません、手元に資料がなくて。","id":"exchange-031"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"１点だけ。何か広報の仕方みたいなものをぜひ考えていただきたいと思うので、その辺、今あるのかどうか教えてほしいと求めました。","respondent":"大森文化観光戦略課長","answer":"アドバイス、ありがとうあります。そちらのほうであれば、団体利用がある場合には、本日何時から何時まで団体利用がありますみたいなことを周知できればと思います。","id":"exchange-032"}]},{"id":"topic-04","title":"しながわシティランの開催に向けた進捗","agenda":"しながわシティランの開催に向けた進捗","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"資料について２点お伺いしたいのですが、目的ですけれども、いろいろ書いてあるのですが、区民のスポーツを行う要求に応えるという感じですかね。それがちょっと入っていないのが残念なのですが、これは位置づけるべきだと私は思うのですけれども、いかがでしょうかというのが１つ。","respondent":"三井スポーツ推進課長","answer":"これまで区民スポーツ大会の種目の１つとして区民マラソン大会を実施してまいりましたので、見る、支えるということで。そういったものを含めて、区に返金をいただくということで、区から出している負担金を実際に減らすということで考えております。","id":"exchange-033"},{"speaker":"安藤委員","kind":"質問・要望","question":"これは既に区が負担金を出しているので、その分が余った場合には充当というか、そういうことになる、分かりました。今後入っているというのであれば、ぜひそういったところも忘れずに、一言でもいいので入れてほしいと要望します。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"おぎの委員","kind":"質問","question":"協賛企業の募集結果のところをお伺いしますが、協賛金額が４,０００万円ほど集まったということで、すばらしいと思います。物品で協賛されている会社のものは、金額には含まれていないですよねということが１つと、どういったものが協賛品として集まったのでしょう。","respondent":"三井スポーツ推進課長","answer":"飲料で言うと、ジュニアランとかファミリーランでお菓子等の配布を予定しているのですが、そういったお菓子の提供をいただいているところもあります。その他、複数あるので、事例としてはそのような形になっております。","id":"exchange-035"},{"speaker":"おぎの委員","kind":"質問","question":"交通規制を行うということで、ふだんあまり運動をされない方でも、イベント的に参加される方というのがいらっしゃると思うのですね。１０kmだと、どうしても規制に間に合わない方が出てくると思うのですが、どのようにされる予定か尋ねました。","respondent":"三井スポーツ推進課長","answer":"4)の矢印の手前ぐらい、海岸通りの手前が第１収容関門、状況に応じて対応していくところです。歩けない状態なのか、当日は医療観察スタッフが１０名ほど自転車で回っていますので、救護本部と連携しながら対応を考えていくところになります。","id":"exchange-036"},{"speaker":"おぎの委員","kind":"質問","question":"最後に１点だけ、しながわシティランの広告動画を作られていて、あれを私もＳＮＳ等で時々拡散させていただいているのですが、あの動画はどなたが作って、金額はどれぐらいかかっているのか尋ねました。","respondent":"三井スポーツ推進課長","answer":"今回実際に他のマラソン大会を見ながら検討していったのですが、来年はもう少し経費を抑えてできるかなと考えています。当日の映像等を使いながらＰＲ動画を作っていければなと思っています。","id":"exchange-037"},{"speaker":"おぎの委員","kind":"質問・要望","question":"確かに初年度なので動画に使う素材がないという部分もあるのかなとは思います。来年を見越してまた広報戦略をかけられるように、今年のうちから大会の記録としていろいろな画像を撮ってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-038"},{"speaker":"ゆきた委員","kind":"質問","question":"１点、１０kmとジュニアラン２kmとファミリーラン１kmで、それぞれ教えてほしいと求めました。今後、次年度以降にも関わってくることだと思いますので、ぜひお聞きできればと思います。","respondent":"三井スポーツ推進課長","answer":"区内が約１,６００人、区外が約８００人から９００人の間ということで、大体割合としては６５％ぐらいが区民の方ということになっております。ジュニアランについては在学も含めてですけれども、ファミリーランについては在住の区民の方のみということになっております。","id":"exchange-039"},{"speaker":"ゆきた委員","kind":"確認","question":"確認できました。２月中には、ここについて分かる範囲で、状況とか進捗についてお聞きできればと思います。","respondent":"三井スポーツ推進課長","answer":"ただ、実際に置く場所についてはこれから調整ということで、ただ実際に置くという方向で調整を進めているところになります。実際に活用もできればということで、防災課のほうから話を聞いているところです。","id":"exchange-040"},{"speaker":"ゆきた委員","kind":"確認","question":"現状、確認できました。障害のある方のトイレとか、公衆トイレの場所と数まで確認できるようになっていますが、この辺について何かお考えがあればお聞きできればと思います。","respondent":"三井スポーツ推進課長","answer":"トイレの設置場所と仮設のトイレをどこに置くかということも最近決まってまいりましたので、なるべく事前に周知できればと思うのですが、どういった形でできるのかは、これから検討してまいります。","id":"exchange-041"},{"speaker":"せお委員","kind":"質問","question":"４番のイベントですけれども、地図とかそういったものはこれから出てくる予定なのでしょうか、説明を求めました。","respondent":"三井スポーツ推進課長","answer":"イベント内容につきましては、スケジュールを現在検討しているところになりますので、決まり次第ホームページ等、あとはＳＮＳ等で発信できればなと考えているところになります。","id":"exchange-042"}]},{"id":"topic-05","title":"行政視察報告書","agenda":"行政視察報告書","exchanges":[{"speaker":"安藤委員","kind":"意見","question":"内容はいいのですけれども、議長に報告する際に、こんなにすばらしいものができているので、ぜひこれを区民に広く公開するように、併せて委員長のほうから、具体的にはホームページに掲載してほしいということですが…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-043"}]},{"id":"topic-06","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"ご納得されたのかということを伺いたいのと、そもそも原因というのですかね、その辺はどうなのか尋ねました。","respondent":"築山戸籍住民課長、横田デジタル推進課長","answer":"ご案内した後の対応ですが、ご不便をおかけしたところではありますが、ご理解いただいたところです。再来庁が難しいという方に対しましては、郵送対応ですとか、個別で対応をさせていただいたところです。 本日のミスですが、そちらの処理が終了しなかったために、マイナンバーカードの住基ネット処理も更新できなかったという事象になります。それから、今回は住民記録システムと住基ネットとの連携部分になりまして…","id":"exchange-044"},{"speaker":"安藤委員","kind":"質問","question":"すみません、もう一点だけ、ごめんなさい。結局どういうことなのかが分かるように説明してもらいたいのと、そういう問題ではないのかしら、伺いたいと思います。","respondent":"横田デジタル推進課長","answer":"住民記録システムと住基ネットの連携が、実データの連携まで検証ができずに、通信の疎通確認のみ検証を実施しておりました。今後システム更改前の後日対応で済む処理を、システム更改後に、今後より効果的なベンダーコントロールを実現できると考えております。","id":"exchange-045"},{"speaker":"安藤委員","kind":"意見","question":"そういう懸念とか不安はわりと置き去りにされて、どんどん強圧的に進められてきたというところで自治体は大変苦労しているのだなと私は思いました。そうした権利の擁護ですので、その辺をきっちりと考えて、これから取り組んでいってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-046"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"情報の発信の仕方というのは、ぜひ平時から、きちんとやっていただきたいなと思います。そこの情報発信というのは、平時から取り組んでもらうというのが大事なのかなと思うのですけれども、その辺についてお考えを説明を求めました。","respondent":"築山戸籍住民課長","answer":"委員がおっしゃるとおりですが、速やかに報告することが重要だと考えております。状況を確かめながら正しい情報を提供できるように努めてまいりたいと考えております。","id":"exchange-047"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/414982?Template=document&Id=6941#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":36322,"voices":139}},{"id":"r07-20250120-7","meetingId":"r07-cm01","date":"2025年1月20日","dateIso":"2025-01-20","committee":"厚生委員会","time":"午後 １時００分～午後 ３時０６分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件整理しています。","topics":[{"id":"topic-01","title":"令和６年陳情第５７号、支援区分５と６の重度障害者が入居できる障害者グループホームの整備を品川区長に求める陳情","agenda":"令和６年陳情第５７号、支援区分５と６の重度障害者が入居できる障害者グループホームの整備を品川区長に求める陳情","exchanges":[{"speaker":"ひがし委員","kind":"質問","question":"は今回の重度障害者、区分５、６の入居者が２３区の中でも最低であったというような調査結果について、率直に区の受け止めを教えてください。入居の進捗と区分の内訳、また必要性の高い区分Ａの方のうち、どのように体験入居を進めていったのかというようなことについてもお知らせください。","respondent":"佐藤障害者施策推進課長、松山障害者支援課長","answer":"詳細が分かりかねますので、区としてはそのような事実を確認できておりませんので、そこについては１つのお答えというものはないところです。現在、令和６年１１月現在で支援区分５… 支援区分の内訳ですけれども、区分２が４人ということで、計１６名ということになっております。体験の可能性、指定管理者がお声をかけさせていただいて…","id":"exchange-001"},{"speaker":"ひがし委員","kind":"確認","question":"そのうちの１６名の方々は、Ａの中でも細分化して、入居の可能性が高い方々から先に体験入居を勧めたのかという点をもう１回ご確認させてください。もう１点、なぜ中重度対象の出石つばさの家は通院等介助のサービスを実施しないのでしょうかというようなご質問が陳情にも書かれていますので。","respondent":"松山障害者支援課長","answer":"なかなか体験が難しい、そもそもが体験が難しい方もいらっしゃいますので、それは指定管理者の判断によるものです。それからご家族の状況、緊急対応など含めて判断するということで、全く通院介助ができませんということではありませんでした。","id":"exchange-002"},{"speaker":"ひがし委員","kind":"質問","question":"ということは、今現状では受け付けていないというわけではなくて、総合的に判断をしてできるような体制に向けて調整していくということですか。その方の安全やご家族の状況などを見て、難しければできないし、そこは施設と委託されている先との協議の上決まっていくということなのか尋ねました。","respondent":"松山障害者支援課長","answer":"まずは施設の安全上、それから緊急対応が必要かどうかと、あとご家族の状況等を総合的に判断して決めていきたいということでした。どうしてもご家族が付き添えない、あるいはサービスが使えないといった場合については、実施する場合があるということでした。","id":"exchange-003"},{"speaker":"ひがし委員","kind":"質問","question":"その施設の中で、今回出ているものが重度のところなので、支援区分５と６の方がどのぐらい定数として入るご予定なのか説明を求めました。","respondent":"佐藤障害者施策推進課長","answer":"支援区分、そのうち５、６の方が３名から４名程度というような形になるところも出てこようかと思います。２か所になるので、合わせて６名から８名程度、令和８年度までに利用できる枠が増えていけるというようなところを見越しています。","id":"exchange-004"},{"speaker":"ひがし委員","kind":"質問・要望","question":"その認識でよろしいのかというところを聞かせていただきたいということと、あと１点、助成金というものがすごく大切になってくると思うのです。現在品川区では、ぜひ重度の障害の区分に対しての助成というところも検討していただきたいと思うのですが、その点についても併せてお答えください。","respondent":"佐藤障害者施策推進課長、松山障害者支援課長","answer":"重度の方を一斉に受け入れて、その辺りは受入れの見極めをきちんとして、利用者の方が困らないような形で進めていきたいと考えているところです。そういった部分については、民間の誘致のほうにつきましても… 現在品川区では有資格者助成はありますけれども、ご利用者の受入れに対しての助成金についても広く検討してまいりたいと考えています。さらに進めるために、検討を進めてまいります。","id":"exchange-005"},{"speaker":"ひがし委員","kind":"質問・要望","question":"今入りたいと言って入れなくて、しっかりと区も進めていく方針だということがご確認できたので、その点進めてほしいと求めました。ぜひ前向きに検討していただくように要望させていただきまして、私からの質問は以上とします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"鈴木委員","kind":"質問","question":"この調査用紙も頂いたのですけれども、多分これも区のほうに行っているのではないかなと思うのですけれども、これはご覧になられていないでしょうか。これは本当に、私は区としてもしっかりと受け止めていただいて、その点についての受け止めについては改めて伺いたいと思います。","respondent":"佐藤障害者施策推進課長","answer":"直近の数字でも１桁というところで、こちらのほうとしても課題だというような認識としては、認識しているところではあります。グループホーム全体の整備を進めているという状況ではありますが、引き続き区のほうとしましても進めていくべき内容だというようには認識しています。","id":"exchange-007"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ぜひ強力に、しっかりと計画を持って整備をしていっていただきたいということで、強く要望しておきたいと思います。ですから、６の割合がどれぐらいかということがすぐに分かるようであれば、ちょっと教えていただけたらと思います。","respondent":"松山障害者支援課長","answer":"支援区分については、支援区分５、６は入所施設の方に多くいらっしゃるです。前回ご説明したとおりの数字ですので、例えば公募要領に５や６だけですなど、そのようなことではございませんでした。","id":"exchange-008"},{"speaker":"鈴木委員","kind":"質問","question":"合わせて５、６は３人しか入れないという事業計画でそのような計画だったということだと、ちょっとそこのところが分からないのです。実際３人しか入らないという、今４人になったのですか、ちょっとその辺のところを改めてお聞かせいただけたらと思います。","respondent":"佐藤障害者施策推進課長","answer":"特にこちらとしても出していただいて確認して、区としてそちらを通して、受け取って確認しているものではございません。〔「事業計画にここまでは書いていないということ」と呼ぶ者あり〕 事業計画には、公募のときにそこまで、これをそのとおりに実施するというような形でのというところではございませんというお話になります。実際支援区分の方が２人いるような状況も踏まえまして、申込みがあった方はその入所の調整をし…","id":"exchange-009"},{"speaker":"鈴木委員","kind":"質問・要望","question":"何というのですか、区の思いと事業者の思いがずれたのか、その辺のところはどのような状況だったのか教えていただけたらと思います。要望に応えられるような、その点、今後に向けてというようなところも伺えたらと思います。","respondent":"佐藤障害者施策推進課長","answer":"中重度というと支援区分だけのお話ではない部分ももちろんありますが、５、そこの提案が中重度を入れていただくというようなところの認識であったと。今後につきましては、今後も利用したい方が支援区分にかかわらずご利用いただけるような形で…","id":"exchange-010"},{"speaker":"鈴木委員","kind":"質問・要望","question":"重度の方は４人という、１６の定数に対して４人というものが重度というようなことで、今のご答弁だと。区は今の４人でよしとして、私はそのような方向にぜひしていただきたいと思うのですけれども、その点についても伺います。","respondent":"佐藤障害者施策推進課長","answer":"必要な方、児童の方も含めて、この部分については対応できるようにというようなところは十分考慮してまいりたいと考えております。","id":"exchange-011"},{"speaker":"鈴木委員","kind":"質問・要望","question":"かなり、区立ということで対応が求められるのではないかなと思いますので、区としても検討していただきたいということでお願いしたいと思います。このような助成ということでいいのかということを伺いたいということと、あと、多分これ東京都の助成ですよね。","respondent":"松山障害者支援課長","answer":"それから出石の方につきましても、知的障害者グループホームということで、区の家賃助成の対象になっております。今ちょっと詳細な数字は持ち合わせておりませんが、全くゼロということはございませんで、複数名助成を区としては適用しているという状況です。","id":"exchange-012"},{"speaker":"鈴木委員","kind":"質問・要望","question":"どちらにしても、本当にグループホーム、一般質問などでも取り上げさせていただいていますけれども、絶対数が足りないと思うのです。そのようなところで、私は区としてもぜひ進めていただきたいと思うのですけれども、その点お願いします。","respondent":"佐藤障害者施策推進課長","answer":"そこに向けて増やすためにどういった方策が必要かといったところは明らかにしていかなければいけないところというようには認識しています。表し方、表示の仕方も含めて検討を進めてまいりたい、そして整備のほうを進めてまいりたいと考えております。","id":"exchange-013"},{"speaker":"鈴木委員","kind":"質問・要望","question":"一般質問で聞いたときに、やはり品川区のグループホームの利用者が２７７人、去年の７月段階で。本当に住み続けたいと皆さん願っているのに、ぜひその計画も含めて、このような実態の改善に取り組んでいただきたいということで要望します。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"筒井委員","kind":"確認","question":"方針ということは確認をさせていただきましたけれども、この記述について、どのように区としては受け止めておられるのか伺いたいと思います。","respondent":"松山障害者支援課長","answer":"この陳情にある記載の受け止めですが、指定管理者に確認したところ、特にこのような発言というようなものは、こちらのほうにはしていないというような報告は受けております。","id":"exchange-015"},{"speaker":"筒井委員","kind":"質問・要望","question":"分かりました。改めて確認を行いたいということと、しっかり重度の方を受け入れていただきたいと思うのですが、２点ほど伺いたいと思います。","respondent":"松山障害者支援課長","answer":"中重度の方を受け入れていただく際には、しっかりと今後も、その受入れや体制に合わせて指定管理料を区としては確保して支援してまいります。そして今いる方が重度化・高齢化になっても地域で住み続けられるように支援していく施設であるということは…","id":"exchange-016"},{"speaker":"若林委員","kind":"確認","question":"当然第７期ですか、イコール計画すべき人数が出ていますけれども、その辺を確認させてください。","respondent":"佐藤障害者施策推進課長","answer":"例えばグループホーム、共同生活援助の令和６年度の見込量としては３１７というような数字で載せさせていただいているところです。サービスを実際に利用されている方の支援区分の状況等は、障害者支援課のほうでの給付実績等で把握してまいりますので、繰り返しになりますが。","id":"exchange-017"},{"speaker":"若林委員","kind":"質問","question":"令和６年度、今年度は３１７という数字がこの計画の中に載っていて、括弧書きで、内の精神障害の人数も出ています。品川区が１００人分の障害者グループホームの整備目標をほぼ達成するということで、区として認識しているところなどありますか尋ねました。","respondent":"松山障害者支援課長","answer":"それから中重度の必要な方というものは、どの方もグループホームという住まいが地域の中で必要であると認識はしております。もちろん数字的には、これから計画をつくる上で細かな分析はしてまいりますけれども、どちらが片やこうということではございません。","id":"exchange-018"},{"speaker":"若林委員","kind":"質問・要望","question":"願意に沿えるかどうかという観点で、今回の場合はグループホームにどうやって入っていただくか、この陳情の議論を聞いていて思います。これはもう区役所や議会というものはそのようなものですから、戸越四丁目とご努力をされているということは冒頭で確認させていただいたし。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"やなぎさわ委員","kind":"確認","question":"改めて確認なのですけれども、戸越四丁目というものが民設民営、これは区のほうから指定料などというものは出たりはするのでしょうか。〔「補助金」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"やなぎさわ委員","kind":"質問","question":"では、すみません、質問を変えます。何かしらの運営費の助成等が行われる予定はありますか尋ねました。","respondent":"佐藤障害者施策推進課長","answer":"今ご質問ありました小山七丁目、戸越四丁目に関しましては民営という形になりますので、指定管理料の形では、当然出ないという形になります。まだこれも計画の途中ですので、あとは運営に係る補助…","id":"exchange-021"},{"speaker":"やなぎさわ委員","kind":"質問","question":"障害者区分５、６が約半分ぐらい全体でいらっしゃるということで、新しくできるグループホームに関してなるべく……。にそういった運営の補助等で、改めてそういった議論が今区の中でどのような進み具合をしているのかということをちょっと説明を求めました。","respondent":"松山障害者支援課長","answer":"民間への補助についてです。重度の方の入居者を増やしていただくために、広く、やはり補助については検討していきたいと考えております。","id":"exchange-022"},{"speaker":"石田（秀）副委員長","kind":"質問","question":"ひとつ考え方を伺いたいことは、２９、３０ぐらいはできているわけではないですか。ここの場合は重度の５、６だけれども、運営費の助成金というものを入れているわけか尋ねました。","respondent":"松山障害者支援課長","answer":"他区の重度者の受入れの運営費の助成金の状況です。２３区の中で実施している区はありますので、さらに受け入れていただけるように、広く検討しています。","id":"exchange-023"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"これは事実で、その辺のところも変えてくれないと、区だって責められても動けないではないですか。重度がこうだと逆のようになってしまうとか、人を増やさなければいけないからとか、そのようなことで逆のバージョンも出ているわけではないか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"石田（秀）副委員長","kind":"質問","question":"本日結論を出すであります。ここはちょっと今５と６、５と６という陳情があって、不採択でお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"ひがし委員","kind":"質問・要望","question":"区が重度の障害がある方も入居できるように取り組んでいくというようなご確認ができましたので、今回の陳情には沿い難く、不採択とします。重度障害者を入居させた際の助成など、そういった点についてもしっかりと検討を重ねていただきますように、こちらは強く要望をします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"},{"speaker":"鈴木委員","kind":"質問・要望","question":"職員体制もしっかりと整える、本当に社会問題になっているわけですから、これが必要だと思います。でも実際に区民がこれだけ困っているというような状況があるわけですから、整備の計画をつくっていただきたいということで、採択でお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"やなぎさわ委員","kind":"意見","question":"本日結論を出すで、趣旨採択にしたいのですが、３つになってしまうので採択にします。それにはどうしても時間がかかってしまうということもあるので、様々な方策をぜひ積極的に取っていただいて、今回は採択でありますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"}]},{"id":"topic-02","title":"東大井三丁目における都有地（都営元芝アパート跡地）を活用した特別養護老人ホーム等整備計画の事業者辞退","agenda":"東大井三丁目における都有地（都営元芝アパート跡地）を活用した特別養護老人ホーム等整備計画の事業者辞退","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"去年の１１月２６日に厚生委員会で、３か月遅れて全体としては半年ぐらい開設が遅れるという報告があったばかりなので、ちょっとその辺の白紙の状況というものはどのようなことなのかも改めて説明を求めました。","respondent":"東野福祉計画課長","answer":"特別養護老人ホームの需要数が多いということで、区といたしましては、改めて特別養護老人ホームの計画として、東京都のほうに申入れをしています。今後につきましては再公募ということで、同じような形式を取りながら進めていきたいと都との協議を進めていくということで…","id":"exchange-029"},{"speaker":"鈴木委員","kind":"質問・要望","question":"改めて再公募ということなので確認させていただいていいですよねというようなことと、ちょっとその点についてもお聞かせほしいと求めました。いつ申出があったのかということも分かったら教えていただきたいということと、人材の確保など、その点についても説明を求めました。","respondent":"東野福祉計画課長","answer":"目黒駅前の施設との規模的な差はあるので、具体的な比較というものは難しいのですけれども、同程度の額は必要ではないかと考えています。あくまでもこれは建設費高騰で事業者の資金計画が追いつかなくなったということでのご辞退ということで認識しています。","id":"exchange-030"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そのような見通しはつくのかどうなのか、ぜひつくっていただきたいと思うのですが、その点についても伺いたいと思います。","respondent":"東野福祉計画課長","answer":"１点方策としてはお借りするということも考えられるのですが、そうしますと、何分費用がかかってしまうというところがあります。財政的なところも含めて考えていくような形になろうかと思います。","id":"exchange-031"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ぜひそのような方向も含めてご検討いただいて、３年も延びてしまうということは、地域の方からも待ち望まれているという施設なので、なるべく早く要望に応えられるようなことも含めてご検討ほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"},{"speaker":"石田（秀）副委員長","kind":"質問","question":"今おっしゃったようにやり直して３年間延びるということは、それは分かりますが、大丈夫ですか。それはもう１回よく考えてやらないと、大丈夫ですかという。","respondent":"東野福祉計画課長","answer":"こういったことに対応するためにスライドなども使って、出資計画などを確認した上で、選定を行っていきたいと思っているところです。その辺も踏まえて、今後施設計画をどうしていくかについては、区全体として考えていければと考えています。","id":"exchange-033"},{"speaker":"石田（秀）副委員長","kind":"質問","question":"東京都もこのような制度をやっているわけですから、この１０億円の差、運営で入ってくる金は決まっているわけです。お願いをしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"}]},{"id":"topic-03","title":"品川区立八潮在宅サービスセンターおよび品川区立八潮わかくさ荘ほか６施設の指定管理者候補者の公募","agenda":"品川区立八潮在宅サービスセンターおよび品川区立八潮わかくさ荘ほか６施設の指定管理者候補者の公募","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"３年間ほとんどのところが赤字続きというような状況になっていたと思うのですが、何というのですか、そのような対応というものはどのように考えられているのか説明を求めました。","respondent":"菅野高齢者福祉課長","answer":"大体国の福祉支援機構の調査などによりますと、デイサービスの場合は、黒字にはならないのではないかというような分析結果も出ております。その辺りのところは、区としては一定の金額をお支払いしつつ、在宅サービスセンターを運営していただけたらと思っているところです。","id":"exchange-035"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"ひがし委員","kind":"質問・要望","question":"緊急医療救護所７か所中２か所、例えば令和７年度にあと何か所やるなど、そのような想定もありましたら教えてほしいと求めました。１９時以降から朝の８時、９時になるまでの時間帯の対応というところを説明を求めました。","respondent":"遠藤健康推進部次長","answer":"このような方が来たらどうしますかというようなことを動いたときに、どうやって対応していくかと、要するに具体的なものがなかなか出てこないと。そちらのほうをもう少し延ばすなどというようなことも考えられるかなと思いますので…","id":"exchange-036"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ぜひ、例えばどこの学校救護所であっても同じような対応が受けられるというように周知と訓練、進めていただきたいなと思っています。ぜひ私も見に行かせていただきたいなと思いますし、この点については改めて別の機会で質問させてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-037"},{"speaker":"鈴木委員","kind":"質問・要望","question":"これ７か所ということで、多分医療機関の職員が７２時間はこちらに、そこの確認も改めてさせてほしいと求めました。学校医療救護所というものも、自分の診療所等の開設と、この救護所の体制をどう取っていくのかというようなところもご説明お願いします。","respondent":"遠藤健康推進部次長","answer":"こちらについては、今のところ公表の予定は考えていないところです。それぞれに駆けつけていただくというような形で考えて、それに合わせてということで考えているところです。","id":"exchange-038"},{"speaker":"鈴木委員","kind":"質問","question":"７か所の、７か所のところにはどのクリニックのどの先生はここに行くとか、その点についても伺います。","respondent":"遠藤健康推進部次長","answer":"例えば医師会であればそれぞれで、いわゆるどこの方はここに行くのだという一覧をつくっていただいている形でやっているところです。それは先ほどのコーディネーターが調整して、割当といいますか、混乱のないように動くという形になっているところです。","id":"exchange-039"},{"speaker":"鈴木委員","kind":"質問・要望","question":"その辺のところの周知の仕方というものはどこまでいっているのかということを伺いたいということと、医療施設にあるようなものはないではないですか。１３か所で医院を、何か実際問題合理的なのだろうかという疑問があるのですけれども、そのような点については課題というものはないのか尋ねました。","respondent":"遠藤健康推進部次長","answer":"７２時間から１週間という形にはなっていますけれども、その辺は実際の状況を見ながらというところで、恐縮です。この１３から増やしたらいいのかというところでも、またちょっと違うのかなと思っているところですので、現状ではこのようなところです。","id":"exchange-040"},{"speaker":"鈴木委員","kind":"確認","question":"そのような使えるところは使っていくというところは柔軟にやっていくという考え方でいいということですか。本当にこれで実際問題どうなのだろうかというような思いがしたのですけれども、ちょっと改めてそこの確認をさせてください。","respondent":"遠藤健康推進部次長","answer":"そこは柔軟といえば柔軟なのでしょうけれども、ある程度７日間というめどを持ってやらせていただくというように考えているところです。ちょっと診療機関の数は、すみません、申し訳ございません。","id":"exchange-041"},{"speaker":"渡辺委員","kind":"質問","question":"事務、やはり全国からも救援の方がいらっしゃったときの受入れの体制が効果的でないと意味がないということを当時の委員長がおっしゃったのです。このＤＭＡＴの受入れという意味での考え方が１つ、教えてもらいたいということと、まずはそちらをお願いします。","respondent":"遠藤健康推進部次長","answer":"こちらのほうから、そこから東京都に上がっていろいろと、品川区のほうにどのような方が派遣されるというような情報が下りてくるところです。こちらのほうでの訓練というものをやったことがないところでございまして…","id":"exchange-042"},{"speaker":"渡辺委員","kind":"質問","question":"計画の中で役職があったりするのですが、１ついいなと思って伺っていたことが、毎朝責任者が集ってミーティングをすると。部署であると思うのですが、総合的に心構えではないですけれども、考え方を説明を求めました。","respondent":"遠藤健康推進部次長","answer":"それの仕組みも学んでいるところですので、そのようないい部分というか、困った部分などいろいろこちらのほう共有しています。実際の災害時のいろいろ、また本部のお話かと思いますが、そのようなところでそちらのほういろいろと盛り込んでいければと考えているところです。","id":"exchange-043"},{"speaker":"やなぎさわ委員","kind":"質問","question":"令和６年度の訓練実績のところでお伺いしたいのですけれども、すみません、前提として少し勉強不足で申し訳ないのですが、こういった災害時は、健康保険証や保険証がなくても受診ができるのかどうか、まずそこをお伺いしたいと思います。","respondent":"遠藤健康推進部次長","answer":"当然なくなっている場面もあるかと思いますので、なしで対応するような形で考えているところです。","id":"exchange-044"},{"speaker":"やなぎさわ委員","kind":"質問","question":"それを踏まえた上で、今回の訓練というものは、そういった、例えばマイナ保険証のカードリーダーのようなものを設置して、何というのですか、そういったものを想定した訓練をしたのか、別にもうそれは一切保険証はない状態というものを前提として訓練を行ったのか、その辺もし分かれば説明を求めまし…","respondent":"遠藤健康推進部次長","answer":"今回についてはそのようなものは一切用意はしていない、想定はしていないという形で進めているところです。","id":"exchange-045"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"１点だけ。そことどのような連携を取るのかということが、もちろんあるのだと思うのだけれども、その辺を教えていただきたい。","respondent":"遠藤健康推進部次長","answer":"こちらの医療対策本部のトップといいますものが健康推進部長になりまして、部長が災害対策本部のほうにも参加することになっておりますので、そこでの情報共有という形になっているところです。","id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/238890?Template=document&Id=6939#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":38961,"voices":123}},{"id":"r07-20250120-8","meetingId":"r07-cm01","date":"2025年1月20日","dateIso":"2025-01-20","committee":"建設委員会","time":"午後 １時００分～午後 ４時１５分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を63件整理しています。","topics":[{"id":"topic-01","title":"第６回羽田新経路の固定化回避に係る技術的方策検討会","agenda":"第６回羽田新経路の固定化回避に係る技術的方策検討会","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"それと、安全性が軽視につながってしまうと困るというところで、そうした安全性の点ではどうなのかというのを伺いたいと思います。それが何人ぐらい配置されるものなのか、１滑走路に１人ずつみたいな感じなのか、その辺りを伺いたいと思います。","respondent":"高梨都市計画課長","answer":"区といたしましては、羽田空港の運用に関する大前提であると考えていますので、全てにおいて優先されるべきものであるという認識です。対応機材の海外の対応率ですが、こちらも説明を受けてはございませんが、国の資料によりますと…","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"そういったところも区として、安全性がしっかり担保されるように、国に求めてほしいと求めました。そうした中で申入れを出したというところを伺いたいのと、区の求める具体的な方策というのは何なのか、伺いたいと思います。","respondent":"高梨都市計画課長","answer":"第６回検討会におきましては、この検討会において、区民負担軽減につながる具体的な方策の提示とその実施について。今回の検討会でも当然、方策の提示とその実施を期待していたところですが、第６回の検討会では、それが示されなかったです。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"区の求めていたものが示されなかったということで、そこの確認をさせていただきたいのと、実施可能回数に限りがあり。その間は今の運航が実施をされ続けてしまうということになってしまうと思うのですが、区の認識を伺いたいと思います。","respondent":"高梨都市計画課長","answer":"今回示された方式では不十分と考えているかという最初のご質問ですけれども、区はこれまで、具体的な方策の提示とその実施を求めてきたところです。時間がかかる等々の課題に対する区の認識についてですが、区としては…","id":"exchange-003"},{"speaker":"のだて委員","kind":"提案","question":"いいのかというところを伺いたいのと、回避ができないということが明らかになったのではないかと思うのですが、いかがでしょうか。それを固定化することになると思うのですけれども、いかがか尋ねました。","respondent":"高梨都市計画課長","answer":"１年以内に検討会を開催するということも会議の中で発言があったと聞いてありますので、しっかりと検討を進めて、一刻も早く。課題が幾つかありながらも、この方式を用いるとどういったルートになるのかというような一歩進んだ検討も含めて、国により鋭意検討を進めてほしい。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問","question":"資料１の１２ページの一番下のところで、今回のＣ滑走路の方式だということですから、Ａ滑走路については固定化されてしまうということだと思います。そうしたことが、根本的に解決をしていくということになると思いますが、いかがか尋ねました。","respondent":"高梨都市計画課長","answer":"国から具体的なルート案について示されていなく、区としても聞いているところではございません。国としてしっかりと検討して、それが示され、実施されることを求めていく考えです。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問・要望","question":"この羽田新ルートに、区としてもそれを求め、反対をしていっていただきたいと。これは要望しておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"ただ、改めて区長の名前で申入れが行われたということですので、現時点での区の立場を含めて、いろいろ伺いたいと思います。２５日に申入れを行ったということで、どういう内部的な検討、この申入れに至ったのかという経過を伺いたいと思います。","respondent":"高梨都市計画課長","answer":"検討会が開催されることは２０日の段階で把握をしていますので、翌２５日、相手先の部長宛てに直接申入れ書を提出させていただいたと。２４日の検討会の開催後と２５日の申出の終了後にも、ＨＰになりますけれども、事実関係についてご報告をさせていただいたところです。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"具体的な方策の提示と実施を求める、そこの内容も確認させてほしいと求めましたが、いかがでしょうか。もう１点伺いたいのは、区民負担の軽減の質疑の中で、騒音の軽減を検討してほしいというご説明がありました。","respondent":"高梨都市計画課長","answer":"この間２年以上、第５回から間が空いて、区長の思いとともに文章とさせていただいたところです。２点目の、検討会によって区民負担軽減につながる具体的な方策を考えていただきたいという態度には変わりはございませんけれども、払拭するように。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"現時点でも、先ほど課長もおっしゃった騒音の軽減、落下物の危険の払拭というか対策は、国が考えることなのだという立場なのか、確認させてください。私はいずれにしても、これまでも述べてきたとおり、従来の海上ルートへの変更以外に解決策はないと思いますが、この点もいかがか尋ねました。","respondent":"高梨都市計画課長","answer":"その解決に向けての今後の取組について、海上ルートも含めた検討、海外事例等も勘案した上での検討を継続していくと記載をしています。検討会において、区民負担軽減につながる方策の検討をしっかりと行っていただいて、実施に移していただきたい。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"従来の海上ルートへの変更を求めるのだという立場を表明されないわけですから、この申入れ書からも、いかがでしょうかということです。従来の海上ルートに戻してほしいと言うべき立場が品川区長に求められるのだということは、この間も述べてきたし、今でもそう思っております。","respondent":"高梨都市計画課長","answer":"区から申し上げることはできませんけれども、まず区としましては、区民の声をしっかりと国に対して届ける。そこが品川区として一番大事なところではないかと考え、今までも国に対して声を届けてまいったところです。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"最も地上を低く飛ぶのが品川区ですから、国の対応は本当にひどいと思いますけれども、少しでもぴりっとするような環境にもつながってくるのかなと。質問としては、これで最後にしますけれども、最後にここだけ確認させてほしいと求めました。","respondent":"高梨都市計画課長","answer":"今、委員ご案内の文面で、これまで要望という形で国に文書で届けたことはございません。区としましては、地元自治体である品川区民の声をしっかりと重く受け止めていただいて、国の責任において検討されるべきと考えているところです。","id":"exchange-011"}]},{"id":"topic-02","title":"令和７年２月都営住宅入居者募集","agenda":"令和７年２月都営住宅入居者募集","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"いつも伺っておりますが、直近の募集戸数と応募倍率を伺いたいと思います。エアコンとか給湯器がついていないところがあると伺ったのですけれども、そのことが分かれば伺いたいのと、分かれば伺いたいと思います。","respondent":"川原住宅課長","answer":"前回が令和６年８月になるのですけれども、令和７年２月の募集開始時なので、あとはプレスの発表日以降に掲載予定です。資料の記載につきましては、前回の区営住宅同様、今までの過去の資料での掲載はありますというところで、口頭でのご回答とさせていただきました。","id":"exchange-012"},{"speaker":"のだて委員","kind":"質問・要望","question":"そういうことになると思いますので、区としてもエアコンとか給湯器設置に向けて、支援を東京都に求めてほしいと求めました。それと、区営住宅ではどうなっているのかなというのも思いまして、それに対する支援というのがあるのかどうかも含めて伺いたいと思います。","respondent":"川原住宅課長","answer":"都営住宅への困窮者、要配慮者の入居に伴って、そういった対策・対応、エアコンや給湯器の設置を都に求めてというところから回答します。もともと区で設置をしたものであるとか、どの住居に関しましても、１部屋分のエアコンのコンセントは確保してあるところです。","id":"exchange-013"},{"speaker":"のだて委員","kind":"質問","question":"最後、すみません、エアコンのところがよく聞き取れなかったのですけれども、１部屋分のコンセントはあるという話だったのですか。だから、エアコン自体はないということなのか尋ねました。","respondent":"川原住宅課長","answer":"そういった設置も含めて、ご自身で設置いただく必要はあるのですけれども、低廉化家賃使用料というところでは、価格を下げてのご提供です。区営住宅に関しては、１部屋分のコンセントの用意というところはできている状況です。","id":"exchange-014"},{"speaker":"のだて委員","kind":"質問・要望","question":"気候危機の問題でも、エアコンがないと暮らしていけない状況になってきていると思いますので、そこは設置をするようにしていただきたいと。区が設置するようになるべきだと思うのですけれども、ぜひそれを検討してほしいと求めましたが、いかがか尋ねました。","respondent":"川原住宅課長","answer":"先ほどのご質問のエアコンのコンセントの設置状況につきましては、そのほか、建設の年度によって異なるところもあるかと思います。ご意見をいただいているものについては真摯に受け止めて、協議というか、検証は必要であると区は考えております。","id":"exchange-015"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、もし課題が具体的にあれば、伺いたいと思います。受けていない人も含めて、エアコンというのは普通にアパートでもあるものですから、区営住宅へもぜひつけていただきたい。","respondent":"川原住宅課長","answer":"例えば３ＤＫで３個あるときに全部つけてしまうと、全体の住居、一つの建物に対する電気の容量がどうかといったところの問題もあると伺っているところです。","id":"exchange-016"}]},{"id":"topic-03","title":"東海旅客鉄道（株）に対する目黒川で発生した気泡への対応要請","agenda":"東海旅客鉄道（株）に対する目黒川で発生した気泡への対応要請","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"率直に伺いたいのが、区長名でなく部長名なのはなぜなのかというところを伺いたいと思いました。そういう認識の下で原因究明を求めたということでよいのか、要請書の中身について、区の認識も併せて伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"１点目です。気泡の発生とシールド掘進に明確な関係性は見られないというＪＲ東海の説明があったとおりでございまして、あと説明会での状況等を踏まえまして。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"私が伺ったのは、令和６年１２月１９日に部長名で提出を行ったのですが、対応を求めたということなのか。区としては、そこは明確にしていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"大石まちづくり立体化担当課長","answer":"区としてしっかりと発信することが大事と考えておりますので、区長ではなくても、文書の重みとしては一緒だと考えているところです。原因究明されていないという区の認識なのかですけれども、そういった声を受けて、改めて原因究明を区として求めたところです。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"相手に原因究明を求めると私は考えるのですけれども、原因究明がされていないという立場や認識を表明されない理由は何なのか、伺いたいと思います。そこも併せて伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"説明会でも質問の中でもかなり多くの質問が出ていたというところを踏まえまして、区といたしましても、そういった認識です。因果関係をしっかり求めるですけれども、原因が一定究明されれば、因果関係も明らかになってくるのかなという認識です。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"別紙２の区の対応についての回答が今日の資料に寄せられているわけですけれども、伺いたいのは、ＪＲ東海は何と回答したのか。私は全くのゼロ回答だと思っているのですけれども、そこについてもご説明ほしいと求めました。","respondent":"大石まちづくり立体化担当課長","answer":"回答内容にあります調査の追加の検討につきましては、先日の説明会等でも今回、一定前向きな回答として受け止めているところです。調査の追加というところもありますので、まずはそこの状況、対応をしっかりと注視していきたいと考えています。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"改めて伺いますけれども、この回答で気泡の原因は明らかになったのか。引き続き区としては原因究明を求めていくという立場を表明すべきだと思うのですけれども、いかがか尋ねました。","respondent":"大石まちづくり立体化担当課長","answer":"繰り返しになりますが、調査の追加も検討するということで一定回答もいただいているところですので、区といたしましては、どのような調査がされるのか、その辺の報告を待って、そこの状況をしっかりと踏まえて今後の検討を考えていきたいと考えております。","id":"exchange-021"},{"speaker":"中塚委員","kind":"質問","question":"原因が明らかにならない中で、工事は進めるべきではないと。リニア工事そのものを一旦中止すべきだということを区は表明して、ＪＲ東海にも伝えるべきだと思いますが、最後にいかがか尋ねました。","respondent":"大石まちづくり立体化担当課長","answer":"リニア中央新幹線につきまして、ＪＲ東海が国土交通大臣から認可を受け、ＪＲ東海の責任の下で実施されている事業です。調査の追加の検討、こちらの状況を踏まえまして、引き続きＪＲ東海の対応を注視してまいりたいと考えているところです。","id":"exchange-022"},{"speaker":"のだて委員","kind":"質問・要望","question":"もしあったらご説明ほしいと求めましたが、なぜ今回、回答があったのかというのを伺いたいと思います。今まで示されている、説明会でも示された内容のものと理解していいのでしょうか、伺います。","respondent":"大石まちづくり立体化担当課長","answer":"先ほども申したとおり、説明会で説明がなされなかった調査の追加の検討というところが、一つ実績としてあるのかなと考えているところです。オープンハウス型説明会等、説明会で示されたところで、説明がなされるものと認識しています。","id":"exchange-023"},{"speaker":"のだて委員","kind":"質問・要望","question":"酸素濃度が４％だということが分かったわけですけれども、そうしたことも含めて検証していくべきではないかと思うのですけれども、いかがでしょうか。ぜひ区としても出すように求めてほしいと求めましたし、区民にもぜひ公表してほしいと求めましたけれども、いかがか尋ねました。","respondent":"大石まちづくり立体化担当課長","answer":"一つは、適時適切な情報発信というものを１１月の要請書でも求めているところですので、しっかりと引き続き求めていきたいと考えているところです。２点目の調査結果の詳細ですが、繰り返しになりますけれども、工事に関する情報の適時適切な情報発信を求めているところです。","id":"exchange-024"},{"speaker":"のだて委員","kind":"質問・要望","question":"引き続き、リニアと気泡の関係、原因究明を求めてほしいと求めました。その原因が分かるまでは、リニア新幹線工事を中止すべきだということも、ぜひ一緒に求めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"えのした副委員長","kind":"質問","question":"そこで１２月２９日、迅速に区からの要請書ということで、部長名で申入れをしていただいたご対応に感謝を申し上げます。そこから約１か月たっておりますけれども、区として目視なり、現状、その辺の地域の方のお声があったとか、そちらをお聞かせ願えますか尋ねました。","respondent":"大石まちづくり立体化担当課長","answer":"区民からの問合せにつきましても、区では一切受けておりません。１件もないです。","id":"exchange-026"},{"speaker":"えのした副委員長","kind":"意見","question":"本日もご対応いただいたということで、また引き続き、雨ではない天気の日も、気泡が小さくなったのか、出てこないのか、目視で地域の安全、区民の方の安心・安全のためにご対応ほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"のだて委員","kind":"質問・要望","question":"教室型説明会もやってほしいという声も出ておりますので、そうしたこともＪＲ東海に区として求めてほしいと求めましたが、いかがか尋ねました。","respondent":"大石まちづくり立体化担当課長","answer":"オープンハウス型説明会ですけれども、ＪＲ東海からは、本掘進の開始前や掘進時期に合わせて、順次オープンハウス型説明会を開催予定と聞いてあります。","id":"exchange-028"},{"speaker":"のだて委員","kind":"質問・要望","question":"そこをぜひ、町域ごとに教室型説明会をということで、陳情なども区議会にも出ているわけですし、さらに説明の場を充実させていくという立場で区としても対応してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"}]},{"id":"topic-04","title":"品川区水辺利活用推進計画（素案）に係るパブリックコメントの実施","agenda":"品川区水辺利活用推進計画（素案）に係るパブリックコメントの実施","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"この計画は再開発のグレードを上げるためのものなのかと伺いたいと思います。２点伺いたいと思います。","respondent":"北原河川下水道課長","answer":"そちらについては、骨子の段階でもご説明させていただいているところですが、これによって開発が進んでいくという計画ではございません。こちらの計画が開発を進めるための計画ということではございませんので、基本的に、連携という趣旨のものではございません。","id":"exchange-030"},{"speaker":"中塚委員","kind":"質問","question":"そんな再開発のグレードアップのために、なぜこんな計画が必要なのかと思いますけれども、いかがでしょうか。Ｐ２１ページの方針３、まちづくり計画との連携が新規で載っているわけですから、それぞれいかがか尋ねました。","respondent":"北原河川下水道課長","answer":"例えばライトアップの実施であったりとか、先ほどもご説明したように東品川海上公園での非動力船の活用促進であったりとか、あと。そうすることによって、今回の計画の策定を進めているものでございまして、そこについてはご理解いただきたいと思います。","id":"exchange-031"},{"speaker":"中塚委員","kind":"質問","question":"どう見ても、まちづくり計画との連携が新規に書いてあるのですから。地域というと住民みたいなイメージを持つけれども、さっきもお認めになったように、大崎エリアマネージメントが入っているわけですから。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"},{"speaker":"澤田委員","kind":"質問","question":"地域の活性化や区民のシビックプライドの醸成など、大変大切なものであり、そのための推進計画は本当に重要であると考えています。それとも団体を対象とか、何か考えていらっしゃることがあれば、対象を説明を求めました。","respondent":"北原河川下水道課長","answer":"この間、骨子を作成後、地域の団体、例えば旧東海道品川宿周辺のまちづくり協議会等、地域の団体には個別にヒアリングを行ってまいりました。そういったところですので、今回は一般の方から広く意見を募るという趣旨で考えてあります。","id":"exchange-033"},{"speaker":"澤田委員","kind":"質問","question":"今回は一般の方というところで伺っているのですけれども、若い方の意見というのがより集まるかなと思うのですが、その辺りについてはどうお考えか尋ねました。","respondent":"北原河川下水道課長","answer":"現状、ＳＮＳを活用した周知というのは考えていなかったところですが、ただ、今回ご意見いただいたこともありますので、ほかの計画等のやり方も含めて、勉強させていただきたいと考えていますので、ありがとうあります。","id":"exchange-034"},{"speaker":"のだて委員","kind":"質問","question":"桜の維持管理を進めていくということも書いてありますけれども、現状は桜の木は結構傷んでいるという状況なのか、現状を伺いたいと思います。それと、橋梁のライトアップの新たな演出を検討するということですけれども、これもどういうものなのかというのを伺いたいと思います。","respondent":"森道路課長、北原河川下水道課長","answer":"区内で１,１００本ぐらい桜があるのですけれども、古くに植えられたものも多くあります。伐採をして、また新たに植え替えるということを継続してやっておりますので、引き続きそれを進めてまいりたいと考えております。 １点目、東京都が主に実施をしてございまして、５年に１回程度の周期で実施をしています。いろいろ考慮したライトアップの在り方を検討していければと考えていますが、今後、詳細については詰めてまいりたいと考えています。","id":"exchange-035"},{"speaker":"のだて委員","kind":"質問・要望","question":"フェーズ２以降になると、フェーズ２以降になったときに、そこを伺いたいと思います。繰り返し求めておりますが、説明会を実施すべきだと思いますけれども、いかがか尋ねました。","respondent":"北原河川下水道課長","answer":"河川管理用通路の通行ルール等の改善について検討していくという記載も、安全の面もしっかりと考慮しながら進めていきたいと考えています。区民の方の理解を得るために説明会を行うべきではないかですが、現在のところ、説明会の開催までは考えてございません。","id":"exchange-036"},{"speaker":"のだて委員","kind":"質問・要望","question":"フェーズが変わっても意見交換をやっていくものだということでいいですかという確認と、あと転落防止柵とかは、先ほども質疑がありましたが。それと説明会も、どういった形で周知したらというお話だったので、ぜひ説明会の実施も検討していただきたいと、改めて求めておきたいと思います。","respondent":"北原河川下水道課長","answer":"推進会議につきましては、メンバーが実務担当者というところで、意見交換会という趣旨です。本計画については、再開発のために策定している計画ではございませんので、改めてお伝えさせていただきたいと思います。","id":"exchange-037"},{"speaker":"横山委員","kind":"質問・要望","question":"推進計画素案の３０ページ、あと３４ページに少し関わってくるのですが、３０ページの公共交通との連携。ぜひ今後進めていただきたいという思いがありまして、お聞きするのですけれども、現状と今後の考え方について説明を求めました。","respondent":"北原河川下水道課長、大友公園課長","answer":"区有船着場の周辺については、案内板を７か所全てに設置しています。引き続き、水辺の部門としてできることは進めていきたいと考えております。 水族館の無料案内バスが公共の乗換え案内等に出てこないというところについては、改善点として受け止めたいと考えています。ご意見ありがとうございました。","id":"exchange-038"},{"speaker":"横山委員","kind":"質問・要望","question":"こういった一般の方に向けてのパブリックコメントというところは大変重要になってくるかと思いますので、ぜひ様々な意見を引き続き拾っていただいて、水辺の利活用の推進につなげてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-039"},{"speaker":"つる委員","kind":"質問","question":"水辺で、担当地域が荏原地域で、なかなか水辺に触れる機会がなくてという話は毎度するのですけれども、そういう中で、そもそも品川というのはどこにあるのか尋ねました。","respondent":"北原河川下水道課長、高梨都市計画課長","answer":"品川については、２３区の中でも東京湾に面しているエリアというところで、城南のエリアという認識です。すみません、答えになっているかどうか。 品川の語源というところで受け止めをさせていただきましたけれども、古い資料によりますと、目黒川の古名であると把握をしています。","id":"exchange-040"},{"speaker":"つる委員","kind":"提案","question":"ある議員から、品川区の区部にある目黒川のところを、品川と愛称変更したらどうかと提案があったわけです。そういう質問もかつてあったわけなので、どのように考えて当時研究されたのか、説明を求めました。","respondent":"北原河川下水道課長","answer":"筑後川や利根川とか吉野川なんかが３大暴れ川と呼ばれていたりとか、地元で親しまれて、それが浸透していくというのが一般的なのかなという認識です。そういった取組を進めていく中で、品川区における河川とは何ぞやという部分も、引き続き研究してまいりたいと思います。","id":"exchange-041"}]},{"id":"topic-05","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"その理由を伺いたいと思います。ここを言わば柱に据えた理由を伺いたいと思います。","respondent":"川原住宅課長","answer":"令和６年５月に住宅セーフティネット法の改正というところでも、そこは住宅部門だけではなくて、共に実施をしていく必要があると認識をしています。この居住支援事業はもともと民間賃貸住宅の入居の促進というところもございまして、空き室が一定戸数あるというところが…","id":"exchange-042"},{"speaker":"中塚委員","kind":"質問・要望","question":"もっと増えればいいのにというお話を伺いますし、高齢者のところでは、区営住宅の役割はますます増えていると思います。もう少し今後の中身を伺えたらと思うのですけれども、ここまで踏み込まれたことを歓迎したいと思います。","respondent":"川原住宅課長","answer":"保険の内容の中身を検討するに当たっては、事前にこういった保険を積極的に取り入れている、ヒアリングをオンラインなどで実施させていただきました。オーナー側にとって必要なところ、必須なものは何かというところも含めて、検討をしています。","id":"exchange-043"},{"speaker":"中塚委員","kind":"質問・要望","question":"どのように位置づいているのか、まずはきめ細かくヒアリングをしてほしいと求めましたが、いかがでしょうか。どんな困り事に対して支援をしていきたいと思っているのか、今後の方向性も聞きたいと思いますので、ご説明いただけたらと思います。","respondent":"川原住宅課長","answer":"まだこれも検討中の段階なのですが、その辺りは協議をしながら、引き続き検討してまいりたいと考えています。特殊清掃などは、そういったところを保険の検討のメニューにできるか現在検討中ではありますが、考えているところです。","id":"exchange-044"},{"speaker":"中塚委員","kind":"意見","question":"現実の問題を何度も経験していると難しいというところが、今おっしゃった残置物の処理の問題や清掃のこと、ご説明あったとおりだと思います。両方に耳を傾けていただいて、具体的な支援策を形づくって進めていただけたらと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-045"},{"speaker":"のだて委員","kind":"質問・要望","question":"区のお考えを伺いたいと思います。居住支援協議会が昨年７月に行われて、５年間の間にマイナス０.８％減少したということなのですけれども、区としての認識を伺いたいと思います。","respondent":"川原住宅課長","answer":"保証人制度の在り方というところも新たに国から示される予定ですので、そういったスキームについては情報収集に努めてまいりたいと考えています。資料の出どころが令和２年の調査ですので、今も力を入れておりますが、実施をしていきたいと考えています。","id":"exchange-046"},{"speaker":"のだて委員","kind":"質問・要望","question":"高齢者の住みにくさという点では、傾向がどうかというのは分かりませんけれども、そうした支援が実際に求められているものだと思っているところです。専用住宅への登録を進めていくと同時に、登録住宅も家賃補助の対象にしていくということが必要ではないかと思うのですけれども、いかがか尋ねました。","respondent":"川原住宅課長","answer":"調べているところではありますので、そういった施策についても、専用住宅にできないかといったところは引き続き検証してまいりたいと考えています。そういった働きかけを、区でも行っていく必要があるというところは認識しています。","id":"exchange-047"},{"speaker":"のだて委員","kind":"質問・要望","question":"高齢者とか障害者の方に対する家賃補助というのを、ぜひ実施していってほしいと求めましたけれども、伺いたいと思います。そうであるなら、借り上げの公営住宅を提供していくということも一つの手なのかなと思いますが、いかがか尋ねました。","respondent":"川原住宅課長","answer":"はそういった、特に配慮を要する方々の支援というところの施策を展開していくことが先決だと考えていますので、現在のところ考えてはおりません。公営住宅の増設、まずは民間の賃貸住宅の促進というところをしっかりと行っていきたいと考えていますので…","id":"exchange-048"},{"speaker":"のだて委員","kind":"質問・要望","question":"借り上げ公営住宅も含めて、ぜひ検討して進めてほしいと求めました。最後に伺いたいと思います。","respondent":"川原住宅課長","answer":"借り上げの高齢者住宅は実施していますが、全体の抽せんを実施するのではなく、困窮度によって入居者を決めていくものです。そういったそれぞれの役割分担を果たしながら区としては実施していきたいと考えています。","id":"exchange-049"},{"speaker":"横山委員","kind":"質問・要望","question":"少し確認と、教えていただきたい部分があるのですけれども、どういった現状になっているのかというのを確認させていただけたらと思いました。","respondent":"川原住宅課長","answer":"実際に月１回、訪問を行ってくださっているのが、社協に籍を置く高齢者のボランティアの方が訪問を行ってくださっているところです。しっかりと法人化して、施策で反映をしていきたいと考えているところです。","id":"exchange-050"},{"speaker":"横山委員","kind":"質問","question":"２事業者が指定に向けて、こちらの２事業者というのは、何か専門性があったりされるのでしょうか。そういった枠組みも用意されているというお話があったのですけれども、区においてのその辺りの現状について説明を求めました。","respondent":"川原住宅課長","answer":"もう１事業者は不動産事業者なのですけれども、住宅確保要配慮者をまさに得意とする事業者が検討して、都と協議を行っていただいているところです。より幅広い要配慮者の住宅支援を行っているですが、現在品川区においては、こういったところについてはまだ実施をしてございませ…","id":"exchange-051"},{"speaker":"横山委員","kind":"質問・要望","question":"居住のサポートが必要な方に手厚い支援が行われるように、区としても進めていっていただくのかなと思いますので、お願いできればと思います。困っていらっしゃる方のお声ですとか、様々な先進事例の情報として捉えてほしいと求めましたので、要望で終わらせていただきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-052"},{"speaker":"つる委員","kind":"質問","question":"現在の例えば民間とか、公営でもいいのですが、孤独死による残置物について、区へ相談があった際に、お金がかかっているものがあったとすれば、幾らぐらいかかっているのか、区の負担額が分かれば説明を求めました。","respondent":"川原住宅課長","answer":"申し訳ありません、区営住宅や公営住宅では、年に１回そういった事例があるかどうかです。これは清掃代のみというところですので、これにさらに内装リフォーム代であるとか、畳があればその張り替え代というと、別途費用がかかっていくです。","id":"exchange-053"},{"speaker":"つる委員","kind":"質問","question":"孤独死の発生率みたいなものが、公民両方合わせて、分かれば説明を求めました。","respondent":"川原住宅課長","answer":"分母の部分が分かりかねるところであるのが大変恐縮なのですけれども、公営住宅で私が把握している限りだと、年に１回あるかどうかです。昨年度は１件ございました。","id":"exchange-054"},{"speaker":"つる委員","kind":"質問","question":"いわゆる事業者の単価が、先ほどおっしゃっていただいたような、清掃に限って言っても６０万円から７０万円ぐらい。そこが住めるようにしていくまでかかる経費というのは、１件当たり都合どのぐらいかかるのか、説明を求めました。","respondent":"川原住宅課長","answer":"区が勝手に手を入れることができませんで、戸籍を追うところから始まりますので、非常に時間が長くかかります。１年近くかかっているケースもありますので、費用もさることながら、非常に期間も要するといったところです。","id":"exchange-055"},{"speaker":"つる委員","kind":"質問","question":"１戸当たりの保険料単価は非常に安かったわけですけれども、今のことを伺っていると、大きいリスクに備えられる。だけれども、さっき伺ったように１件だけでそれだけ費用がかかるということは、そこに保険を掛けていくメリットというのはあるのかなと思いました。","respondent":"川原住宅課長","answer":"１５０件程度と、まだ検討段階ではあるのですけれども、考えているところです。そういった家賃に対する補償につながる保険ができないかと検討しています。","id":"exchange-056"},{"speaker":"つる委員","kind":"質問","question":"名古屋にも伺ったのですが、区が２３区全体に声かけして、そういったところは保険会社のほうで対応できるのかどうか。この辺り、もし検討されている中で、情報提供されていれば説明を求めました。","respondent":"川原住宅課長","answer":"区のオーダーに応じてオーダーメードの保険というところを見積りとして考えていてくださっているもので、把握しています。ほかの自治体との把握の状況というところでよろしいでしょうか。","id":"exchange-057"},{"speaker":"つる委員","kind":"質問","question":"ほかの自治体と一緒にできるかどうかとか、保険会社で保険商品として用意されているかどうか、そういった話があるのかなと。名古屋市で伺ったときには、ほかの自治体でも契約している例が幾つかあるので、全国に広がれば保険料額が抑えられるのではといった話はあった。","respondent":"川原住宅課長","answer":"そういったところは、今後いろいろヒアリングをする必要があるかなと考えています。どこかの自治体とセットでといったところは考えてございませんでしたので、その辺りは意見を、保険会社にも聞き取りをしていきたいと思います。","id":"exchange-058"},{"speaker":"澤田委員","kind":"質問・要望","question":"私からも幾つかご質問させていただければと思うのですけれども、ひとり親と障害者がすごく少ないという印象があります。なぜ少ないのかという原因など、考えられるところがあれば教えていただきたいことと、そういうこともあれば教えてほしいと求めました。","respondent":"川原住宅課長","answer":"より困窮度の高いひとり親家庭の方の支援というのは、今後も引き続き必要であると認識をしています。こうしたところは個別に支援が必要な部分であるかと思いますので、引き続き住宅課で行っていきたいと思います。","id":"exchange-059"},{"speaker":"澤田委員","kind":"質問・要望","question":"大家の理解というのも本当に大きな課題だと思いますので、ぜひその辺りもしっかりとやってほしいと求めました。もう１点伺いたかったのが、こちらも進めていただきたいのですが、区としてはどのようにお考えなのか尋ねました。","respondent":"川原住宅課長","answer":"保証会社の保証料がなかなか難しいという方への支援といったところではあります。そういった情報提供は、住宅課でまとめて行っているといったところです。","id":"exchange-060"}]},{"id":"topic-06","title":"その他","agenda":"その他","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"しっかり周知をしてほしいと求めました。それと関連して、要望することを検討するということでしたか、その検討状況というのは今どうなっているのかというのを伺いたいと思います。","respondent":"高梨都市計画課長","answer":"新駅の可能性の検討ということで、今年度も検討作業を行ってありますけれども、沿線における候補地を絞り込む。絞り込む地域の周辺におけるまちづくりの今後の検討に資する都市基盤の状況等の検討といったところを行っているところです。","id":"exchange-061"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、まだ要望するかどうかを検討中ということです。請願駅となると、区としての出費も多額になってくるということですので、それはやめるべきだということも求めておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-062"},{"speaker":"中塚委員","kind":"質問・要望","question":"区内７団体ありますし、社会福祉協議会との連携も含めて、交通弱者というか、不便を感じている方々は、特段周知は徹底していただきたいと思うのです。私の記憶では初めてではないかと思うぐらいですから、強めてほしいと求めましたけれども、いかがか尋ねました。","respondent":"高梨都市計画課長","answer":"１１月の運休に際しましてはご意見いただきまして、個別に所管へ直接、都市計画課から案内するということも前回やりました。今回も同様に、周知が漏れないように取組をさせていただければと考えています。","id":"exchange-063"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/109228?Template=document&Id=6937#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":53765,"voices":149}},{"id":"r07-20250120-9","meetingId":"r07-cm01","date":"2025年1月20日","dateIso":"2025-01-20","committee":"文教委員会","time":"午後 １時００分～午後 ３時００分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件整理しています。","topics":[{"id":"topic-01","title":"令和７年度新入学学校選択の抽選結果","agenda":"令和７年度新入学学校選択の抽選結果","exchanges":[{"speaker":"西村委員","kind":"質問・要望","question":"幾つかお伺いさせていただきたいと思うのですが、まず、今回、兄弟枠で漏れた方がいるのかどうかということをお伺いさせてほしいと求めました。その辺りの届いているお声やお考えがあればお聞かせほしいと求めました。","respondent":"柏木学務課長","answer":"いつまで待てばというと、なかなか難しいところではありますけれども、繰上げの期限は新１年生ですと１月末までです。お声はいろいろ頂いているところですけれども、申し訳ございませんけれども、繰上期限まではお待ちいただきたいと思います。","id":"exchange-001"},{"speaker":"西村委員","kind":"質問・要望","question":"住民基本台帳外の子を１人も受け入れられない感じになってしまうので、読み方があれば教えていただきたいのが１点です。お感じになっているところがあれば、こちらも説明を求めました。","respondent":"柏木学務課長","answer":"それと、３５人学級の影響です。今、何学級分という数字は持ってございませんが、影響は出ていると考えています。","id":"exchange-002"},{"speaker":"西村委員","kind":"質問・要望","question":"様々難しいところがあるのですけれども、特に一番初めにご答弁頂いた兄弟枠に関しては、親御さんのご不安も相当なものだと思います。今後抽選校をどうしていくかということもあると思うのですが、何とか兄弟ばらばらにならないようにしっかりとご検討ほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"山本副委員長","kind":"質問","question":"４学級１３０名の受入れを予定している中で、今のところ学区入学予定者が１５３名ということで、大幅に多い状況になっています。こちらの見通しはどのようになっていらっしゃるのか尋ねました。","respondent":"柏木学務課長","answer":"第三日野小学校は、小学校の時点から私立の進学の方が多い学校になりますので、その部分も考慮いたしまして、４学級で収まるという見通しです。現状、繰上げの状況等を見ましても、収まると考えています。","id":"exchange-004"},{"speaker":"山本副委員長","kind":"質問","question":"第三日野小学校は結構人数が増えていて、運動会でもグラウンドがいっぱいになっているような状況があります。学区等もエリアの中で増えている状況なのかなというところでご質問させていただきましたけれども、収まる見通しということでよかったです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"僕はうまく表現できないのですが、その辺はあらかじめ認識していただきたいというふうに、何らかの言葉を入れたほうがいいのかなというのが一つです。そちらのほうについては少し準備しているのかというところの二つをお願いします。","respondent":"柏木学務課長","answer":"学校案内等の表現につきましては、検討させていただきたいと思います。一番受入れで動くのが１月中旬から下旬にかけてという説明は、一応していますが、改めて文字のほうは少し検討させていただきたいと思います。","id":"exchange-006"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"大丈夫だというお話だったのですけれども、万が一のことに備えて、ぜひいろいろ検討しておいてほしいと求めました。これは要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"}]},{"id":"topic-02","title":"区立学校におけるいじめの重大事態の発生状況および調査結果","agenda":"区立学校におけるいじめの重大事態の発生状況および調査結果","exchanges":[{"speaker":"高橋（し）委員","kind":"質問","question":"全体的ないじめに対する考え方として、学校の教員、それから、子どもたちの受け止め方というのは、どのように変化しているのか。あるいはいじめはいけないのだという認識が浸透しているのか、そのようなところについて、センターとしてどのように把握しているかを説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"こういったものがいじめなのだという認識をしたり、子どもたちにとっても、着実にいじめについての理解は深まっています。先生方がしっかりと対応していくことで、こうした重大事態化を未然に防いでいただいていると捉えております。","id":"exchange-008"},{"speaker":"高橋（し）委員","kind":"質問","question":"今、センター長から教育委員会、そして、現場、子どもたちが変化してきている、重大性を認識して進められているというご説明を頂きました。今後、さらに周知して、本当にゼロになっていくように。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"}]},{"id":"topic-03","title":"自閉症・情緒障害特別支援学級の新設","agenda":"自閉症・情緒障害特別支援学級の新設","exchanges":[{"speaker":"西村委員","kind":"質問","question":"２点、お伺いさせてください。もう一点は、改めて、授業内容について伺いたいと思います。","respondent":"唐澤特別支援教育担当課長","answer":"通常学級が３５人学級であるのに対して、８人１学級という形になりますので、少人数の指導を行うところが違いとして挙げられます。自閉症・情緒障害特別支援学級の特徴として、自立活動指導は教育課程の中で実施していきますので、個別もありますけれども。","id":"exchange-010"},{"speaker":"西村委員","kind":"質問・要望","question":"宮前小学校のエリア外からわざわざここに送迎して通わせておられる保護者の方がいらっしゃるのかということをもう一度お伺いしたいと思います。今、保護者の方がすごく求められていることではないかなと思いますので、引き続きお願いしたいと思います。","respondent":"唐澤特別支援教育担当課長","answer":"対象児童につきましては、特別支援教室の対象とも重なっているところがありますので、学校では特別支援教室を利用しながら。個々の事案はあるのですけれども、丁寧に対応をしながら、円滑に進められるようにしていければと考えています。","id":"exchange-011"}]},{"id":"topic-04","title":"品川区こども計画（素案）に係るパブリックコメントの実施","agenda":"品川区こども計画（素案）に係るパブリックコメントの実施","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"これについては、なかなか時間がかかるということなのか、どうかを伺いたいのが一つです。その辺りのイメージがわくような、もう少し詳細な説明をお伺いしたいと思います。","respondent":"柴田子ども施策連携担当課長","answer":"では、この空いている間はどうなのだというお話なのですけれども、子どもの意見反映の機会の確保については、来年度から実施していく考えです。ベースとして考えておりますのが、今年度、２回実施いたしました区長とみんなのタウンミーティングというものです。","id":"exchange-012"},{"speaker":"あくつ委員","kind":"質問","question":"二つ伺います。その二つについて説明を求めました。","respondent":"柴田子ども施策連携担当課長","answer":"とりわけ区政との接点や区に意見を言う機会が少ないであろう小学校４年生から高校３年生というところが今回のメインの対象と考えております。小学校４年生で、ファシリテートできる、子どもの意見表明を支えるようなファシリテーターを入れて会議を進行していく考えです。","id":"exchange-013"},{"speaker":"あくつ委員","kind":"質問・要望","question":"少し立ち入ったことまで伺ってしまいましたが、全体の話の中から教えていただいてありがとうございました。それについても、何か方向性があるのであれば、教えてほしいと求めました。","respondent":"飛田子育て応援課長","answer":"地域の方でそのまま引き継ぎたいというところはそのまま継続していただいているので、微増かなということで４２か所と設定しているところです。希望する方がいらっしゃいましたら、子ども食堂ネットワーク事務局と連携しながら、一緒に協力して支援していきたいと考えております。","id":"exchange-014"},{"speaker":"あくつ委員","kind":"質問","question":"現状維持しながらマッチングして、増えていけば、ウェルビーイングに資するような形になるのかなというお考えだということでよろしいですか。もしご答弁があればお願いします。","respondent":"飛田子育て応援課長","answer":"子ども食堂というのは、地域の方がその地域のためにやりたいから実施している事業で、区の委託でも何でもないというものです。運営を支援していけるのか等、相談を含めて、区としてはバックアップしていきたいと考えております。","id":"exchange-015"},{"speaker":"西村委員","kind":"質問","question":"１点、お伺いします。品川区の子どもの増減の特徴や、ファミリー世帯の人口推計をどのように分析されておられるのかなというのを改めてお伺いできればと思います。","respondent":"柴田子ども施策連携担当課長","answer":"子どもの増減のところなのですけれども、概要資料にもお示しさせていただきましたとおり、推計としては伸びていくと見込まれております。申し訳ありません。","id":"exchange-016"},{"speaker":"西村委員","kind":"質問・要望","question":"ぜひそういったことを反映しながら作成ほしいと求めました。ありがとうございました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"せらく委員","kind":"質問・要望","question":"教えていただきたい部分があるのですけれども、子ども・子育て支援事業計画のほうは、今年度で計画期間を終えると確認いたしました。来年度からスタートしますと、子ども・若者計画のほうはどういった取扱いになるのか教えていただけますか。","respondent":"柴田子ども施策連携担当課長","answer":"令和９年度まで残っているのですけれども、第３章のところに全く同じ形ではないのですが、要素としては生きているという考え方で作成しております。今後も、子ども・若者計画というのは、このこども計画の中で生き続けているという位置づけとなっております。","id":"exchange-018"},{"speaker":"せらく委員","kind":"質問","question":"「就く」というのは勤務するという意味かなと思うのですが、ここだけ漢字なのは引用データだからなのですか。少しお聞かせいただけますか。","respondent":"柴田子ども施策連携担当課長","answer":"ただいまご指摘いただきました７４ページ、下段の関連データのグラフでしょうか。","id":"exchange-019"},{"speaker":"せらく委員","kind":"確認","question":"ご確認いただきますよう、よろしくお願いいたします。ほかにもいろいろ細かく聞きたいなと思うところがあるのですけれども、個別でお伺いしていきたいと思いますので、今日は大丈夫です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"あくつ委員","kind":"質問・要望","question":"工夫というか、手続の簡略化以外の工夫のところをもっと教えていただきたい。令和１１年度まで年々増えているのですが、この辺りの見方について説明を求めました。","respondent":"染谷子ども家庭支援センター長","answer":"そういったところの工夫をしていきたいと考えております。会員数を増やしていくことを一つの目標とする中で、活動実績についても、それに応じて増えてくるというところを想定した数字となっております。","id":"exchange-021"},{"speaker":"あくつ委員","kind":"質問","question":"先ほどおっしゃられた報酬を増やすということと、自宅外での活動をしやすくするというところは、確かに前にご答弁で伺ったことがあると思うのです。先ほどもご答弁があったからいいですが、これから増やしていく、増やす結果が出るということでしょうから、非常にいい目標だなと思います。","respondent":"染谷子ども家庭支援センター長","answer":"先ほどの工夫の見直しの部分ですが、令和７年４月１日以降、予算措置された段階で順次実施していきたいと考えております。","id":"exchange-022"},{"speaker":"山本副委員長","kind":"質問・要望","question":"どのような効果を考えているかということを少し教えてほしいと求めました。大きな一つの計画になるわけなのですけれども、この計画をどういった方々に見てもらいたいか、伝えたいかというところについてもお教えください。","respondent":"柴田子ども施策連携担当課長","answer":"子ども版の策定も予定しておりまして、出来上がりましたら、子どもたちのタブレットに格納していく考えです。それから、地域の皆様、子どもたちのために区内で活動していただいている団体の皆様にも幅広く届けたいと考えています。","id":"exchange-023"},{"speaker":"山本副委員長","kind":"質問・要望","question":"ご説明いただいたこども会議のところは、子どもの意見を反映していくというのはとても良い取組だと思いますし、ぜひ進めてほしいと求めました。いろいろな意見を言いたいという思いも強まると思うのですが、この辺の仕組みについてお考えがあれば、お聞かせほしいと求めました。","respondent":"柴田子ども施策連携担当課長","answer":"こども会議は３回実施する考えで、今、検討しております。実現させて、子どもたちに達成感を得てもらうといったことができればと考えております。","id":"exchange-024"},{"speaker":"山本副委員長","kind":"質問・要望","question":"取組の熱も入ると思いますので、ぜひそういったビジョンを示して、子どもたちに様々な意見を言う機会を設けてほしいと求めました。それ以外の個別の内容については、また、別の機会を通じてご質問等をさせてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"高橋（し）委員","kind":"提案","question":"事務局の方が中心になって管理し、委員の方に提案してやっていくと思うのですが、その辺りをよろしくお願いします。これは要望ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"},{"speaker":"西村委員","kind":"質問","question":"細かいところで伺いたいのですけれども、２９ページにお米支援プロジェクトが入っておりまして、今年もやるということで記載されているのか。その点だけ少し伺えればと思います。","respondent":"飛田子育て応援課長","answer":"お米支援プロジェクトなのですが、来年度予算も計上しまして、実施できればと考えております。","id":"exchange-027"},{"speaker":"西村委員","kind":"質問・要望","question":"きちんと狙いどおりだったのかどうかというところも含めて分析をした上で、計画に盛り込んで進めていただきたいなと思います。今、お分かりになる範囲で結構なのですが、ご答弁だけお願いします。","respondent":"藤村子ども育成課長","answer":"狙いは、通常、児童センターを利用していない児童や家庭への支援につなげるというもので、目的の一つでありました。来年度はどういった形になるか分かりませんが、また、児童センターで配付となれば、同様の形で取り組みたいと思います。","id":"exchange-028"},{"speaker":"西村委員","kind":"意見","question":"その点も難しいところではあるのですが、またしっかりと分析をしていただいて、進めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"}]},{"id":"topic-05","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"その辺りを少し詳しく教えていただきたい。これは、１年生ぐらいで行けなくなるということだと思われますが、その辺りの現状の詳細を教えてほしいと求めました。","respondent":"丸谷教育総合支援センター長","answer":"フリースペースやフリースクールの場合は、まだまだ学校への登校には至っていないということで、継続して支援を行っている場合がほとんどです。そちらで対応していけるのか、次年度、再来年度につなげていきたいと考えているところです。","id":"exchange-030"},{"speaker":"あくつ委員","kind":"質問・要望","question":"１０年前では１桁だったものが、最近では２０から３０人ぐらいになってきているということについて、その原因を分析しているのか教えていただきたい。特に往復の安全面の確保というのはどのようなことをお考えになっているのか、もう少し詳細に説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"過去５年間においては、コロナ禍ということで、少なからずそういった部分の影響もあるのではないかと考えています。１年生や２年生のようなお子さんを保護者が公共の交通機関等を使って移動する際の安全面といったことも考慮しながら、今後、検討していきたいです。","id":"exchange-031"},{"speaker":"西村委員","kind":"質問・要望","question":"入っているときは、保護者の方から直接ＨＥＡＲＴＳに連絡があったときなのか、どういうときなのかを教えていただきたいということが１点目です。何かお考えがあればお聞かせほしいと求めました。","respondent":"丸谷教育総合支援センター長","answer":"次に、バーチャル・ランニング・プラットフォーム、ＶＬＰのログイン促進について、今年度も本当に試行錯誤しながら運営を進めてまいりました。先生方からの意見について、何かアンケートのようなものをとれるように方策を考えていきたいと思います。","id":"exchange-032"},{"speaker":"西村委員","kind":"質問","question":"あまり個別具体的な内容は聞けませんが、伺いたいなと思います。この数字を見て、入りたいけれども満員で入れないということはあまりないと思っていていいのか、その辺りを説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"保護者の認識として、なかなか分からないのではないかということについては、そのとおりだと思います。おおむね３０人程度ということで設定しておりますが、登録者数はその２倍程度を見込んで、曜日で割り振るということを行っています。","id":"exchange-033"},{"speaker":"西村委員","kind":"質問・要望","question":"以前の委員会でも質問させていただいたところなのですが、改めて、学区ごとに外国籍のお子さんの偏りがあれば、お聞かせいただきたいです。山中小学校、八潮学園の日本語指導教室に行けない外国籍の子どもはどれぐらいいるのかと、その子どもへのご対応を説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"保護者対応について、教育総合支援センターから学校に貸し出した翻訳機で対応しているというのが現状になります。在籍校に別室を設けていただいて、通室が難しい場合でも対応できるような体制は整えております。","id":"exchange-034"},{"speaker":"西村委員","kind":"質問・要望","question":"港区に確認しましたら、外国籍のお子様が６００名近くいらっしゃるということで、大変多いのです。オンラインレッスンや、日本語適応指導員の派遣など、ぜひいろいろな施策をご検討いただきたいなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-035"},{"speaker":"せらく委員","kind":"質問","question":"マイスクールと校内教育支援センターについて伺いたいと思います。そのまま下校する子の割合を、感触でも結構ですので、お聞かせほしいと求めました。","respondent":"丸谷教育総合支援センター長","answer":"１日４時間にしても、給食も別室で支援がいる下で喫食できるように体制を整えている学校もあります。今、各学校が子どもの状況や、また支援員が来られる曜日や時間帯といったものを総合的に調整しながら事業を進めているところになっております。","id":"exchange-036"},{"speaker":"せらく委員","kind":"質問","question":"学校の工夫で、それぞれ対応していただいているということなのですけれども、給食も教育の中の一つと思います。支援員の属性の中で、例えば、この免許を持っていると給食の時間まで支援ができるみたいな制限などはありますか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"特段、支援員に教員免許がないと給食を一緒にとってはいけないといった縛りは設けておりません。一緒に食べたりという工夫もできますので、特段、そこは免許がないから給食の時間にいられないという制限は掛けておりません。","id":"exchange-037"},{"speaker":"せらく委員","kind":"意見","question":"分かりました。子どもたちの成長を守るためにも、どうかそういった事例の共有といいますか、全校でも対応が可能なようにしていただければと思っていますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-038"},{"speaker":"高橋（し）委員","kind":"質問","question":"別のときに教えていただければと思うのですけれども、東京都、国の予算で賄っているものはどれかもし分かれば教えてください。もし、今、分かるものがあったら、お願いします。","respondent":"丸谷教育総合支援センター長","answer":"校内別室指導支援員の配置につきまして、東京都からは５校分を頂いておりますが、残りは区の持ち出しという形になっているところです。全ての事業について、補助金のあり、なしを把握が、今、この場でできておりませんので、また個別にお伝えできればと思います。","id":"exchange-039"},{"speaker":"高橋（し）委員","kind":"意見","question":"区でも独自にこれだけ上乗せして、不登校などをやっているのだというところがもっと見えるといいかなと思ったのでお尋ねしました。お尋ねしに行きますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/200387?Template=document&Id=6935#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":35671,"voices":128}},{"id":"r07-20250120-5","meetingId":"r07-cm01","date":"2025年1月20日","dateIso":"2025-01-20","committee":"総務委員会","time":"午後 １時００分～午後 ４時４７分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を62件整理しています。","topics":[{"id":"topic-01","title":"品川区総合実施計画（改定素案）に係るパブリックコメントの実施","agenda":"品川区総合実施計画（改定素案）に係るパブリックコメントの実施","exchanges":[{"speaker":"西本委員","kind":"確認","question":"その所管の中での調整も図ってここに来ているという理解でいいのか確認したいのと、５年間ということですが、区長選挙が入ってきますよね。それから、これは誰がまとめたのか尋ねました。","respondent":"崎村企画課長","answer":"この実施計画の改定に当たっては、どういう事業を実施計画に位置づけるのかというところを、区長の確認をいただいて取りまとめているところです。予算的には１,０００万円でお願いしています。","id":"exchange-001"},{"speaker":"西本委員","kind":"質問・要望","question":"そこをどうやって理解を求めていくのかという点が１つ。そこら辺はどう考えているのですかというところを説明を求めました。","respondent":"崎村企画課長","answer":"全く同じ質問を全国の方を対象に実施していて、それで幸福度がどのくらいかというものをはかっているところです。今回のウェルビーイング指標を設定する、また、総合実施計画を改定していく意義かと考えているところです。","id":"exchange-002"},{"speaker":"西本委員","kind":"質問","question":"それをどう想定して、行政として事業展開していくのですかということです。これを具体的な形で落とし込んで説明していかないと、これだけでは私は分からないと思いますが、その点はいかがか尋ねました。","respondent":"崎村企画課長","answer":"デジタル庁が実施している全国調査の結果から、では、長期基本計画の中でそういった指標を考えることも１つの手なのかなとは考えております。今回の総合実施計画については、繰り返しになりますけれども、区の施策について考えていけるようにしていきたいと考えているところです。","id":"exchange-003"},{"speaker":"西本委員","kind":"質問","question":"それはどう分析するのかお聞きしたいです。だから、どう捉えていますかということを説明を求めました。","respondent":"崎村企画課長","answer":"やはり子育て支援といいますか、また、人口を増やしていくということを取り組んでいかなければいけないのかと。そういう品川区をつくっていくための施策は何かということを考えていくということも、１つ大きな課題なのではないかなと捉えているところです。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問","question":"それは違うということが私らの勉強の成果でありまして、１７項目の中で関連性がどうあるのですかということが大切なわけです。どういうふうに事業の展開をしていくのか、それも取り入れてほしいと思うのですけれども、いかがか尋ねました。","respondent":"崎村企画課長","answer":"取組の予定といいますか、見込みについては掲載をしますので、令和８年度以降は調整中という網がかかるということではございません。令和７年度の予算を踏まえて、令和８年度以降、見込みで事業を実施していきたいということを区民にお知らせさせていただきたいと思います。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問・要望","question":"何が新しいのでしょうかという、これ、ほとんど今までやっていたものですね。これからまた何回も計画があると思いますので、意見として言わせてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"松本委員","kind":"質問","question":"我々も１年間勉強したとはいえ、１年間勉強したと言いながら、そんなに偉そうなことは言えないというところはあると思います。１点お伺いしたいのは、もう令和７年度から令和１１年度の目標とか指標というのは、見通しとしてあるのかどうかお伺いします。","respondent":"崎村企画課長","answer":"令和１１年度までの実施計画事業として何をやっていくのか、それらが全て来年度の令和７年度の予算を起点として進めていくものになりますので、数量的なものについて記載をした形であらわしていきたいと考えているところです。","id":"exchange-007"},{"speaker":"松本委員","kind":"質問・要望","question":"品川区は個別にどういうことをやっていくのかというのは、区民の方たちは、こういうふうにしていくのだということを納得してくださると思うのです。これは質問という形で投げかけしますし、我々が審議する前に具体的な数字として出していただきたいと思うのですが、いかがか尋ねました。","respondent":"崎村企画課長","answer":"５年間、こちらは５か年の計画ではありますけれども、令和７年度予算にご審議いただくということは難しいのかなと考えています。令和８年度以降については、またそれぞれご審議をいただいて、予算についてお認めいただくということがふさわしい形なのかなと考えているところです。","id":"exchange-008"},{"speaker":"松本委員","kind":"意見","question":"逆に、令和７年度に関しては、議員の皆さんに審議してほしいというやり方は多分可能なはずではないかと思います。我々というか、私としては、審議しやすいということを意見として申し上げたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それに対して区民の皆さん、どうでしょうかということになってくるのではないかと思うのですけれども、障害者計画とか。少し少なすぎるのではないでしょうかとか、もっと充実させてほしいとか、そういう声が出てくるのだと思うのです。","respondent":"崎村企画課長","answer":"人、それについてパブリックコメントを実施してご意見をいただいているところですので、実施計画事業それぞれについてお諮りするというのは。実施したのかといいますと、また、区民の意見をお聞きするために実施しているということが一番大きなところです。","id":"exchange-010"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"いかがでしょうかということと、パブリックコメントの期間が３週間、そのパブリックコメントをとるというのは４週間なのです。どういうふうに設定されて、どなたがどう決められているのかということ、いかがか尋ねました。","respondent":"崎村企画課長","answer":"今回、総合実施計画としてパブリックコメントを実施するというところの意味としては、１つ大きな手段となっているところです。特に今回について、総合実施計画の改定に当たってのパブリックコメントの実施で説明会を実施するというところは考えておりません。","id":"exchange-011"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"せめて１か月ぐらいはあってほしいなと思いますので、今後、そこら辺は考えていただきたいなと思います。なので、もしほかにそういった視点が入っているのであれば教えてほしいし、いかがか尋ねました。","respondent":"崎村企画課長","answer":"こちらについてまたさらに力を入れて、どういうところが課題なのかということを深掘りしてやっていかなければいけないと思います。それぞれの実施計画事業、今回、計画事業の中に入れていくということが実情です。","id":"exchange-012"},{"speaker":"石田（ち）委員","kind":"質問","question":"６ページ辺りからあるウェルビーイングの説明というか、どうでしょうかという感じで受け止めてもらって、意見をもらいたいということなのですか。いかがでしょうかということと、この計画は、区として責任をもって進めていくものと捉えていいのでしょうかということを伺いたいと思います。","respondent":"崎村企画課長","answer":"生活環境の向上というところで、そういった住民主体の動きを区としても支援していくといったところで、実施計画事業にこれまでもあるです。そういった考え方で、区としては実施計画事業を進めているところです。","id":"exchange-013"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この実施計画は、５か年計画ということです。基本的には５年計画ということでいいのかという確認と、長期基本計画自身も途中で変えていく、そういうことは検討されているのか伺いたいと思います。","respondent":"崎村企画課長","answer":"現在の基本構想、長期基本計画に基づいて、実施計画事業などを進めていくということが基本的な考え方です。とはいえ、この計画期間を待たずに、そういったことに着手するということも考え方としてはあるのかなと答弁させていただいたところです。","id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"質問","question":"区民の幸福度や生活満足度などを把握しましたということで６ページにデジタル庁が実施する地域幸福度指標全国調査が載っていて、どのように調査していくのかということがあれば、伺いたいと思います。","respondent":"崎村企画課長","answer":"こちらのデジタル庁が実施する調査というのは、全国的に実施をしているもので、これまでも２０２２年度から実施してきているようなものです。国のホームページ等でも公表されているものになりますので、今後…","id":"exchange-015"},{"speaker":"須貝委員","kind":"質問・要望","question":"区民あっての品川区ですから、やはり区民を前面に置いて、区民のための政策、計画を立てるべきではないかと思います。悪化しているなら、それに対して集中的に職員も、それから予算も振り分けることが基本的な構想だと思うのですが、どうか尋ねました。","respondent":"崎村企画課長","answer":"前年度もそうですけれども、全事業を事務事業評価という形で行いまして、次期実施計画として何を進めていくのかということを検討してきたところです。区としても考えておりますし、今回の実施計画について検討してきているところですので…","id":"exchange-016"},{"speaker":"須貝委員","kind":"質問・要望","question":"そして、こういうふうに出せないということは、先ほど、予算という話もありましたけれども、どうなのですか。区としては、着実に皆さんの区民サービスとして、区民に寄り添った施策をやっていきますということをしっかり強くアピールするべきではないか尋ねました。","respondent":"崎村企画課長","answer":"基本構想に基づいて実施していくというものになりますので、目指すべき社会像ですとか、方向性についてはお示しをさせていただいているところです。その中で、では、どういうふうに実施計画を詰めていくかというところについては、研究課題にさせていただければと考えています。","id":"exchange-017"},{"speaker":"須貝委員","kind":"意見","question":"かなり知っている人でないと、これは理解できないと私は思います。優秀なこういう書面をつくられると、なかなか理解がしにくいのではないかと、それだけは申し上げておきますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"パブリックコメントもとるし、次の報告になってしまいますけれども、世論調査を２年に１回やっているではないですか。もっといいのかなということが１つと、次回はもう少しとってもらえたらいいかなと要望で、取りあえずそこでお願いします。","respondent":"崎村企画課長","answer":"区独自でこういった地域の幸福度をはかるというような調査を実施しているところもありますので、ウェルビーイング指標については、検討といいますか。期間については、委員からもお話がありましたように、今後はなるべくとれるようにしていきたいと考えております。","id":"exchange-019"},{"speaker":"まつざわ委員","kind":"意見","question":"５か年でも単か年でも方向性が決まっていて、やはりそこの意見の出し合いができると、いいものになっていくのかなと思うのです。１つで頑張っていくのですという、区長を中心に１つでやっていくのですよという思い、それを課長のほうからとの意見を述べました。","respondent":"崎村企画課長","answer":"区の長期基本計画に基づく総合実施計画として、議会に対してご説明して、しっかりと区長の下で考えていきたいと考えています。","id":"exchange-020"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"森澤区長が目指すウェルビーイングに関して、しっかり区民に示していくというところがメインというふうに確認いたしました。どういうところを区が求めているのか、何を区が求めているのかということを１点確認を、まず最初にさせてほしいと求めました。","respondent":"崎村企画課長","answer":"副委員長からお話がありましたように、パブリックコメントの実施をする意義として一番大きなところは、今お話がありましたように。新たに実施をしてきました孤独・孤立対策推進事業ですとか、ヤングケアラーの支援事業ですとか、総合支援ですとか。","id":"exchange-021"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"そのことについて、このウェルビーイングとの関連性も質問でも確認させていただいているところでありますが、残念ながら。それと、これは全然別件ですけれども、今回、私たちがいただいているこのＡ４横の体裁は、パブリックコメントに出すための体裁か尋ねました。","respondent":"崎村企画課長","answer":"所得制限なく無償で提供するというような考え方が、区民の幸福につながるものと認識しておりますので、しっかりと検討していきたいと考えております。縦にしてしまうと、今後の電子化等の動きも含めて、今回からＡ４横にさせていただければと考えておるところです。","id":"exchange-022"},{"speaker":"大倉委員","kind":"質問・要望","question":"パブリックコメントの意義ということでお話を伺って、多分そういうことを求められてきたところもあったかなと思いますので、区民の声を聞くとか。これからどうしていくかという区の姿勢の１つに、この辺もぜひ今後、そのような工夫をしていただけるといいのかなと思いました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"西本委員","kind":"質問・要望","question":"だから、令和７年度の予算が年次計画にきちんと入るというのだったら、入っているものを出すべきではないですか。これ、時期をずらすほうがいいと思いますけれども、いかがか尋ねました。","respondent":"崎村企画課長","answer":"今回、ウェルビーイングの視点を入れ込むというところで、総合実施計画として改定をする中でのパブリックコメントは初めて実施いたします。これまで総合実施計画については、当然…","id":"exchange-024"},{"speaker":"西本委員","kind":"質問・要望","question":"いや、実は令和７年度の予算が変わりましたからとか、それが入っているんだったら意見があったのに」とかというところだってあるわけではないですか。だから、もう既に令和７年度の計画が立っているのだから、それを入れ込んでもいいのではないか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"}]},{"id":"topic-02","title":"第２６回品川区世論調査","agenda":"第２６回品川区世論調査","exchanges":[{"speaker":"西本委員","kind":"質問","question":"なので、大分重複している部分があるかなと。どういう位置づけでこの世論調査が反映されているのか、ＡＩ等の結果とどういう整合性をとってやっているのか、その辺はいかがか尋ねました。","respondent":"與那嶺戦略広報課長","answer":"今回の世論調査は第２６回で、２年に一度必ずとっているということで、時系列的に比較が見られる形になります。ただ、新しい技術などが出てきていますので、その辺りは関係部門と共有しながら活用の仕方などを検討してみたいと考えております。","id":"exchange-026"},{"speaker":"西本委員","kind":"質問","question":"政策を決定する上では非常に大切な項目ですから、私は否定はしないし、必要なことだと思っています。担当は違うかもしれないですけれども、いかがか尋ねました。","respondent":"與那嶺戦略広報課長","answer":"特に取り組んでいく必要がある目標などについては、まず、認知度を世論調査で聞いていきましょうという形で行いました。そこは個別の調査であるとか、こういった全体のものというところを活用していきながら、それぞれで考えていくものかと考えています。","id":"exchange-027"},{"speaker":"西本委員","kind":"質問","question":"政策決定に至るまでの経緯は、どういう経緯でやっているのか、そこを教えてほしいのです。どうやって決めているのか尋ねました。","respondent":"久保田企画経営部長","answer":"政策決定につきましては、やはり我々、区民から多くの意見を聞いて、それらを政策に生かしていきたいという考えを持っています。７回程度実施するというようなこともありますので、議会の議論もいただきながら政策決定して、事業として実現させていくといったところです。","id":"exchange-028"},{"speaker":"西本委員","kind":"質問・要望","question":"何を求めているかとか、令和７年度の予算のときは、やはり分かりやすい決定経過を求めていこうかなと。もっと庁舎の中で調整を図ってほしいと思いますので、これは要望として言っておきますので、ぜひお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"石田（ち）委員","kind":"質問","question":"これだけ下がっているというのは、何か理由があるのですか。そこら辺、区として何かあれば伺いたいと思います。","respondent":"與那嶺戦略広報課長","answer":"当然、多くの方から回答をいただけることを望んでおります。今後の回収率を上げていけるように、回答を増やしていけるようにと考えているところです。","id":"exchange-030"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今回の数字をどう見て、どう働きかけをしていくのかというところを考えたほうがいいのではないかなと思いますけれども、いかがでしょうか。これが解消されているからオーケーですよねというふうには思っていないですよねということを確認させてください。","respondent":"與那嶺戦略広報課長","answer":"やはり多くの方に回答してもらえるように、方法は考えられるかと思いますので、我々担当として考えていきたいと思います。そういった形で様々な施策に生かしていきたいというところも含めて、今回ご紹介させていただいたものです。","id":"exchange-031"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この８ページのところでいうと、あとは区に求めていくものというところでは見ているので、ぜひ回収率の向上は頑張っていただきたいなと思っています。やはり議会で積極的に求められているものを少し入れ込んでいくということはあるのではないかなと思うのですけれども、そこら辺はいかがか尋ねました。","respondent":"與那嶺戦略広報課長","answer":"なるべくここの設問は、前回、２年前の調査のときとほぼ同じ項目が今回も設定されているというところはあります。当然、そういった特に重視していくべき項目といったところにつきましては、所管部門と相談しながら確認してまいりたいと考えています。","id":"exchange-032"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"先ほど、防災の話もありましたけれども、例えば、町会に求めること、ＰＴＡに求めることの１位が大体防災対策です。５０％、それはどう考えているのかなということを教えていただきたいのと、そういうものがあるかということも説明を求めました。","respondent":"與那嶺戦略広報課長","answer":"性別であったりとか、それでどういった回答の色があったかみたいなところは提示する中で、ある程度見えてくるところもあるのかなと考えています。項目をまとめていく段においては、特に情報共有を図りながら進めてきたという形で、これは引き続き続けていきたいと考えています。","id":"exchange-033"},{"speaker":"まつざわ委員","kind":"質問","question":"どうしたらいいのでしょうかという、パブリックコメントになるのですか、やはり住んでいる人の声が一番現実ではないですか。この調査はすごく大事だと思うので、２年に１回というルールをこのまま継続していくのか、そこら辺の考え方はどうか尋ねました。","respondent":"與那嶺戦略広報課長","answer":"世論調査で続けている項目については、継続的に調査を行っていって、区の全体的な変化を見ていくというところも１つ大事なところかなと考えています。それは当然、そこはそれぞれお互いを活用しながら、よりよい施策につなげていくということが大事な観点かと考えております。","id":"exchange-034"},{"speaker":"須貝委員","kind":"質問","question":"９ページで、質問として、それについてご意見をお聞かせください。何か見ていますかということを、我々からすると知りたいところなのですが、その辺についてご意見だけ聞かせてください。","respondent":"與那嶺戦略広報課長","answer":"区のお知らせについては、どういった媒体を使って見ていただくかというところが、まず聞くところかなと考えています。そういったところで活用しているものを見ていくというところは、引き続き継続していきたいと考えています。","id":"exchange-035"},{"speaker":"須貝委員","kind":"意見","question":"なぜかというと、実際、防災訓練でもほとんど出てこない。そういう方たちの意見も聞きたいなというのはすごく思うので、これは意見だけですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-036"},{"speaker":"大倉委員","kind":"質問","question":"回収率のところでいろいろほかの委員からもあって、回収率の工夫はどのようにされているのかなというところを教えてください。そういう工夫があるかなと思うのですけれども、そういった工夫、今現在どのようにされているのか説明を求めました。","respondent":"與那嶺戦略広報課長","answer":"２週間ほどたって回答がまだない方につきましては、それで回答をお願いしますという形で行っておりまして、まだまだやり方がないかなと思うところ。今回、調査の目的の中からは、そういったところまで設定しなかったというところが現状です。","id":"exchange-037"},{"speaker":"大倉委員","kind":"質問","question":"少し分かりやすいとか、手にとってみようと思うような工夫とか、いろいろあるのかなと。その辺、工夫をぜひしていただけたらと思いますが、いかがか尋ねました。","respondent":"與那嶺戦略広報課長","answer":"インセンティブをつけましょうか、インセンティブがあるから回答するのかどうかみたいなところが、また少し議論も出てくるかなという形です。多くの方に回答してもらう１つの手段だということは、是非も含めて、今後の検討事項にしたいと考えています。","id":"exchange-038"}]},{"id":"topic-03","title":"続きまして、(3)人権・ジェンダー平等に関わる調査（区民・事業所）","agenda":"続きまして、(3)人権・ジェンダー平等に関わる調査（区民・事業所）","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"全体的に区の調査上での印象を教えていただきたいのと、２ページの人権問題のところで、日本は人権後進国と言われることが多いのです。なので、区としては、そういう認識の下でこういう調査をされている部分があるのかどうかということを伺いたいと思います。","respondent":"木村人権・ジェンダー平等推進課長","answer":"様々なところで実施している人権に関する啓発事業だったりとか、取組が、少し反映できているのかなと考えております。人権侵害が「ない」と答えられている方が６２.５％と、もう１つは、人権侵害と考えられていないというところもあると思うのです。","id":"exchange-039"},{"speaker":"石田（ち）委員","kind":"質問","question":"ないから区としての施策をやらなくていいとかということにはならないですよねという意図で質問したので、ご答弁ありがとうございました。約４人に１人が受けているということが見受けられて、様々見解なり、お聞かせいただけたらなと思います。","respondent":"木村人権・ジェンダー平等推進課長","answer":"男性と女性で分けると、ハラスメントを受けたことがないと回答している男性が６３.５％と、女性の５６.３％より７.２％ほど高くなっております。最初のパワー・ハラスメントが４人に１人というふうになっていますけれども、今後…","id":"exchange-040"},{"speaker":"西本委員","kind":"質問","question":"公表するのは今回の結果だけですか。前回との比較という形での公表はしないのか尋ねました。","respondent":"木村人権・ジェンダー平等推進課長","answer":"２つの調査を１つにしたことと、お答えいただくのに少し難しいというところがあったので、経年で見ているものの中で少し削ったところもあります。それは新しく入れていたりしますので、前回のものがないものについては入れられませんが、あるものは入れていく予定であります。","id":"exchange-041"},{"speaker":"西本委員","kind":"質問・要望","question":"どういう質問項目になっているのか確認したいのですけれども、３ページの人権を侵害されたという、やはり分からない項目が多々あると思うのです。これが課題ですとかというのは、今回の報告では入れるのか入れないのか、説明を求めました。","respondent":"木村人権・ジェンダー平等推進課長","answer":"言葉の定義につきましては、必要なものには少し入れているところもあるのですけれども、全部に対して入っているものではありません。なので、文章を読んでいただいて理解していただいて回答していただくというような流れになっておりますので。","id":"exchange-042"},{"speaker":"西本委員","kind":"質問・要望","question":"「男性のほうが非常に優遇」というものがある、「どちらかというと男性が優遇」が２.８％と１５.３％だから、大体１８％ぐらいあるではないですか。これは要望でお願いしておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-043"},{"speaker":"新妻副委員長","kind":"意見","question":"例えば、多様な働き方というところも、先ほども在宅就業制度がないところが減っているという成果が出てきているかと思います。そこはまた引き続き連携をしていただいて、品川区内の中小・零細企業を助けていただける支援の拡充をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-044"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"新妻副委員長","kind":"質問・要望","question":"１点だけ確認いたします。今、３月の下旬に発表ということですが、具体的にどのような形で発表されるのかということを確認させてほしいと求めました。","respondent":"與那嶺戦略広報課長","answer":"そういった形で発表していくというやり方が１つ考えられると思いますし、あとは、広報媒体を通じて発表していくというところも考えてあります。当委員会でのご説明も適宜実施していきたいと考えています。","id":"exchange-045"},{"speaker":"西本委員","kind":"確認","question":"確認なのですけれども、２０名、この間も聞いたのですよね。もう少し住民サイドの思いというものを引き上げるようなことをまず推進してからブランドを決めるべきなのではないか、いかがか尋ねました。","respondent":"與那嶺戦略広報課長","answer":"区の職員も区の一員として街の価値を高めていく１つのプレーヤーという形ですので、この間、いろいろ意見を聞いてきたです。そこを１つ位置づけをいたしまして、まずは区民や区に関わっている方々のご意見を伺って、今進めてきております。","id":"exchange-046"},{"speaker":"西本委員","kind":"質問","question":"どうもそこがつながっていなくて、政策につながっていかなかったら、分かりにくいのではないですか。何かがあるから、それを認識して共通認識になってくるのではないかなと思うのですけれども、そこはどうなのか尋ねました。","respondent":"與那嶺戦略広報課長","answer":"それは各施策を進めていく中で活用していただけたら、よりそこの価値を高めていくところがあろうかと思います。まずブランディングの中で区の全体的なイメージを高めていく、それで各施策がより高いレベルで実現していく、そういったところをイメージしています。","id":"exchange-047"},{"speaker":"西本委員","kind":"質問・要望","question":"やるのだったらしっかりやってほしいし、区民の皆さんにきちんと説明できる、理解を求めていくということをぜひやってほしいなと思うのです。多分もう少しとんがっていかないとできないと思いますが、いかがか尋ねました。","respondent":"與那嶺戦略広報課長","answer":"それを使って品川区のイメージづくりを進めていくという形で考えています。現状、個別のこの施策とという形ではなく、全体で区の行っている様々なものとつなげて使っていくという形で考えてあります。","id":"exchange-048"},{"speaker":"西本委員","kind":"質問・要望","question":"品川区にはゼロから１００歳以上の方がいらっしゃって、おかしいよなと、それでいいのですかという納得いかないことがたくさんあります。そこをもう少し工夫をしていただきたいと要望させてほしいと求めました。","respondent":"與那嶺戦略広報課長","answer":"未来をつくっていくというところは、当然それは世代によるところではないというところは、思いとしては持ってあります。全世代の方を対象にしながら、しっかり品川の未来をつくっていく、そういったところを目指しているものです。","id":"exchange-049"},{"speaker":"松本委員","kind":"質問","question":"それぞれの個性が尊重される寛容で多様な街」というものを見たときに、逆にこれを目指していない自治体はあるのですかという話になると思います。お伺いしていきたいのですけれども、これはあらゆる人が云々というのは、誰がワーディングをしたのか尋ねました。","respondent":"與那嶺戦略広報課長","answer":"そこの言葉の蓄積というところを、我々事務局のほうで、キーワードを抜き取りながらまとめてきたというところはあります。この調査の中で得られた皆様の声を１つの文章にまとめてワーディングしたものです。","id":"exchange-050"},{"speaker":"松本委員","kind":"質問","question":"そういうふうなところは特にされていないということでよろしいでしょうか。もう少し具体的に言うと、この都市ブランディングの推進において、ＡＩの活用はなされていないということでよろしいか尋ねました。","respondent":"與那嶺戦略広報課長","answer":"その中で、質的・量的という形で調査を行ってきたところではあるのですけれども、具体的にＡＩを活用したかというと、今回、活用してはいないです。あくまでここは出てきたキーワードを整理する中でまとめてきたです。","id":"exchange-051"},{"speaker":"石田（ち）委員","kind":"質問","question":"もう１回、西本委員の質問の繰り返しになってしまうかもしれないのですけれども、これがあるといいなと思うことがあるわけではないですか。だから、それを網羅するというのは、本当に難しい、大変なことだと思うのですけれども、ブランディングというのは、そういうことか尋ねました。","respondent":"與那嶺戦略広報課長","answer":"この１年間進めている中で非常に感じていまして、かなりそこは行ったり来たり戻ったりみたいな形で進めてきたところは、正直なところです。その上で、さらにこれは来年以降も進めながらまだまだ考えていくことも多いとは思うのですけれども…","id":"exchange-052"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そこに税金をかけてどうするのですかという区民の率直な声があって、そうすると、ついてこないというか。以上、意見です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-053"},{"speaker":"まつざわ委員","kind":"質問","question":"全く平均というのですか、逆にどのような色にも染めていけるのではないかという、私はいいふうに捉えましたけれども。１個聞きたいのが、この都市ブランディングは、それでゴールではないですよねということなのです。","respondent":"與那嶺戦略広報課長","answer":"おっしゃるとおりで、今つくっているロゴやデザイン、これを発表することがゴールかというと、むしろこれがスタートという形で考えております。ここをしっかりと打ち出して、まずスタートラインに立つための準備をしているという形で我々も捉えております。","id":"exchange-054"},{"speaker":"まつざわ委員","kind":"意見","question":"スタートだから難しいですけれども、その後をどう持っていくのか。どこまでそういうブランドというものを売り込んでいくというのは嫌ですが、担っていくのかということを説明を求めました。","respondent":"柏原区長室長","answer":"今後の予定のところで書いてあるような、この先に、オールで品川区を盛り上げていこうと考えているところです。認識みたいなところで底上げをして、これが多分、自治体のブランディングの考え方と企業の考え方で大きく違うところなのだと思うのです。","id":"exchange-055"},{"speaker":"須貝委員","kind":"意見","question":"区民の一番思っている通勤通学、すごく交通の便がいいという、そのイメージをこの品川というものに取り入れたらどうかなと思ったのです。自分でも、これを言っていいのかどうか迷ったのですけれども、意見だけ言わせていただきますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-056"},{"speaker":"大倉委員","kind":"質問","question":"もう１個、しっかりやっていって、そういうふうな品川ブランドをつくっていければいいなと思います。区民がどうやったらそう思って、やはり自分たちでロゴをつくってどうにかなるのかなと思うと、そういう認識でいいのか尋ねました。","respondent":"柏原区長室長","answer":"流れといいますか、委員おっしゃっている内容のことを、同時並行で進めていくということが基本的な考え方になってくると思います。職員だけで何かをやろうということでもありませんし、いろいろ予定ということで書かせていただいていますけれども、そういう手法で進めていく。","id":"exchange-057"},{"speaker":"大倉委員","kind":"質問","question":"お話はそのとおりで分かりました。それも１つの意味ではブランディングのメリットというか、そういうものも誰もが品川区へ来ると生きやすくなるというようなイメージでいいのか尋ねました。","respondent":"柏原区長室長","answer":"個別的に具体的な話になったときに何ができるかということはありますけれども、イメージといいますか、目指すところで言うのであれば、委員おっしゃるようなことになってくると思います。","id":"exchange-058"},{"speaker":"大倉委員","kind":"意見","question":"分かりました。これが発表されていくときには、なかなか伝わらないのではないかという懸念があるので、そこはぜひ進めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-059"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"西本委員","kind":"確認","question":"だけど、公募の方々は、そこまで調べて選定しているのですか。そこを確認したいのです。","respondent":"勝亦総務課長","answer":"区として統一的な、今おっしゃったような調査ですとか確認のルールは定まっていない部分もあろうかと考えています。基本的に公になっているものの情報は、できる限り確認をした上でお願いするというのは、各所管のほうでやっていると認識しております。","id":"exchange-060"},{"speaker":"西本委員","kind":"質問","question":"決まりはないけれども、調査をするということが私は必要だと思うのですが、いかがか尋ねました。","respondent":"勝亦総務課長","answer":"過去のＳＮＳですとか、デジタル上での発言、そういったものも注視していく必要があるかと考えますので、今後、どのような誹謗中傷ですとか発言内容を確認していくかというのは、少し研究していきたいと考えております。","id":"exchange-061"},{"speaker":"西本委員","kind":"質問・要望","question":"代表で話合いに入っていただいているわけですから、そういうものを含めてご検討ほしいと求めましたので、お願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-062"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/787454?Template=document&Id=6943#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":68683,"voices":146}},{"id":"r07-20250121-14","meetingId":"r07-cm01","date":"2025年1月21日","dateIso":"2025-01-21","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ２時３８分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を38件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"１月６日ということで、全く同じような原因で、この２自治体が全く同じ状況で全く同じ障害が起きたという認識でいいのか尋ねました。","respondent":"横田デジタル推進課長","answer":"正確には把握していないのですが、新宿区につきましては、サーバーのメモリー不足が原因であったと聞いております。なので、品川区とは別事象ということになります。","id":"exchange-001"},{"speaker":"あくつ委員","kind":"質問","question":"この報告いただいたところについては、システム更改ということが書いてあるのですけれど、これはいわゆる標準準拠システムへの移行作業という中で発生したというふうに理解をすればよろしいのか尋ねました。","respondent":"横田デジタル推進課長","answer":"先日の年末年始で、住民記録システムを標準準拠システムに移行を行いまして、その作業ということになるのですが、直接的な原因は、住民記録システムと住基ネットの接続の部分になりまして、厳密には今回のシステム標準化とは関係ないところで障害が起きたという事象になります。","id":"exchange-002"},{"speaker":"あくつ委員","kind":"確認","question":"私の理解度では、何となく分かる気はするのですが、そのとおりなのだろう、説明のとおりなのだろうなと思います。ベンダー挟んでいるから、ここについては、もう同じことは基本的に起きないと考えてもよろしいのかどうか確認をさせてください。","respondent":"横田デジタル推進課長","answer":"システム障害が起きないように努力はしたいと考えております。ユーザー目線での検証をきちんと提案して、実行していくなど、ベンダーをより一層うまく指揮してコントロールしていきたいなと考えております。","id":"exchange-003"},{"speaker":"あくつ委員","kind":"質問","question":"分かりました。いわゆるベンダー側からの謝罪ではないですけれど、二度とそういうことは起こしませんというような、何かそういったものはあったのか尋ねました。","respondent":"横田デジタル推進課長","answer":"システム稼働前は夜中の深夜１時、２時とかそういう、こういったやり方ではなかなか厳しいなということ。例えばプログラムでチェック機能を設けるとか、最後は人間の手によらないチェックの機能を設けてくれというような要望を出しているところになります。","id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問","question":"１月６日のあの混雑状況、区の負担で郵送でということもあったのですけれども、やはり区民の方が一番影響を被ったのではないでしょうか。これはもうお願いするしかないのですが、その辺りについてもう一度最後、ご答弁いただいて終わりにしたいと思います。","respondent":"横田デジタル推進課長","answer":"９７.５％を下回った稼働の場合は、そういったところも、視野に入れて調整をしているところになります。","id":"exchange-005"},{"speaker":"山本委員","kind":"質問・要望","question":"シゴトＤＸ、地域のデジタル化、それから行政のデジタル化というもののアップデートみたいな位置づけになるのかというところを確認させてください。それから、地域のデジタル化と行政のデジタル化が、この順番が変わることに対しての意味があるのかどうかというところについてお教えください。","respondent":"西澤ＤＸ戦略担当課長","answer":"新しい基本方針ですが、それぞれ将来像と基本方針を定めておりまして、効果的なＤＸ推進を目指していこうと考えております。前回からの変更点の特徴ですが、今回はＤＸというところで、業務に踏み込んでやっていくというところを目指しております。","id":"exchange-006"},{"speaker":"山本委員","kind":"質問・要望","question":"ご説明いただいた個別の３つの視点についてそれぞれお伺いしたいのですが、４ページに記載の、それについて教えていただきたいです。これ、具体的にどのような方法をご検討されていらっしゃるのか、取組の方向性や内容についてお教えほしいと求めました。","respondent":"西澤ＤＸ戦略担当課長","answer":"こちらは官民が連携してデータ利活用をする中で、よりよい施策といったところを検討していけるといいなと考えております。具体的なデジタル技術については、そういったところを組合せで使うことによって、業務の効率化ということを進めていけるように推進していく予定です。","id":"exchange-007"},{"speaker":"山本委員","kind":"質問・要望","question":"施策の立案と推進の考え方やこの推進体制のところについても続いて質問させていただきたいのですけれども、７ページ、現在。それとも兼務者になるのでしょうかというところと、こういう形で課内の浸透を図るとか、そういった役割が明確にあれば教えてほしいと求めました。","respondent":"横田デジタル推進課長、西澤ＤＸ戦略担当課長","answer":"私から、１点目のデジタル地域通貨のご質問についてお答えいたします。Ｔｏｋｙｏ Ｔｏｋｙｏ Ｐｏｉｎｔの動向を見ながら、次年度以降もまた、調査研究してまいりたいと考えております。 マイルストーンについては、今後、重点施策の立案と推進の中で考えていく、検討していく。令和４年から令和６年の３年間で実施したことについては、もう１個ＤＸといったところに向けて、かなり進められたと考えております。","id":"exchange-008"},{"speaker":"山本委員","kind":"質問・要望","question":"次に、システム標準化のところですけれども、先ほどほかの委員からの質問もございましたので、理解いたしました。これ実際、障害のところですが、起こってその影響を受けた方々というのは、分かっているところでいうとどれぐらいの人数の方なのか尋ねました。","respondent":"横田デジタル推進課長","answer":"約３２０名の転入、転出、印鑑登録などの処理ができなかったと思われます。ちなみに、区負担での郵送負担がどれぐらいあったかというところなのですが、４名になります。","id":"exchange-009"},{"speaker":"山本委員","kind":"質問・要望","question":"影響があった３００名の方というと、しっかりとベンダー様と協議の上、再発防止に努めてほしいと求めました。それからシステム標準化についてもしっかりと進めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"筒井委員","kind":"質問・要望","question":"私からは、ＤＸ推進基本方針について伺いたいと思います。その確認をさせてほしいと求めました。","respondent":"西澤ＤＸ戦略担当課長","answer":"ただ、そんなに難しい用語を使ってはいません。例えばですけれど、６ページなどでＥＢＰＭという言葉があるのですが、あまり使われない用語に関してはこういった注釈を入れるようにしております。","id":"exchange-011"},{"speaker":"筒井委員","kind":"質問・要望","question":"そうしたことについては適宜、分からない区民に対してはご説明、丁寧な対応をしていただきたいと存じます。前方針の１９ページで、これは引き続き、副区長という認識でよろしいのか尋ねました。","respondent":"西澤ＤＸ戦略担当課長","answer":"来年度、令和７年度も副区長が実施していく予定にはなっております。ただ今後、基本的には副区長が実施するということになっております。","id":"exchange-012"},{"speaker":"筒井委員","kind":"質問","question":"基本的に副区長で、では、副区長ではなくなる可能性もあるということなのですか、その点あれば。","respondent":"西澤ＤＸ戦略担当課長","answer":"思いとしては、副区長だからＣＩＯというわけではないというところで、ＣＩＯとして誰がふさわしいかと検討した上で、ではそれが誰なのだというところがポイントになっております。","id":"exchange-013"},{"speaker":"筒井委員","kind":"質問","question":"ＣＩＯの方、どなたか決定された際にはまた、ぜひお知らせいただけると幸いです。総務省との連携ですか、この１０ページは、伺いたいと思います。","respondent":"西澤ＤＸ戦略担当課長","answer":"最近出来上がったというところもありまして、そういったことから、東京都の連携というところを強くしていくということは重要だと考えております。そういったところの方針とか施策とか、今回東京都というところを載せしています。","id":"exchange-014"},{"speaker":"筒井委員","kind":"質問・要望","question":"高齢者の方の情報格差の問題をどう捉えているのかということと、同じく１７ページのところで、この辺りの都市型観光の推進というのがなくなった理由について伺いたいと思います。","respondent":"西澤ＤＸ戦略担当課長","answer":"こちら方針では書かれていないですけれど、今後も実施していくものになっておりまして、各種講習というか体験教室みたいなものを予定していまして。都市型観光については、どういった手段がいいのかというところを議論しながら進めていくと考えておりまして…","id":"exchange-015"},{"speaker":"筒井委員","kind":"質問・要望","question":"そのデジタルデバイド対策、本当に利用者目線ということでそうしたことは継続してしっかりやってほしいと求めました。都市型観光については、新方針の安心安全なまちをつくる、要はまちづくりの中に包括的に入れていくというイメージでよろしいか尋ねました。","respondent":"西澤ＤＸ戦略担当課長","answer":"はい、その認識で問題ございません。","id":"exchange-016"},{"speaker":"筒井委員","kind":"質問","question":"ＤＸ化を推進するに当たり、もし万が一の危機的な状況に陥った場合、そうしたデータの消失とか大丈夫なのかという問題があるかと思います。そうした危機管理対応についてもある程度、基本方針に載せたほうがいいのかなと思っているのですけれども、その辺りどのようにお考えなのか尋ねました。","respondent":"横田デジタル推進課長","answer":"システム標準化によりまして、データセンターは基本的にはＡＷＳという外資のクラウドのほうに移行する予定になっています。その辺りをこういったＤＸ推進基本方針に掲載してはというところですが、今後検討してまいりたいと考えております。","id":"exchange-017"},{"speaker":"筒井委員","kind":"質問・要望","question":"デジタル化を推し進めると、そうした危機管理に逆に弱いのではないかというお声もありますので、ぜひそうした、万が一の危機管理対応というのもしっかりと考えていっていただきたいと存じますので、よろしくお願い申し上げます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"新妻委員","kind":"質問・要望","question":"そもそもこれは令和８年度以降、ここに掲げられている以外で、さらにまだやらない部分があるのでしょうか。そこを教えていただきたいのですけれども、国の交付の延長に関連して、品川区の進め方について少し教えてほしいと求めました。","respondent":"西澤ＤＸ戦略担当課長、横田デジタル推進課長","answer":"私からは、今後の具体的な施策についてお話をさせていただきたいと思います。アクションプラン、それをもって今度の４月の行財政改革特別委員会でもう一度ご説明させていただければなと考えています。 令和８年度以降、本来の稼動予定より少し遅くなってしまう業務が３つあるのですが、できるだけ早急に標準化を進めていきたいと考えております。で、データが分担してしまう状況になってまいりますので…","id":"exchange-019"},{"speaker":"新妻委員","kind":"質問・要望","question":"そのマイナンバーカードだけではなく、デジタル化に関してという全体を少し分かりやすくまた、周知をしていただきたいなと思います。これは今後、国の補助金の交付が延長になる、これは活用できるということでよろしいのか尋ねました。","respondent":"横田デジタル推進課長","answer":"こちらの３業務につきましても、補助金の対象になります。漏れてしまった金額につきましては、都区財政調整制度等を活用して、できるだけ満額に近いお金を獲得していきたいなと考えております。","id":"exchange-020"},{"speaker":"石田（秀）委員","kind":"質問","question":"そこは計画道路に何ｍ食い込んでいるのですかというのを丁寧に教えていただいたのだけれども、みんな、素人っぽいプロみたいなものもいるわけで。相手に対してもサービスが１回で済んでよかった、どうしても役所は２回も３回も行ったり、区民にとってはそういうのがあるではないか尋ねました。","respondent":"西澤ＤＸ戦略担当課長","answer":"は、質問するとチャットボットがきちんと答えてくれるとか、そういったところの普及率を増やしていこうと考えております。あくまで方針なので、より使いやすかったり、より利用率が増えるような施策を効果的に打っていくというところは今後実施していくところになります。","id":"exchange-021"},{"speaker":"石田（秀）委員","kind":"質問","question":"会社の中でこれが大問題になっていて、これをどういうふうに整理しようかというので、それは業者の人にしかやってもらえないという話になったけれど。どうなってしまってこれどうしたらいいのという対応がよく分からないことが結構あるのですけれど、それから、こんなことはできるのか尋ねました。","respondent":"西澤ＤＸ戦略担当課長","answer":"ファクスとかメールとか、そういったところの対応策があるので、そういったところをやっていくことが一つかなと考えております。区が提供するサービスについては、電子申請に関しては、そういうことを通じて実施いただければなと考えています。","id":"exchange-022"},{"speaker":"つる委員","kind":"質問","question":"聞き漏らしていたので改めて教えてほしいのですが、ここを改めて教えていただきたくて、改めて説明を求めました。","respondent":"西澤ＤＸ戦略担当課長","answer":"こちら、デジタル化推進委員は職員になります。各課にいる職員で、ふだんの業務をしながらこのデジタル推進委員も兼ねるといったものになっております。","id":"exchange-023"},{"speaker":"つる委員","kind":"確認","question":"これは品川区とどういうふうに、連携だとか活用だとかとになっているのでしょうか。人数把握なかなかできていませんとかということは少し確認できたのですけれど、現在品川区で、そういったところも含めて説明を求めました。","respondent":"西澤ＤＸ戦略担当課長","answer":"今、国のデジタル推進委員とは特に連携はしておりませんで、区独自でデジタル化推進委員を立てて、全庁的な、課に大体１人から２名ぐらいの職員をデジタル化推進委員として立てておりますので、そのメンバーを通じて全庁的なデジタル化を進めていくといった計画になっております。","id":"exchange-024"},{"speaker":"つる委員","kind":"質問","question":"そうすると、具体的なサービスが対区民、対法人とかに向けて展開されたときには、そうした方々の活用というかご協力の可能性はあるのでしょうか。なければないでいいです。","respondent":"西澤ＤＸ戦略担当課長","answer":"彼らがＤＸの浸透を深めるというところになっておりますし、そういうことを深めていけば所管課のデジタル化が進んでいくので、そういったところで区民へのデジタルサービスの還元といったものができると考えております。","id":"exchange-025"},{"speaker":"つる委員","kind":"提案","question":"あるいは、国のデジタル庁のデジタル推進委員を活用したらいいのではないのかなというところの提案的な質問なのですが、先ほどの質疑を伺っていても。デジタル化推進委員ではなくてデジタル推進委員との連携などの可能性はないのか尋ねました。","respondent":"西澤ＤＸ戦略担当課長","answer":"今後調査を進めて考えていきたいとは思っておりますが、課との連携をしていくというところで必要な人材と定めておりまして、全庁的なＤＸの推進には欠かせない役割と考えております。","id":"exchange-026"},{"speaker":"つる委員","kind":"提案","question":"そうしたデジタル推進委員がご協力できること多々あるのではないのですかねというような、今伺っていることにも背景にあるわけですけれど。ご協力いただく可能性というのはあるのではないのかなと、これは別の機会でいろいろまた、もう少し確認しながら聞けたらなと思いますとの意見を述べました。","respondent":"横田デジタル推進課長","answer":"今は区と連携がないので、もし区民から問合せあったときはこういうのを活用してくださいというような周知も含めて、今後検討していきたいと考えております。","id":"exchange-027"},{"speaker":"のだて委員","kind":"質問","question":"この基本方針を作成するに当たって、いろいろ庁内でもアンケートとかグループワークやってきたということですので、その中での意見とか議論というのがどういうものがあったのかというのを伺いたいと思います。","respondent":"西澤ＤＸ戦略担当課長","answer":"ワーキンググループに関しては計２回実施しておりまして、７月から９月に関して実施されています。各施策というか、こちらに書かれている３つの、いろいろな施策を基本方針として定めたといったところになっております。","id":"exchange-028"},{"speaker":"のだて委員","kind":"質問・要望","question":"今までつかんでいたものがつかめなくなって、その点、区としてはどのように考えているのか伺いたいと思います。このマイナンバーカード持っていない人も不利益がないように、行政としてはぜひやっていってほしいと求めましたけれども、いかがか尋ねました。","respondent":"西澤ＤＸ戦略担当課長、横田デジタル推進課長","answer":"パブリックコメントの実施方法についてですが、実施期間は令和７年２月１日から２月２８日を予定しておりまして、周知方法については。デジタル推進課のほうに来ていただければ説明をいたしますので… 私からは、マイナンバーカードは、住民サービスの向上ですとか事務の効率化に使用しています。個人情報の保護に十分留意しながら、マイナンバーカードの利活用を法令にのっとりまして適切に進めてまいります。","id":"exchange-029"},{"speaker":"のだて委員","kind":"質問・要望","question":"この標準化に伴って、これまで行ってきた事業が縮小されたりできなくなってしまった部分というのがあるのかどうか、伺いたいと思います。そうした負担の面で、実際、現状どうなっているのかというのを伺いたいと思います。","respondent":"横田デジタル推進課長","answer":"当然これまでやってきた事務を見直すＢＰＲをしながら進めていきますので、今、事業の縮小したものはあると考えております。国のほうからは、これまでそれなりに行革を進めてシステムのコストを圧縮してきた関係もありまして、我々一同頑張ってまいりたいと考えております。","id":"exchange-030"},{"speaker":"のだて委員","kind":"質問","question":"区民に直接関わる縮小はしていないということなのですか、そこを伺いたいのと、いかがか尋ねました。","respondent":"横田デジタル推進課長","answer":"事務の効率化ですとか、帳票を２枚出さなければいけないのを１枚に変えたりとか、そういったことは実施をしております。３点目が、そういったシステム改修経費ですとか運用経費を抑制することができるということが期待できると考えております。","id":"exchange-031"},{"speaker":"西村委員","kind":"質問","question":"具体的に品川区でどの事業でどのように展開するイメージなのかというのを伺えればと思います。３ページで、このときにワークショップをされた部を教えてほしいと求めました。","respondent":"西澤ＤＸ戦略担当課長","answer":"まず、検証とアクションというところを実施していくということが重要だと考えておりまして、そういったところを取り組んでいきたいと考えています。他自治体との連携も含めてやっていけると、自治体としてどういったデータ分析だとか…","id":"exchange-032"},{"speaker":"西村委員","kind":"質問","question":"ワークショップで部が横断していると書かれているので、どの部が横断、何課が横断をされてワークショップされたのかが分かれば説明を求めました。","respondent":"西澤ＤＸ戦略担当課長","answer":"ワークショップについては、子育て応援課、高齢者福祉課、あとは戸籍住民課など、そういった窓口業務をしている課というのを中心に集めてワークショップを実施していきました。","id":"exchange-033"},{"speaker":"西村委員","kind":"質問・要望","question":"少しＥＢＰＭは難しいところもありますので、私も勉強していきたいと思いますが、力強いご答弁いただいているのでぜひ進めてほしいと求めました。２４時間以内に解決できるように進めていただいたことが、その研修がどのような形で今回活かされたのか、もし分かれば説明を求めました。","respondent":"横田デジタル推進課長","answer":"毎年９月の中旬あたりに、今回みたいにダウン対策システムが動いたらどういうふうに対応するのかと、システムがないときにどういう対応をしたのかと。その辺りは、戸籍住民課だけでなく税務課ですとか国保医療年金課ですとか…","id":"exchange-034"},{"speaker":"西村委員","kind":"質問・要望","question":"よく分かりました。特に来庁人数の多い課ですので、こういった研修とか訓練の強化もぜひ、引き続き再発防止のためにご検討ほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-035"},{"speaker":"筒井委員","kind":"質問","question":"２回目ですみません。デジタル化推進委員について伺いたいのですけれど、研修とかを受けて、どういった方がデジタル化推進委員になっているのか尋ねました。","respondent":"西澤ＤＸ戦略担当課長","answer":"デジタルを進めていくという人材になりますので、ＩＴに割と強いといった人材を選んでいただくことを我々としては推奨しております。そういったところに優先的に来ていただくような働きかけをして、よりレベルアップさせていくということを目標にしております。","id":"exchange-036"},{"speaker":"せらく委員","kind":"確認","question":"区のオンラインサービスで、サービスによってログインＩＤ、パスワードというのはそれぞれ設定するものなのか確認させてください。","respondent":"西澤ＤＸ戦略担当課長","answer":"基本的にはサービスが分かれておりますので、サービスＩＤとパスワードを分けていただくものになっております。１個突破されるとほかのサイトも突破される可能性が強いので、セキュリティーの観点でもあまり推奨はしていないというところになっております。","id":"exchange-037"},{"speaker":"せらく委員","kind":"意見","question":"１つのＩＤ、１回ログインすれば自分にひもづくサービスが使えるような画面になれば、お話しいただけるとの意見を述べました。","respondent":"西澤ＤＸ戦略担当課長","answer":"そういったところの研究を進めていきながら、利便性とセキュリティーというところの両方を兼ね備えるログイン方法ということを今後、技術の進歩と併せて研究していきたいと考えております。","id":"exchange-038"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/347374?Template=document&Id=6945#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":30806,"voices":84}},{"id":"r07-20250122-19","meetingId":"r07-cm01","date":"2025年1月22日","dateIso":"2025-01-22","committee":"災害・環境対策特別委員会","time":"午後 １時００分～午後 ４時２５分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を80件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"こういったものを区としてはご覧になられているのか伺いたいのと、３００ページあるので、こういうものも見られているのか。区の職員の研修とかも必要になってくるのではないかなと思うのですけれども、いかがか尋ねました。","respondent":"平原防災課長","answer":"私も８年前、熊本に住家被害認定調査で支援に行きまして、急遽そちらに回ったというようなこともありました。そういったところへどういうふうに、先ほど言いました研修内容を伝達するかといったところにつきましても、研究しています。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"分かりました。今現在どうなって……、今はどう考えられているのか、説明を求めました。","respondent":"平原防災課長","answer":"あるいは、もうちょっとたってきましたら、最初についたところから、今度は中期的に必要なってくるところに人員を移してくる。人員の流動化を考えながらも、ただし、ふだんからしっかりと能力を高めるようなことは責任を持ってやってほしいというところで進めているものです。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"そういう体制に活かしていくというところでは、どんなことを感じられてきたのか、伺いたいと思います。","respondent":"平原防災課長","answer":"役割分担ができて、ちょうどその過渡期で、私どもが入ったときにはかなり加速化していったような状況でございました。住家被害認定調査は受援職員を送り込むということを前提とさせていただいたというふうに、その後の制度改正のところでは聞いているところです。","id":"exchange-003"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"分かりました。有事は本当にいつ起こるか分からないので、この体制だけはしっかりと今後も構築してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"まつざわ委員","kind":"質問","question":"区民の皆様は知っているのでしょうか、知らないのでしょうかという、区民の方は当たり前に分かっているものなのですか。それを説明を求めました。","respondent":"平原防災課長","answer":"公的な支援のために必要になるものですので、罹災証明書というものが必要ですよということはしっかりとアナウンスされるものです。そういったところでは、被害に遭われた方というのは、そういう事実は知っているのかなと思ってあります。","id":"exchange-005"},{"speaker":"まつざわ委員","kind":"意見","question":"今、やはりそういうのが分かれば助かるなと思ったのですが、区のほうでプッシュ型でそういう被害が出た方に関してはしっかりと通知が行くと。罹災証明は、使う使わないは別にしても、しっかり分かっているということですねとの意見を述べました。","respondent":"平原防災課長","answer":"罹災証明、被災者台帳という考え方がございまして、一人一人がどういう状況かというものを私ども把握することが前提となっております。なお、火災そのものにつきましては、所管行政庁が消防ということなって、消防法になりますので、区では発行対象という形ではございません。","id":"exchange-006"},{"speaker":"まつざわ委員","kind":"質問","question":"消防団も必ず行くのですよね。豊町１丁目で火事があったときに、罹災証明って何ですかとか、例えばそういった周知もどんどん取り入れていただけるといいかなと思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"えのした委員","kind":"意見","question":"「５ 相談体制」というところで「各種情報を伝達するとともに、何人体制ですとか、その辺が分かればお知らせくださいとの意見を述べました。","respondent":"平原防災課長","answer":"本委員会で避難所につきましてご説明させていただいたときの、一番最後のところの情報支援という中で、巡回して各種の相談を受けるような体制というふうに考えているところです。","id":"exchange-008"},{"speaker":"えのした委員","kind":"意見","question":"今、士業団体等と連携して実施していただくと。それとも、関わるけれども士業団体がメインでご相談を聞いていただくという……、ちょっとイメージがとの意見を述べました。","respondent":"平原防災課長","answer":"やはりそれを適切にどこにつなげるかというところでいきますと、やはり弁護士の方あるいは行政書士の方といったところが適任かなと思われます。ただ、その後の実際の支援という形になりましたら、そういったところでより詳細なお話を聞いて実際の支援につなげていく。","id":"exchange-009"},{"speaker":"鈴木委員","kind":"質問・要望","question":"罹災証明の調査のところで、６市町で、その後の再建ができるかどうかというのが調査の結果によって決まってくることになると思うのです。住家被害認定調査票の写しを被災者が求めた場合は、求められたときに写しをそのまま出して、伺いたいと思います。","respondent":"平原防災課長","answer":"これについては引き続きしっかり検討させていただきたいと思ってありますが、もう１点が、それはそれで不利益な情報なので。第２次調査のほうが詳細調査なので、調査を考えていただくといったところで、私どももしっかり教訓を踏まえてやっていきたいと思ってあります。","id":"exchange-010"},{"speaker":"鈴木委員","kind":"質問・要望","question":"１９点の方もいれば１０点の方もいて、でも、この公開はすごく大事なことですよということが日弁連のところで書かれている中身だったのです。どう判定されたのか、ぜひともこういう方向でご検討ほしいと求めましたが、改めて伺えたらと思います。","respondent":"平原防災課長","answer":"罹災証明書の発行支援に向かいましたが、その中身を説明して、その結果こうなりましたといったところも含めてご説明したと聞いているので。そういったことで事務的にも対応していますので、今後も様々な状況を踏まえながら、検討を進めてまいりたいと考えています。","id":"exchange-011"},{"speaker":"鈴木委員","kind":"意見","question":"１年たってもあんな状況で、現場を見られたら、この支援では再建は無理でしょうという状況は本当にあると思うのです。そういうところでの支援のさらなる拡充と、ぜひ充実をしていただきますようにお願いしておきたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"こんの委員","kind":"質問","question":"すぐに申請に持ち込めるような形の体制がとられているのかどうかといったところをまずお聞きしたいのと、また、それには委任状が必要となっています。こうしたことへの対策をどのように考えているのか、説明を求めました。","respondent":"平原防災課長","answer":"巡回窓口をつくっていくお話もさせていただいたところですが、そういった中で、書面の用意なんかは当然あるものと考えているところです。まだ検討途上のところもございまして、様々、品川区でもしっかりと寄り添った形で対応できるようにしてまいりたいと考えています。","id":"exchange-013"},{"speaker":"こんの委員","kind":"確認","question":"現在、体制としては、巡回をしながらフェーズごとにといったところは確認させていただきました。証明書の申請に持ち込めるような、こうした体制をお願いしたいと思うのですが、いま一度ご答弁をいただけますか尋ねました。","respondent":"平原防災課長","answer":"避難行動要支援者に対する支援の視点の中で検討していますが、ただ、一般的にかなり網羅的にやるということはなかなか難しいので。そのときに必要なところで、地震の場合には巡回体制を、そういったところに行けばというようなご案内をしっかりさせていただければと思ってありま…","id":"exchange-014"},{"speaker":"こんの委員","kind":"質問・要望","question":"先ほども証明書が出た後の支援がどういうふうに受けられるかという議論がありましたけれども、この体制をぜひ今後も考えていっていただきたい。要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"須貝委員","kind":"質問・要望","question":"結局順番があるわけですから、遅れれば、１年たっても解体ができなくて再建ができない。半壊だ、全壊だとなっていない人も避難してくるわけで、本当に大丈夫なのですかというのをもう１回確認させてください。","respondent":"平原防災課長","answer":"被害想定に出されたものをしっかりと対応するというものがまず区の防災体制と考えていますので、そういったところからしっかりやらせていただくと。被害想定で出された数字に対して、しっかり対応しているというところでご説明させていただいているところです。","id":"exchange-016"},{"speaker":"須貝委員","kind":"質問・要望","question":"様々なものを皆さんがそれぞれ、そしてその足りないところを後方支援としてしっかり行政が対応するという方法をとっていただきたいと私は思います。終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"ゆきた副委員長","kind":"確認","question":"令和６年度からマイナポータルでの電子申請が可能となったということですけれども、対面の窓口での発行手続を希望される方もかなり多いと思われます。災害時の罹災証明の発行手続の窓口開設については、区役所で１つ開設されるという認識で間違いなかったか尋ねました。","respondent":"平原防災課長","answer":"必要に応じて開設する必要があるのではないかといったところで、今、場所の検討なんかもまた進めているところです。そういったこともございまして、まだ地域防災計画には特に記述していないところです。","id":"exchange-018"},{"speaker":"ゆきた副委員長","kind":"質問・要望","question":"ここについては、防災協定を結んでいる行政書士会品川支部からの要望でも上がっていることだと思われます。地域に密着した１３の地域センターで、最後、お聞きできればと思います。","respondent":"平原防災課長","answer":"地域センター対応となっていますけれども、一旦は自動的に地域センターという形にしていないというのは、そういったところです。そういったところの運用可能性も勘案しながら、今、検討を進めているところです。","id":"exchange-019"},{"speaker":"ゆきた副委員長","kind":"確認","question":"状況に応じて対応されているということで確認させていただきました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"せお委員","kind":"質問・要望","question":"そこら辺の考えを教えていただきたいのと、発行もそうですけれども、これは優先順位とかは考えられているのでしょうか。そこら辺も説明を求めました。","respondent":"平原防災課長","answer":"逆に税務課がしっかりと責任を持っていただくというようなところで、今、認識がしっかりと根づいてきているのかなと思ってあります。支援金が出たりとかの対象になりますので、ただ、明確に順位がついているものではございません。","id":"exchange-021"},{"speaker":"せお委員","kind":"意見","question":"罹災証明なのか、被災証明なのかというところも含めて、柔軟に対応していただけたらなと思っていますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"吉田委員","kind":"質問","question":"多分一生懸命広報はされていると思うのですけれども、残念ながらそこまでの日々の認識というのは難しい方が多いのではないかなと思います。紙を１枚配るだけでも認識が少しは広がるのではないかなと思うのですが、資料の提供とか、伺いたいと思います。","respondent":"平原防災課長","answer":"罹災証明書を含めてですけれども、災害時の対応につきまして、様々な情報を私どもからお送りする必要があるかなと思います。具体的にはいろいろな支援というような内容を周知していく形になるのですけれども、その支援の前段階が罹災証明書という形になりますので。","id":"exchange-023"},{"speaker":"吉田委員","kind":"提案","question":"私もこういう情報は皆さんご存じなのですかねということを提案してみようかなと思いますので。これは要望にとどめますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"}]},{"id":"topic-02","title":"はじめに、(1)東京都による高潮浸水想定区域図の公表","agenda":"はじめに、(1)東京都による高潮浸水想定区域図の公表","exchanges":[{"speaker":"塚本委員","kind":"質問","question":"説明ありがとうございました。これはどういうぐらいの事態なのですかというか、もしあったのであれば、どんなものがあったのかというのを最初にお伺いしたいと思います。","respondent":"平原防災課長","answer":"具体的には上陸時の中心気圧が９１０ヘクトパスカルといったものでございまして、そういったときに、目黒川のところに影響が出るといったところです。それから、東京湾沿岸の２３区のところですが、大正６年台風のときに高潮被害が出たというのが記録として残っているところです。","id":"exchange-025"},{"speaker":"塚本委員","kind":"質問","question":"避難の指示とか、そういったものの発令の手順というのですか、想定というのは現在どのようになっているのか。町会・自治会への周知も区の対応としてやっていただくことになると伺いましたけれども、現在、備えがなされているかについて伺いたいと思います。","respondent":"平原防災課長","answer":"実際に令和元年の台風１９号のとき、あるいは平成３０年、そういったときに高潮警報が出まして、避難発令をかけたことがあります。何らかの認識はあるかなと思いますし、品川区防災地図であるとか、しっかり今後も周知に努めてまいりたいと考えています。","id":"exchange-026"},{"speaker":"塚本委員","kind":"質問・要望","question":"ありがとうございました。心配するところもあるので、周知というところについてはぜひしっかりと努めてほしいと求めましたので、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"ひがし委員","kind":"意見","question":"２点ほど聞かせてください。避難する場所への影響は少ないと認識していいのかという点がまず１点と、いつ、具体的なところもお知らせほしいと求めました。","respondent":"平原防災課長","answer":"全く影響ございませんというか、そこに今回変更がかかるものではございませんので、高潮浸水想定区域外の学校を指定緊急避難所として指定しています。今後の説明につきましては、いわゆる出水期と呼ばれる６月以降に特に関係するものですので、作業を進めております。","id":"exchange-028"},{"speaker":"ひがし委員","kind":"質問・要望","question":"６月までに間に合うようにということで、町会の方々と話したときにも、自治会の方々への周知というところもしっかりとしていただきたいなと思います。こちらは要望で終了とします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"石田（ち）委員","kind":"質問","question":"１週間以上浸水し続けるというところがぽつぽつあって、一番低い水色で０時間以上１２時間未満となっているのですけれども、こうならないようにするための対策は何か打てるのでしょうかというのを伺いたいと思います。","respondent":"平原防災課長","answer":"高潮ですけれども、いわゆる通常の洪水害よりも流入水量が多いといった特徴があります。もう一つは、そういったところと相まって、私どものいわゆる避難的なソフト対策といったところを重ね合わせていく必要があるのかなと考えています。","id":"exchange-030"},{"speaker":"石田（ち）委員","kind":"質問","question":"分かりました。１週間以上も水がはけないのかなと、こうならないような計画があったりするのか、お伺いしたいと思います。","respondent":"平原防災課長","answer":"なお、私ども防災の者も対象となったような形で情報提供を受けているところですので、都としっかり連携した形で進めしています。浸水深のところの継続時間ですけれども、消防と連携させていただきまして、そういったところにつきましても検討させていただいているところです。","id":"exchange-031"}]},{"id":"topic-03","title":"トイレトラックの導入","agenda":"トイレトラックの導入","exchanges":[{"speaker":"えのした委員","kind":"質問","question":"こちらの上位２案というのは、それは伺ってもいいのかなというところと、やはりトイレの問題は平時でも結構困っているところがあるのです。例えばどういった基準ですとか、日曜日だけとか、何かその辺のイメージがあれば教えていただけますか尋ねました。","respondent":"羽鳥防災体制整備担当課長","answer":"年間を通してのイベント等での活用につきましては、ぜひ積極的に活用していただきたいと考えています。１５日には能登に被災地支援ということで現地に向かっているというケースもありますので、被災地支援というところも踏まえながら、できる限り。","id":"exchange-032"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"その中で、一つ、クラウドファンディング、１,４００万円ですか、すごいですね、うれしいですね。企業から１,０００万円、ふるさとチョイスで一般の方から５００万円ですか、まずそこら辺の感覚を説明を求めました。","respondent":"羽鳥防災体制整備担当課長","answer":"クラウドファンディング、１１月頭から募集を始めまして、それ以前から区内の企業・団体にもご説明させていただいておりました。２３区で初というところで、この思いをしっかりと受け止めて、区の災害時のトイレ事業に活かしていきたいと考えています。","id":"exchange-033"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"これはまさしく２３区初、現在１台、私はこういった事業はしっかりとまた拡充していきたいと要望します。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"鈴木委員","kind":"質問・要望","question":"品川区が被害に遭ったときには、災害派遣トイレネットワークプロジェクトに参加している自治体はどれぐらいあるのか、教えてほしいと求めました。それと、３月３日調印式ということで書かれているのですけれども、この協定の中身というのはどんな中身なのかについても説明を求めました。","respondent":"羽鳥防災体制整備担当課長","answer":"予算につきましては、７月１日の建設委員会におきましてご説明させていただいたところです。歳入といたしまして、クラウドファンディングの寄附金といたしまして５００万円を見込んでいたです。","id":"exchange-035"},{"speaker":"鈴木委員","kind":"確認","question":"これが丸々ここに使われるということではないということなのでしょうか。その確認だけお願いします。","respondent":"羽鳥防災体制整備担当課長","answer":"クラウドファンディングの歳入につきましては、トイレトラックの購入についてご寄附いただいたものですので、トイレトラック導入事業に充てるということになってあります。","id":"exchange-036"},{"speaker":"須貝委員","kind":"質問","question":"１,３００人使ったらもう駄目、どこかの公園なり、どうでしょうか。そういうことを自治体としても考えていかなければいけないと私は思うのですが、ご見解を説明を求めました。","respondent":"羽鳥防災体制整備担当課長","answer":"もちろんトイレトラック、区としても１台、また、災害派遣トイレネットワークプロジェクトを活用してもまだ２５自治体という状況です。今回新たにトイレトラックという新しい機能を追加したということでご理解いただければと考えています。","id":"exchange-037"},{"speaker":"須貝委員","kind":"質問・要望","question":"これから災害時にどうするのだ、やはりよりいいものを避難民の方は求めると思うので、何とか考えていただきたいと私は思います。先に契約したら１円も出さないという、こんなばかなこと、私は抗議してほしいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-038"},{"speaker":"塚本委員","kind":"質問・要望","question":"伺いたいのは、平成１９年以降の人が今後、その免許の壁を越えるにはどうすればいいのかというところが気になるのでお知らせいただきたいのと。ちょっと教えてもらえれば、設置して、使えるようにできるというようなものなのかどうかといったところについても説明を求めました。","respondent":"羽鳥防災体制整備担当課長","answer":"設置について、周知して、実際に啓発のときにも説明できるような体制はとってまいります。物資輸送と同じように、区の職員も同行して、現地に設置するときに被災地の方に説明をしてという対応も想定しています。","id":"exchange-039"},{"speaker":"ゆきた副委員長","kind":"質問","question":"では１点だけお聞きできればと思います。しながわ区民公園に置かれるということを伺っていますが、どのような事前の周知をしていかれるのか、お聞きできればと思います。","respondent":"羽鳥防災体制整備担当課長","answer":"その際に、しっかり使い方を説明できるように、啓発をしてまいりたいと考えています。しながわ水族館来館者が立ち寄るケースもあると思いますので、そういった本当に幅広い方に説明できるように、調整してまいりたいと考えております。","id":"exchange-040"},{"speaker":"高橋（伸）委員","kind":"確認","question":"ジュニアランとファミリーランで約７５０名いて、しながわ区民公園というのを確認いたしましたが、トイレ１回で４００リットルですよね。お披露目ですから、その辺は今どういうふうに計画されているのか、まず１点。","respondent":"羽鳥防災体制整備担当課長","answer":"当日の運用方法についてですけれども、しながわ区民公園の管理事務所棟前に汚水ますがございまして、そちらに直結させる想定で考えてあります。ですので、汚水タンクにためるというよりは、下水に直結させて利用するということを今想定しています。","id":"exchange-041"},{"speaker":"高橋（伸）委員","kind":"確認","question":"その確認が一つと、４０件あって、皆さん掲載するようになっているのか尋ねました。","respondent":"羽鳥防災体制整備担当課長","answer":"車庫につきましては、委員おっしゃったとおり、地震体験車と同じように、第２庁舎１階の駐車場になります。個人の方も、意外に希望されない方もいらっしゃったので、全ての希望される方は後部にしっかり記載できるよう、今、確認はとれています。","id":"exchange-042"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"なぜこういう質問をするかというと、例えば８４３万円だったら８４３とか、そういうナンバープレートにしているのです。何かそういうのはお考えになったのかなと思って、そこだけ確認させてほしいと求めました。","respondent":"羽鳥防災体制整備担当課長","answer":"ナンバーにつきましては特に考えておりませんでしたので、今ご提案いただきましたので、早急に確認してまいりたいと思います。","id":"exchange-043"}]},{"id":"topic-04","title":"令和６年度地区総合防災訓練等の実施結果","agenda":"令和６年度地区総合防災訓練等の実施結果","exchanges":[{"speaker":"こんの委員","kind":"確認","question":"前にも伺ったことがあるかもしれないのですけれども、確認ですが、自分たちでこういう訓練をやりたいと決めるのか。どんなふうにそれぞれの地区の方たちは選んで、こうしたことをされているのか、様子なども伺いたいと思います。","respondent":"伊藤災害対策担当課長","answer":"ＰＬＵＳ ＯＮＥを実施した地域だけではなく、そのほかの地域でも、説明をさせていただければと存じます。小さめの消火器を使った消火訓練など、いろいろ親子で参加していただくようなプログラムも各地域によって検討され、実施をされてきたところです。","id":"exchange-044"},{"speaker":"こんの委員","kind":"質問","question":"こうしたことの訓練は、しようか、どうしようかという検討などがされているのか。やりましょうという促しとかはされているのか、現状、その点に関する訓練について説明を求めました。","respondent":"伊藤災害対策担当課長","answer":"子ども用スペースにするのか、要支援者が滞在するところにするのかなど、確認する機会として訓練の機会を使ったと伺っております。やはり避難所運営マニュアルの変更があったということで、見直し、どこにするのかというのを確認したという避難所が多かったと伺っております。","id":"exchange-045"},{"speaker":"こんの委員","kind":"質問","question":"レイアウトというか、避難所内のスペース確保というか、そうしたところをされたところは結構あったということでよろしいのでしょうか。もう少し訓練の内容について、区としても促し方が必要ではないかと、この内容からそう思われるのですが、その点はいかがか尋ねました。","respondent":"伊藤災害対策担当課長","answer":"やはり一定の方々しか持っていない知識というのは、非常に危険というか、十分ではないと私たちも認識しております。さらに、各避難所連絡会議をやるときにも共有させていただいて、こういった訓練もあるのだよというのを共有させていただきたいと考えております。","id":"exchange-046"},{"speaker":"こんの委員","kind":"意見","question":"いろいろな訓練のメニューをどういった避難所でされているかという情報共有や情報交換をしながらといったところは、より実効性のあるというか、こうしたことを学んでおけば災害時に動けるといった実効性あるものに近づけるような訓練の内容をぜひお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-047"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ペットも、わんちゃんだけではなくて猫ちゃんもいるし、ほかにもいろいろと種類がありますよね。具体的にどうしていくのかとか、そういうところの体制はどうなっているのでしょうというお問合せがあったので、お聞かせいただきたいなと思います。","respondent":"伊藤災害対策担当課長","answer":"具体的な事例を挙げていただきまして、ありがとうございました。備蓄の面も含めまして、ペットも含めまして、検討をさらに進めてまいりたいと考えています。","id":"exchange-048"},{"speaker":"ひがし委員","kind":"質問・要望","question":"テントというのですか、何名かが入るようなテントというのですか、一般の方々とかが過ごすスペースはどうなるのかなというところも教えてほしいと求めました。","respondent":"羽鳥防災体制整備担当課長、大倉委員長","answer":"５０張りですと、大体体育館の半面に設置できるようなイメージになってあります。支援物資という形で届いてきたものを活用していくという、フェーズに応じた対応になっていくかと考えていますが、現状。 令和６年度の防災訓練等の実施結果ということで、そこはご注意いただくというか、ご配慮いただいてお願いいたします。","id":"exchange-049"},{"speaker":"えのした委員","kind":"確認","question":"今回５地区でしたか確認です、まだ８地区かな、アップデートする形で続けていっていただけるのかというところをお聞かせ願えますか尋ねました。","respondent":"伊藤災害対策担当課長","answer":"来年度もいろいろ展望というか考えがあるということと、実施していない３地区の会長につきましても、会場がなかなか。どういったやり方になるか、我々の支援の仕方もまた検討していかなければならないと思いますが、我々のゴールとして持っていきたいと考えています。","id":"exchange-050"},{"speaker":"えのした委員","kind":"質問・要望","question":"確認がとれました。私も町会でいうと、やはりまずは参加していただくというところを促すような取組を期待しておりますので、私から要望します。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-051"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"ここら辺を１回教えていただきたいのと、１０人、２０人でいく。これはぜひ続けていただきたいのですけれども、３割ぐらいが新しい方という部分になったときに、すみません。","respondent":"伊藤災害対策担当課長","answer":"まず、防災協議会の皆さんが考えている訓練内容を実施させていただいているということですので、我々は支援をするスタンスであることは。ただ、やはりお子さんが参加されて、親御さんも参加されたということで、新たな方、また人数が増えたのかなという認識は持っております。","id":"exchange-052"},{"speaker":"まつざわ委員","kind":"質問","question":"ずっと質問していたのですごくうれしくて、でもそれをどう活かしていくか、避難所運営委員会の長というのは結局町会長なのですよね。何と言えばいいのでしょうか、去年のこれを見て、どういくのかなというのを聞かせてください。","respondent":"伊藤災害対策担当課長","answer":"可能な範囲では対応して、できないことはできませんというお話はさせていただいたのですが、職員も入って意見を言わせていただく体制をとっていると。徐々に変えていっている、いけているのではないかと私は感じているところですので、そのところでご了承いただければと存じます。","id":"exchange-053"},{"speaker":"まつざわ委員","kind":"意見","question":"ＰＬＵＳ ＯＮＥすると、それが避難所訓練でも町会長が見ているというのはとてもいい取組なので、私も全部とは言いません、例えばモデルで１地区、２地区限定してでも、好事例を一度、方向性を示してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-054"},{"speaker":"須貝委員","kind":"質問・要望","question":"どこに何があってどうすればいいのだ、１枚の冊子でもいいのですけれども、やらないと駄目なのかなと感じています。ですから、質問というよりは、自分の意見で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-055"},{"speaker":"吉田委員","kind":"質問・要望","question":"どうしていらしたのですかと言ったら、どういう訓練が行われているのかを見に来たということで、参加されたということなのです。広報に関して、聴覚障害者協会が求めている広報と区が広報しましたという認識に差があるのかなと思ったのですが、その点についてはいかがか尋ねました。","respondent":"伊藤災害対策担当課長","answer":"その前に、視覚障害であるとか身体だとかという方も連絡員の方にはご説明をして、広報していただくようにはお話をさせていただいたところです。結局は伝わっていないという認識ですので、しっかりと必要な方に必要な情報が届くように、次回は対応させていただきたいと思います。","id":"exchange-056"},{"speaker":"吉田委員","kind":"質問・要望","question":"でも福祉の一環ですよね、ぜひ福祉制度以外のところにも参加してほしいという記載など、ぜひそのようにしていただけたらと思います。これについては要望でとどめますので、ぜひ今後、前向きに検討していただけたらと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-057"}]},{"id":"topic-05","title":"令和６年度弾道ミサイルを想定した国民保護共同訓練","agenda":"令和６年度弾道ミサイルを想定した国民保護共同訓練","exchanges":[{"speaker":"ひがし委員","kind":"質問・要望","question":"簡単に２点ほど聞かせてください。は都からこの場所でしてくれと言われたのかというところを確認させていただきたいのが１点と、あとは、併せて聞かせていただけたらと思います。","respondent":"伊藤災害対策担当課長","answer":"さきにご説明いたしました、都営の施設であるということから、東京都のほうで指定があったと。東京都の説明文書の中で、おおむね１５名程度の方の参加を計画しているという状況で、今進んでいるです。","id":"exchange-058"},{"speaker":"石田（ち）委員","kind":"確認","question":"幾つか伺いたいのですけれども、要するに品川区にミサイルが着弾したことを想定した訓練ということでいいのか確認したいのと、伺いたいと思います。それで、除染活動とありますけれども、これは何の除染なのか、伺いたいと思います。","respondent":"伊藤災害対策担当課長","answer":"1)のフェーズ１ですけれども、会場1)戸越駅で実施する訓練につきましては、ミサイルが落ちたという想定ではございません。簡易除染といって、その場に応じた方法で除染を行った後に、安全な場所に搬送するといったような訓練が想定されているという状況です。","id":"exchange-059"},{"speaker":"石田（ち）委員","kind":"質問","question":"本当に飛んだときにあることなのか伺いたいのと、要救助者の救出ということなのですね、今の説明だと。要するに何を除染している、化学物質というものは何を想定しているのか、もうちょっと詳しく伺えたらと思うのですけれども。","respondent":"伊藤災害対策担当課長","answer":"こちらについては東京都の想定になっておりますので、そちらで検討された内容となっております。除染をして、中野区と同様の訓練と聞いておりますので、同じようなことをするのではないかと考えております。","id":"exchange-060"},{"speaker":"石田（ち）委員","kind":"質問","question":"分かりました。３ 参加関係機関というところでは、総勢何人になるのか、伺いたいと思います。","respondent":"伊藤災害対策担当課長","answer":"全て含めますと、１００名程度になると聞いてあります。区職員については、おおむね３０名程度が、参加も含めて、安全管理だとかも含めて、参加するです。","id":"exchange-061"},{"speaker":"石田（ち）委員","kind":"質問","question":"何町会ぐらいなのか伺いたいのと、４に移りますけれども、この近隣町会はどこなのか。ホームページには１２月１３日に載せられたというところは見たのですけれども、出すのか、伺いたいと思います。","respondent":"伊藤災害対策担当課長","answer":"町会への説明ですけれども、今のところ、３町会を想定しております。それから学校への説明ですけれども、こちらの説明にありますとおり、こちらで説明を行っていると。","id":"exchange-062"},{"speaker":"石田（ち）委員","kind":"質問","question":"それと、訓練当日の２月４日、戸越台中学校の防災訓練と聞いていますが、この弾道ミサイルの訓練に合流するということはあるのでしょうか。たまたま日にちが重なったということとは何となく思えないのですけれども、そこはいかがか尋ねました。","respondent":"伊藤災害対策担当課長","answer":"誰に説明をしたかですけれども、荏原第三連合町会長には私のほうから説明しまして、係長のほうから訓練を行うという説明を行ってあります。私どもも、必ずしも併せて訓練する必要ございませんということで説明のほうはしています。","id":"exchange-063"},{"speaker":"石田（ち）委員","kind":"確認","question":"それで、戸越台中学校ですよね、合流することはない、ないということで確認していいですよね。一緒にというところを聞いたときに、もしや合流ということもあり得るのかなと思ったのですけれども、そこはないということでよろしいか尋ねました。","respondent":"伊藤災害対策担当課長","answer":"繰り返しになりますけれども、戸越台中学校の生徒が参加するということはございません。","id":"exchange-064"},{"speaker":"石田（ち）委員","kind":"質問","question":"それで、ミサイルが飛んだということになれば、しかもその一部が落ちてくるという訓練ですけれども、ひと度飛べば戦争になるわけではないですか。駅に避難する訓練というところでは、そこら辺はどれだけ備蓄があるのか、そういうところも把握されているのか尋ねました。","respondent":"伊藤災害対策担当課長","answer":"１点目、斜めの軌道で飛んでくるということもありますので、そこは非常に何とも難しいところだとは思います。その場に応じて対応していただくしかないかなと考えています。","id":"exchange-065"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そうした武力衝突を起こさないような、武力衝突などの事態をそもそも起こさないことを国や東京都に求めていくべきではないのかなと先に思うのです。なので、そこら辺は東京都や国に求めるべきだと思うのですけれども、いかがか尋ねました。","respondent":"伊藤災害対策担当課長","answer":"区である程度、都の意向に沿ってやっていくべきであるということで、訓練をやる方向で今進めている状況です。今、委員からお話のありましたご意見につきましては、東京都のほうにも伝えしますので、ご了承いただければと存じます。","id":"exchange-066"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"だから一番大事なのは、武力衝突などの事態をそもそも起こさないということだと思うのです。国や都に求めて、そういう立場に立って、平和を守る対応をしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-067"},{"speaker":"吉田委員","kind":"質問","question":"そのときも課長が対応してくださったので繰り返しの質問になりますが、品川区がこれを了承した日にちについて、そういうスケジュール的なことをまず伺いたいと思います。","respondent":"伊藤災害対策担当課長","answer":"本年度の４月ぐらいに東京都から打診がありまして、その後、検討してまいりました。５月・６月と検討して、その中で決定していったという状況です。","id":"exchange-068"},{"speaker":"吉田委員","kind":"質問","question":"決定したのが６月。東京都にそれを回答したのはいつか尋ねました。","respondent":"伊藤災害対策担当課長","answer":"決定もそのまま、６月ないしは７月に入るかどうかという時点だったと記憶しています。","id":"exchange-069"},{"speaker":"吉田委員","kind":"質問","question":"それで、ホームページに公開されたのが２０２４年１２月ということですよね。その期間、なぜそれを空けたのかも伺いたいと思います。","respondent":"伊藤災害対策担当課長","answer":"こちらは、主催である東京都と足並みをそろえまして、１２月１３日に東京都知事が訓練の公表を行うというところで、併せて区内でも公表させていただきました。","id":"exchange-070"},{"speaker":"吉田委員","kind":"質問","question":"では、あくまで東京都が、まだそこまでは公表しないので、品川区としても公表を差し控えたということでよろしいのでしょうか。一番影響があるのは品川区民なので、品川区民にその前に何かの形で公表するということは考えられなかったのか、伺います。","respondent":"伊藤災害対策担当課長","answer":"東京都からも足並みをそろえるということで、公表のほうは同じような日程でさせていただきました。","id":"exchange-071"},{"speaker":"吉田委員","kind":"提案","question":"それとも、あくまでそれは東京都が提案をしたという形になっているのでしょうか。その辺についても伺いますとの意見を述べました。","respondent":"伊藤災害対策担当課長","answer":"基本的にこの訓練につきましては東京都が主導して、いろいろなところに声をかけていただいたと認識しています。","id":"exchange-072"},{"speaker":"吉田委員","kind":"提案","question":"例えば訓練内容について商店街に提案する際にも、説明されたのも東京都ということなのでしょうか。東京都としてどういう訓練を行うということの資料提供も、商店街などに説明されたのかについても伺いたいと思いますとの意見を述べました。","respondent":"伊藤災害対策担当課長","answer":"例えば戸越銀座商店街につきましては、こちら、区の所属ということもありますので、区側から説明をしていますが、その他の、例えばアパホテルであるとかの近隣の商業施設については、東京都から説明を行うと聞いてあります。","id":"exchange-073"},{"speaker":"吉田委員","kind":"質問・要望","question":"では、あくまで東京都がやることだからということで、品川区は、協力というのでしょうか、一緒にやるということですね。この間伺って、把握しておられたら教えていただきたいのですけれども、いかがか尋ねました。","respondent":"伊藤災害対策担当課長","answer":"大変申し訳ございません。東京都の事案になりますので、予算のほうは当方では把握してございません。","id":"exchange-074"},{"speaker":"吉田委員","kind":"提案","question":"この間、私たちもご説明を受けたのですが、防災行政無線を活用するということは紛れもない事実ではないですか。提案というのでしょうか、許可を求めたのかよく分からないのですけれども、伺いたいと思いますとの意見を述べました。","respondent":"伊藤災害対策担当課長","answer":"防災行政無線を使用することにつきましては、教育委員会を通じては行っておらず、防災課から戸越台中学校に連絡をしています。その件につきましても、教育委員会と情報共有はしています。","id":"exchange-075"},{"speaker":"吉田委員","kind":"質問","question":"要はこの事実をどういうふうに考えておられるかというようなことを伺ったときに、今、即答はしかねますというお返事だったのです。分からない、防災課としてはきちんと教育委員会を通して、教育委員会事務局を通してという認識でおられるということでよろしいか尋ねました。","respondent":"伊藤災害対策担当課長","answer":"先ほど申し上げましたとおり、戸越台中学校には防災課から申入れを行っております。教育委員会に対しては、教育委員会の中での動きになりますので、私からは答弁は差し控えさせていただければと存じます。","id":"exchange-076"},{"speaker":"吉田委員","kind":"質問・要望","question":"こういうことが起きるのだということを刷り込んでいくということを危惧するメンバーが周りには大変多いということです。その点については、子どもの権利という視点からも、ぜひ考えてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-077"},{"speaker":"鈴木委員","kind":"質問・要望","question":"この１００名がどこにどういう形で訓練するのかなというのがよく見えないので教えていただきたいのですが、地下鉄の戸越駅に住民１５人が避難する。その他の（３）なのですけれども、訓練時間は９時半から１１時半なのですけれども、どんな規制なのかも伺えたらと思います。","respondent":"伊藤災害対策担当課長","answer":"自衛隊などは５０名程度で訓練を行って、そういった形で５０名程度想定しているということで、全てで１００名というようなことで考えてあります。それから、やはり訓練の説明は必要だと考えておりますので…","id":"exchange-078"},{"speaker":"鈴木委員","kind":"質問","question":"国道１号線とか交通規制されるとすごく大変そうな感じがするのですけれども、そこら辺、把握されなくて大丈夫なのでしょうか。品川区の職員は戸越駅のほうに行ってしまうので、ここには品川区は入らないで、ここの人たちの５０人が、何の訓練をするのか尋ねました。","respondent":"伊藤災害対策担当課長","answer":"こちらは警視庁の管轄になると思いますので、道路のほうは東京都のほうでしっかりと対応していただける、安全管理も含めて。先ほど３０名と申しました訓練参加者については区の職員の話ですので、交通規制に関するところは、警察官のほうが対応していただけると考えています。","id":"exchange-079"},{"speaker":"鈴木委員","kind":"質問・要望","question":"共産党区議団としても、東京都に対してと品川区に対して、これからこういう訓練の中止を求める要請を今週行っていく予定にしています。この訓練に対してはきっぱりとやるべきではないというところで、答弁は求めませんけれども、そういう主張はしっかりと行っておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-080"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/779403?Template=document&Id=6947#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":67065,"voices":207}},{"id":"r07-20250123-10","meetingId":"r07-cm01","date":"2025年1月23日","dateIso":"2025-01-23","committee":"議会運営委員会","time":"午後 １時００分～午後 １時２５分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を6件整理しています。","topics":[{"id":"topic-01","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"意見","question":"家庭も大変な負担の中で、そうした手段を取るというのは、やはりこれはすべきでないと私は思います。果たしてそれが減量化につながるのかどうかも含めて慎重な検討が必要だと考えていますので、それを踏まえていろいろ対応してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"}]},{"id":"topic-02","title":"意見書（案）","agenda":"意見書（案）","exchanges":[{"speaker":"西村委員","kind":"質問・要望","question":"意見を表明し、国会や政府に真摯な議論を尽くすよう、このタイミングで求める意見書の検討を行いたいと考えました。この間進めてまいりたいと考えていますので、ご意見がありましたらぜひ、１月中にいただければと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"今後の流れについては分かりました。内容について少しお伺いしたいのですけれど、どういう立場から議論を求めるものなのかというのは、どういう案文になっているのか伺いたいです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"西村委員","kind":"質問・要望","question":"タイトルもそうですけれども、賛成の側の意見もありますし、反対の意見もある。進めてほしいと言っていらっしゃる方々の困っている事象、国のほうで議論を進めるべきだということを地方議会から求めるという意見書になっています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"そうなりますと、やはりむしろ選択的夫婦別姓の導入を求める内容にするのが、こちらの文言からすると自然なのではないかなと思うのです。導入の国会審議を求めるという、導入を求める意見書としたほうがいいと思うのですけれど、そこについては御意見いかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"西村委員","kind":"質問・要望","question":"これから１月中にいただければと思うのですが、会派のほうからぜひ皆様に、お持ち帰りいただいてご意見ほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/982705?Template=document&Id=6949#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":9034,"voices":49}},{"id":"r07-20250218-10","meetingId":"r07-cm02","date":"2025年2月18日","dateIso":"2025-02-18","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時２７分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を11件整理しています。","topics":[{"id":"topic-01","title":"ＩＣＴ推進会議からの報告事項","agenda":"ＩＣＴ推進会議からの報告事項","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"あるならば、必要な増員をはじめ、労働環境の改善こそ行うべきではないでしょうか。かつ事務局の負担も最小限に抑えられる案というのを具体的に提案したのですが、これも残念ながら受け入れられることはなかったですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"},{"speaker":"こしば委員","kind":"意見","question":"先ほど石田秀男リーダーからご報告がありましたとおり、これまでＩＣＴ推進会議で協議を重ねてきて、その協議事項について決を採ると判断され、それで、賛成多数で電子での配付に一本化すべきという結論に至ったということで、その結論を尊重すべきと考えますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"須貝委員","kind":"意見","question":"そうしたら、何をやっているのだという区民からの批判も、私は受けるのではないかと思います。だから、今回の石田秀男リーダーの考え方、またそこに所属する委員の方々の考え方は、私は間違っていないと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"}]},{"id":"topic-02","title":"令和７年第１回定例会","agenda":"令和７年第１回定例会","exchanges":[{"speaker":"西村委員","kind":"提案","question":"今後の流れですけれども、２月２１日の金曜日、３日目に提出をしたいと考えています。提案説明はまつざわ委員長が行いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"安藤委員","kind":"提案","question":"内容をご確認の上、ぜひこちらにもご賛同、可決していただきますよう、よろしくお願いしたいと思います。いかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"安藤委員","kind":"提案","question":"先ほど提案させていただいたのですが、区民からの請願がそういうタイトルで上がっているわけですから、やはり熟議するという意味でも。なので、日程変更を提案させていただいたのですが、そこについては委員長、検討してもらえないか尋ねました。","respondent":"まつざわ委員長","answer":"今、安藤委員からお話がありましたけれども、あくつ副議長からのお話もありました。付託が決まっていない部分もありますし、粛々とこのままの日程で進めていきたいと私は思っております。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問・要望","question":"両方とも選択的夫婦別姓制度の早期実現を求める意見書ということで、その内容で、みんなでそれを応援して国に求めるという。こうやって２つ出すと、国にそういう意見を求めるということのほうが、私はきれいだったのではないかなという気がします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問・要望","question":"付託される予定のものもあり、これから議論もありますので、最終本会議に提出させていただきたいというふうに変更してもよろしいですか。なので、提出者ということで、時期を決められるということであれば、この場で申し訳ないのですけれども、変更をお願いしたいのですが。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"山本委員","kind":"質問・要望","question":"賛成は挙手によるものとしていただきたいということ、今回の一般質問では車椅子で演壇に登壇すること、以上の３点をご了承いただきたく存じます。ご検討を。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"}]},{"id":"topic-03","title":"予算特別委員会","agenda":"予算特別委員会","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"その際は、何か検討などは行われたのでしょうかということを伺いたいのと、いかがでしょうかというのが１点目です。その際は、ぜひご審議のほど。","respondent":"大澤区議会事務局長","answer":"できるだけというか、区民の皆様にお知らせする時期が遅くなってしまうということがありますので、ご協力をお願いしたいと存じます。どうしてもというときは、個別に事務局にご相談ください。","id":"exchange-010"}]},{"id":"topic-04","title":"品川区議会個人情報の保護に関する条例","agenda":"品川区議会個人情報の保護に関する条例","exchanges":[{"speaker":"安藤委員","kind":"意見","question":"基となる刑法等の一部改正については、刑法の根幹を変える重大な改悪だと、共産党も反対しているのですが、今回は、法が変更されたことによる文言整理ということで、実際の個人情報の取扱いに変化はないということですので、賛成いたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/982705?Template=document&Id=6951#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":19568,"voices":82}},{"id":"r07-20250219-10","meetingId":"r07-cm02","date":"2025年2月19日","dateIso":"2025-02-19","committee":"議会運営委員会","time":"午後 ０時４５分～午後 ０時４７分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/982705?Template=document&Id=7073#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":1445,"voices":12}},{"id":"r07-20250221-3","meetingId":"r07-c-budget","date":"2025年2月21日","dateIso":"2025-02-21","committee":"予算特別委員会","time":"午後 ２時１４分～午後 ２時２２分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/552633?Template=document&Id=6999#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":2070,"voices":17}},{"id":"r07-20250225-6","meetingId":"r07-cm02","date":"2025年2月25日","dateIso":"2025-02-25","committee":"区民委員会","time":"午前１０時００分～午後 ３時１８分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を105件整理しています。","topics":[{"id":"topic-01","title":"令和５年陳情第３１号、行政が運営主体となる新規火葬場建設を求める陳情","agenda":"令和５年陳情第３１号、行政が運営主体となる新規火葬場建設を求める陳情","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"その規定というのは具体的にはどういうふうになっているのか、東京博善株式会社が経営する桐ヶ谷斎場の２か所だと思うのですけれども、伺いたいと思います。","respondent":"赤木生活衛生課長","answer":"墓地埋葬法に基づく経営主体につきましてのご質問にお答えいたします。その特段の事情というところの部分で、経営主体として東京博善のほうが認められているということが現状となっております。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"これは別によくも悪くも、利益を上げるということが使命になってくるわけですから、そういう区民の悩みについてはどのようにお考えなのでしょうか。どのように対応するのか伺いたいと思います。","respondent":"赤木生活衛生課長","answer":"それ以外の部分で出た収益の部分を、会計自体を分離するというところを令和５年度から実施していただいております。火葬の中で火葬場で出た収益が株主配当だとかといったところに回らないようになっているということで先方から説明は受けておりまして。","id":"exchange-002"},{"speaker":"おぎの委員","kind":"質問・要望","question":"やはりそこで利益を上げるのはどうなのかなという部分は私も感じていますので、民間の動向を注視していただきたいなというのがあります。１点お聞きしたいのは、今年度東京都が予算を組んでいるという話も聞くのですけれども、何かお聞きにはなっていますか。","respondent":"築山戸籍住民課長","answer":"都の予算ですけれども、こちらのほうでは確認できていないところですので、情報収集に努めたいと思います。","id":"exchange-003"},{"speaker":"おぎの委員","kind":"質問・要望","question":"恐らく、２３区の区長会で要望が出されて、都のほうも少し考えているというお話を聞いていますので、引き続き注視していただきたいなと思います。恐らく臨海斎場があるので、東京都が動き出したとしても品川区にはもうこれ以上は難しいのかなとは思いますが、引き続き。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"吉田副委員長","kind":"質問","question":"それで、ホームページ上で公開ということですけれども、例えば、これについての監査とかは東京都の範囲になるのでしょうか。区としては、報告とかそれからそういう会計についての監査をするような権限は保障されていないのか、その辺について伺いたいと思います。","respondent":"赤木生活衛生課長","answer":"その６区合同で、令和４年度に、そこの部分がしっかりと履行されているかどうかの確認を今年度させていただいたところです。そういった中で出てきた資料の中で、修繕計画がしっかりと立てられていることにつきまして確認をさせていただいたところです。","id":"exchange-005"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"それから、やはりどうしても気になるのが、ご遺体を焼くわけですから、その排気です。その辺についての、博善社に対する注意とか、それから排気の状況の調査とかその辺についてはどうなっているのか伺いたいと思います。","respondent":"赤木生活衛生課長","answer":"副葬品等の排気であったり、遺体を火葬した後のところについてのご質問かと思います。細かくお伺いは、先ほど情報としてご意見をいただきましたので、そういったところも含めて我々のほうでも確認をしてまいりたいと思います。","id":"exchange-006"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"何度もはね返されているので承知しているのですが、ぜひその辺は区としても、地域の方たちに寄り添って求め続けていただきたいなと思います。そのことは要望にとどめます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"この５区の中に民間があるのか分からないですが、それとも臨海斎場だけでカウントしているのか、そこら辺を教えてもらえますか尋ねました。","respondent":"築山戸籍住民課長","answer":"ピークへの対応の考え方ですが、こちらは桐ヶ谷斎場も含めてというものになっております。","id":"exchange-008"},{"speaker":"せお委員","kind":"意見","question":"継続でお願いします。今後もずっと続いていくこういう課題に対しては、真摯に取り組んでいかなければいけないなという思いがありますので、継続でお願いいたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"ゆきた委員","kind":"確認","question":"臨海５区においては臨海斎場があって、火葬炉も新設にてさらなる充実が図られていることを確認させていただきました。公営火葬場の新設等に対して自治体への支援を行うべきだとの質疑に対して、東京都は、都市計画交付金の仕組みを活用して支援すると答弁しています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"先ほども申し上げたのですが、やはり本当に高価だし、増やしてほしいという意見はあるのです。それから、使いやすい斎場を求めて運動もしてきたのですが、今の段階ではそちらの臨海斎場のほうの機能を拡充するということで確認ができましたので。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"安藤委員","kind":"質問","question":"今回、継続で私もお願いしたいのですが、やはり、とはいえ葬祭料が桐ヶ谷は高いというふうに伺いますし、高齢化もこれから本格化すると。臨海斎場の動きなどもありますので、今回は、継続ということでお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"藤原委員","kind":"意見","question":"それで、もっともっと深くこれは議論していかないといけないと思っています。新規でするならばどこの場所にどういう予算をという意味においてもありますので、これ、大事な議論の一つだと思っていますので、継続させてくださいとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"２３区の区長会もいろいろな動きをしていますし、とは言っても、一つ一つ課題解決できるものは解決していっていただきたいなと思います。ぜひ、そういったものを我々としても注視をしていきたいということで、継続したいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"おぎの委員","kind":"意見","question":"都内の火葬場の７か所がもうほぼ、民営になっていて、やはり、民営はどうしても経営面や株主の意向が入るので、値段が高くなってしまうのです。〔「公営」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"おぎの委員","kind":"意見","question":"桐ケ谷も民間だから高くなってしまうので、あれも公営にしてもいいのではないかぐらいに思ってはいるのです。やはり重要な問題なので、引き続き注視していきたいと思いますので、継続でお願いしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"}]},{"id":"topic-02","title":"第１７号議案、品川区歩行喫煙および吸い殻・空き缶等の投げ捨ての防止に関する条例の一部を改正する条例","agenda":"第１７号議案、品川区歩行喫煙および吸い殻・空き缶等の投げ捨ての防止に関する条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"改正趣旨について幾つかお伺いしたいのですが、区民等から苦情、規制強化を求める声が多く寄せられているとありますが。伺いたいと思います。","respondent":"河合生活安全担当課長","answer":"さきの区民委員会でもご説明させていただきましたけれども、やはり歩きながら、全ての駅においてそういった状況は見られるという背景があります。やはりそういったところで、やはり迷惑性、危険性が否定できない喫煙というのは全ての駅で確認されたという結果になっております。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"分かりました。それぞれどこを勘案したのでしょうかというのと、パブリックコメント、ここら辺を踏まえましたみたいところがあれば改めて伺います。","respondent":"河合生活安全担当課長","answer":"そういった配慮義務があるにもかかわらず、そういったことを含めて全域に規制をかけるということを趣旨で踏まえたということになっております。現在の喫煙所の設置が不足している現状も踏まえまして、規制強化は段階的にやっていく上での第１弾、というところでやっております。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問・要望","question":"前段のほうですが、区内全域を対象にするというのが法や都条例の趣旨を勘案したということになるということなのでしょうか。そこら辺だけよく分からなかったのでお伺いします。","respondent":"河合生活安全担当課長","answer":"やはりそういったところでも配慮して喫煙しなければいけないのですよというような規定になっておりますので、その趣旨に合わせて、部分的な規制でなく全体としての規制が区でも必要だという判断でなっております。","id":"exchange-019"},{"speaker":"ゆきた委員","kind":"確認","question":"１点だけ、確認ですけれども、この辺についてお聞きできればと思います。","respondent":"河合生活安全担当課長","answer":"空き缶のポイ捨てに関しては努力義務という書きぶりにはなっておりません。実際、過料対象につきましては推進地区に絞られているのですけれども、罰則なしという形での禁止規定になっております。","id":"exchange-020"},{"speaker":"石田（し）委員","kind":"質問","question":"例えば人があまりいないところと比べたら、その辺どういうふうに、いわゆる喫煙所設置に当たって考えているのかというのが１点。でもそれは実は水蒸気ですよと言われたときにどうするのかというのもあるので、そういったところについてはどのように考えているのか説明を求めました。","respondent":"河合生活安全担当課長","answer":"１点目、周囲の歩行者等への配慮および適正な維持管理がなされていると区長が認め、というところで定める予定です。規制対象なのか外なのかというところは判断した上で指導、取締り等をしていくというところで考えております。","id":"exchange-021"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"これは要望です。それに対応できるものにしていただきたいと、これも要望で終わりますが、ぜひ。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"せお委員","kind":"質問・要望","question":"それと、それは誰が決めるのか教えていただきたい。それは今後、この７月１日から人を増やしていくのか、そこら辺を説明を求めました。","respondent":"河合生活安全担当課長","answer":"１点目の過料１万円以下というところは、規則のほうで１,０００円というところで、現在やっているところです。後段の質問は過料の取締りの人員のことでよろしかったですか。","id":"exchange-023"},{"speaker":"せお委員","kind":"質問","question":"この１万円以下という書き方は、それは１,０００円で決定しているのに、これは１,０００円と書かないのですか。ごめんなさい、分からなくてすみません。","respondent":"河合生活安全担当課長","answer":"その状況に応じて増減が見込まれる部分がありますので、そういった情勢で対応できるように下位法令のほうでその金額を定めるという形でやるというところで、条例的にはなっている形になります。","id":"exchange-024"},{"speaker":"せお委員","kind":"質問・要望","question":"１,０００円、それは今後進めていく中で、何か課題などが現れたら少し検討していただきたいなというところはあります。来年度予算をつけているということですか、どこら辺にそれをつけているのかだけ、最後に教えていただけますか。","respondent":"河合生活安全担当課長","answer":"なので、去年と比較すると少し増額になっていると思いますので、そこに含まれています。そういったところが増額になっていると思いますので、確認していただければと思います。","id":"exchange-025"},{"speaker":"おぎの委員","kind":"質問","question":"前回、この条例改正の前に、パブリックコメント等の結果が上がっていたとき、最後のほうで、民間で喫煙所を整備する場合の助成の話などが出ていたと思うのですけれども、これは、令和６年度は一応目標は１件だったのですが、今、民間の整備の件とかというのはどんな感じになっているのか尋ねました。","respondent":"河合生活安全担当課長","answer":"新規設置の件数も前年度と比較して増加と、そういった件数も大きく増加させて今、要求している状況です。次の審議でいただくという形になっております。","id":"exchange-026"},{"speaker":"おぎの委員","kind":"質問・要望","question":"私はたばこを吸わないですが、やはり売っている以上、吸われる方の場所も確保してあげないといけないなというのはありますので、進めていっていただきたいなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"藤原委員","kind":"意見","question":"今回第１７号議案で、このように、条例の一部を改正する条例という形で出ているのですが、区が定める条例は数多くありますが、課長はこの条例を設定する大事さ、条例とはをどのように考えていますかとの意見を述べました。","respondent":"河合生活安全担当課長","answer":"やはり、法と都条例、区条例と下がってきますけれども、その場所の実態に即した条例というものになりますので、区行政として、区としてはやはり重要な条例というところで、区の実態に即したものというところで、やはりそういう存在であると認識しております。","id":"exchange-028"},{"speaker":"藤原委員","kind":"質問・要望","question":"条例があるにもかかわらず、一体行政は、そして私が質問して要望もしているのに、それが実現されていません。なぜそういうふうに伺うかというと、本会議で決まってといろいろなっていくのですけれど、条例の設定というのは物すごく大事だと思っています。","respondent":"河合生活安全担当課長","answer":"ボックスを１個設置してくれているのだけれども、設置者のほうにどういった状況で今、そういった申入れというのはこれまでも続けているところです。なので、そういう環境に、実態に応じて、そういったところは申入れ等の指導というのをしっかりやっていきたいと考えております。","id":"exchange-029"},{"speaker":"藤原委員","kind":"質問","question":"これからやるわけですからまだ通っていないですよ、でも、改正しただけでとなってしまったらいけないと私は思っているのです。この条例を担保に行政をしていくわけですから。","respondent":"河合生活安全担当課長","answer":"事業者の責務として設置しなさいというところになっておりますので、指導ですか、そういったところでないところは対応していこうかと思います。設置しなさいよというのは環境を害するというところが正式に条文になっておりますので…","id":"exchange-030"},{"speaker":"藤原委員","kind":"質問","question":"これについても予算特別委員会で伺おうとは思っているのですが、条例がかかっているわけですから、これは大事なことだと思うのです。だから条例をどう守っていくかというのがやはり行政職員としては大事だと考えていますので、そこは。","respondent":"河合生活安全担当課長","answer":"委員からご指摘がありました、そういった、実際、条例で定められているのだからしっかり履行されるようにというところで、そういった視点でもって、こちらも条例に、定めにのっとってそういった対応はしていきたいと考えております。","id":"exchange-031"},{"speaker":"吉田副委員長","kind":"質問","question":"私から２点伺いたいと思います。この条例の改正によって規制の対象になるのかどうかというのを伺いたいというのが１点と、罰則なしの禁止規定は、その２点について伺います。","respondent":"河合生活安全担当課長","answer":"苦情があったら、正式に駄目ですという指導になりますので、そういった効果は見込めると考えております。そこから外れて、そういったところではやはり、禁止になるというところで効果は見込めると考えております。","id":"exchange-032"},{"speaker":"石田（し）委員","kind":"確認","question":"すみません、１点だけ最後、確認したいのですが、喫煙所は増やしていく方向ということでよろしいのですか。このいわゆる条例に対してどうしようかなという判断をするので、喫煙所は基本的に増やしていくという思いでやっているのかどうかだけ説明を求めました。","respondent":"河合生活安全担当課長","answer":"やはり今現在、推進地区にしかありませんので、全体の駅周辺とかそういったところというのは増やしていく方向で考えております。","id":"exchange-033"}]},{"id":"topic-03","title":"第１８号議案、品川区中小企業事業資金融資あつ旋条例の一部を改正する条例","agenda":"第１８号議案、品川区中小企業事業資金融資あつ旋条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"例えばどのようなものが考えられるのかというのを幾つか教えていただきたいというのが１つと、１件当たりの金額というのは大体どれぐらいを想定しての１億６,０００万円なのかというのをお伺いするのと、そこら辺について確認させてください。","respondent":"小林地域産業振興課長","answer":"さらにはロボットを導入して人手不足に対応するような取組、このチャレンジ支援資金を使って、取組をさらに進めることができると考えております。補助金につきましては、基本的に区の単費でこういった取組を実施しています。","id":"exchange-034"},{"speaker":"安藤委員","kind":"質問","question":"では、単価としては、その１.６％等を区が負担するというような予算の想定だということで理解いたしました。あるいは品川区に入ってくる税収を増やしたいとかいろいろあると思うのですけれど、それについてもう少し目標について教えてもらいたいと思います。","respondent":"小林地域産業振興課長","answer":"今おっしゃられたとおり、こういった取組を通じて、中小企業にいかに体力をつけていただくかというところが大事だと考えています。中小企業に体力をつけていただく、実際に資金調達をやりやすくする中で、そういった新しい取組を一つでも後押しするというところが目的です。","id":"exchange-035"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"チャレンジ支援資金を創設することによって、類似の資金、いわゆる環境対策資金と事業活性化資金をやめるということですね。これまで、この２つの資金というのはどのような方たちが利用されていたのか、分かったら大体でいいのでその件数を教えてほしいと求めました。","respondent":"小林地域産業振興課長","answer":"大企業はできるけれども、中小企業にとってはなかなかこういう新しい取組はリスクがあってやりにくいというようなお声もいただいたところです。最終的にはＳＤＧｓや地域にプラスになるような取組を少しでも後押しするということで…","id":"exchange-036"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"というときに、従業員を確保したり増やしたりといった部分に関して支援をしていただきたいと思うのですが、どこかに当たるものはあるのですか。説明を求めました。","respondent":"小林地域産業振興課長","answer":"その融資では設備資金のほか、運転資金も可能となっておりまして、賃上げや、その資金繰りも含めて対応するような取組があります。チャレンジ支援資金の中で、金融機関に対して区からあっ旋状を出して、対応していきたいと考えております。","id":"exchange-037"},{"speaker":"せお委員","kind":"質問","question":"これは令和４年度事業の見直しをしたのが令和６年２月に出ていて、これはどう見直して、これと今回との関係というのはどうなってくるのかというのを教えてもらっていいか尋ねました。","respondent":"小林地域産業振興課長","answer":"チャレンジ支援資金を今回追加しつつ、いわゆる資金繰りの部分や、設備資金の部分もしっかり対応してまいります。こうした中小企業の借入れ実績も踏まえた今回の見直し対応です。","id":"exchange-038"},{"speaker":"せお委員","kind":"質問・要望","question":"引き続きやっていただきたいなと思うところですけれど、あとは職員の業務的にもやりやすくなるのかなと思っていますので、引き続き。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-039"},{"speaker":"藤原委員","kind":"質問","question":"これ７年以内だったら、いわゆるゼロゼロ融資と思っていてよろしいのか尋ねました。","respondent":"小林地域産業振興課長","answer":"特にコロナの時期に、金利の部分、あるいは無担保・無保証ということも含めてゼロゼロと呼ばれておりました。信用保証料の部分も区が負担する、事業者にとっては両方の負担がゼロという形になるような、新たに借りやすいメニューをつくったです。","id":"exchange-040"},{"speaker":"藤原委員","kind":"質問","question":"少し細かい質問ですが、先ほど課長の答弁で、運送会社が環境を考えてトラックを替えるとか、あとロボットとかの話もあったではないですか。ロボットとかを介護事業所で入れるとかというようなことに関しても、これが通れば、使えると思っていてよろしいのか尋ねました。","respondent":"小林地域産業振興課長","answer":"今回の融資あっ旋については、全業種、法人、個人事業主の方問わず、ということで設定しておりますので、この目的に合致する取組についてしっかり対応してまいります。","id":"exchange-041"},{"speaker":"藤原委員","kind":"確認","question":"何か、チャレンジというと、創業支援、創業するのに限られているような、イメージですよ。よく質疑を聞いていて分かったのですが、確認をしたのですが、そういうことでいいのか尋ねました。","respondent":"小林地域産業振興課長","answer":"今回のチャレンジ支援資金につきましては、伴走的支援といいますか、伴走的なアドバイスも行った上で対応します。このため、金融機関から借り入れていただく、その後の金利負担支援を区が引き続き行うという流れを考えております。","id":"exchange-042"},{"speaker":"藤原委員","kind":"意見","question":"これからどうなるかというのが決まっていくわけですけれども、創業支援の担当課長から答弁いただかないといけない気持ちになってしまうのです。この第１８号議案が可決された時点でいろいろ、その辺はどのように活用していくかも含めてお考えになっているか…","respondent":"栗原創業・スタートアップ支援担当課長","answer":"こちらのチャレンジ支援資金は新規事業展開を図るものも対象経費となっております。そういった方たちが資金調達や、チャレンジをしやすい環境を整えていくため、担当課長としても周知に努めてまいりたいと考えています。","id":"exchange-043"},{"speaker":"吉田副委員長","kind":"意見","question":"よく承知していますので、その辺がここに盛り込まれたということは評価して、賛成といたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-044"}]},{"id":"topic-04","title":"令和７年請願第５号、「選択的夫婦別姓制度の早期実現を国に求める意見書」提出を求める請願","agenda":"令和７年請願第５号、「選択的夫婦別姓制度の早期実現を国に求める意見書」提出を求める請願","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"日本経団連も昨年６月、早期実現を求める提言まで発表したということで、クレジットカードを作れなかったりする事例があったと。ですから、私はこの時点で意見を言いましたので、皆さんからもぜひお伺いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-045"},{"speaker":"おぎの委員","kind":"提案","question":"今回、その前に既に「選択的夫婦別姓について議論を尽くすことを国会及び政府に求める意見書」のほうに私は一応賛成して提出者となりました。しっかりと国に議論していただきたいという意見を持って、今回の、早期に求める提案に関しては反対ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-046"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"しかるべき判断できる年齢になったら、それについても、私とかそれから請願者に求めることではないと思うのです。早期に実現することを求める意見書の提出は必要ではないかと思って、請願の紹介議員としてこの請願の提出に至ったというのが、会派の中での議論です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-047"},{"speaker":"安藤委員","kind":"確認","question":"すみません、いろいろご意見を聞かせていただいて、すごく認識が深まるといいますかあれなのですけれど、最後に、副委員長のところで、会派の中で話し合って会派として請願の紹介議員になるということを了解されたという認識でいいのか、そこを確認したいのです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-048"},{"speaker":"吉田副委員長","kind":"意見","question":"強く主張いたしました。生活者ネットワークとしてずっと主張してきたことですので、私が紹介議員になるということをある意味宣言をいたしまして、提出になりましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-049"},{"speaker":"安藤委員","kind":"意見","question":"宣言ということなので、それは了解されたという判断はできないということになってしまいますけれど、それで会派としては、それについては、細かくて申し訳ない、ただ大事な点であると私は思うので、もう１回聞かせくださいとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-050"},{"speaker":"吉田副委員長","kind":"質問","question":"宣言はしましたけれど、宣言が受け入れられたということで今日の提出に至っているわけですから。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-051"},{"speaker":"安藤委員","kind":"質問","question":"最後に、もう１回質問したいのですが、ジェンダー平等条例との関係です。全会一致で可決されているという事実があるので、と思って少しご質問というか、もしご意見がある方は聞かせていただけるとありがたいなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-052"},{"speaker":"石田（し）委員","kind":"意見","question":"だから結局その議論が進まないのだけれど、もう１回全部出しましょうよと。だから国政で議論すべきだということで、国でまず意見をしっかりと議論を進めてほしいということで、審議をしているということをお伝えしておきますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-053"},{"speaker":"おぎの委員","kind":"質問・要望","question":"賛成ですか、反対ですかと、マスコミの調査はほとんどが２択なのです。国もしっかり議論をしてほしいし、結婚する方も２人でしっかり話し合っていただきたいし、そうやって今後しっかり話し合うべきものだと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-054"},{"speaker":"吉田副委員長","kind":"意見","question":"例えば、今でもいろいろな、世帯に助成金が出たりとか、なので……。〔「個人ナンバーやったら反対するのだから……」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-055"},{"speaker":"吉田副委員長","kind":"確認","question":"戸籍自体がどうしても世帯で管理されている以上、一々いろいろな今、助成金が世帯に出るものに対して確認しなければいけないのです。ですから、それを国のほうに上げてほしいということを言うのは区議会議員の役割として当然かなと思いましたので、紹介議員にもなりましたし。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-056"},{"speaker":"せお委員","kind":"意見","question":"本日結論を出すで、不採択でお願いします。これは国で議論すべきものであって、１人を除く方が賛成してくださっているので、不採択でお願いしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-057"},{"speaker":"ゆきた委員","kind":"意見","question":"やはり区議会として、全体で賛成多数で一致した意見書だからこそ、力強い意味のあるものになると思っています。そういった意味でも、この請願の意見書については、その内容には沿ったものではないので、不採択でお願いしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-058"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"主には皆様のご意見と同じ、子どもの姓の選択をいつ行うのか、子どもの姓をどうするのかということです。それについては慎重な意見が出されましたが、強く主張いたしまして、会派として採択とさせてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-059"},{"speaker":"安藤委員","kind":"質問","question":"若干不正確だったのでもう１回言いますけれど、子どもが１８歳になった時点で本人の申出により変更できるようにするというのが共産党の政策です。意見書とはそもそも国に意見するものですから、こういう方向で議論してほしいという、採択を主張します。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-060"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"どういうことが議論されているのかというのも、そういった議論をぜひ、品川区議会においてはしていただきたいなと。この制度に関しては国がしっかりと責任を持って議論をするべきだし、区の中でいろいろ議論をしていったらいいのかなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-061"},{"speaker":"おぎの委員","kind":"質問・要望","question":"国会と政府に議論を尽くすことを求める意見書のほうに、今回のこの早期実現を求める意見書は、不採択とします。国だけでなく、きちんと区内というか、普段から私たちもこういったことを話し合って情報をどんどん共有していくべきものだとは思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-062"},{"speaker":"石田（し）委員","kind":"質問","question":"では、意見いいですか。は理事者の皆さん、僕も若干おなかがすいていますけれど、考慮していただきながら、判断をしていただければ。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-063"},{"speaker":"安藤委員","kind":"質問","question":"区内の中小零細企業、フリーランス、個人事業主などの実態をつかめると思っていらっしゃるのか伺いたいというのが１つです。その時々の旬の課題について伺うわけですけれども、過去２回、誰がどのような基準でどのような場所で決めているのか伺いたいと思います。","respondent":"小林地域産業振興課長","answer":"昨年１１月に国が実施していた調査では、アンケートの回答だけではなく、国によるヒアリングもお考えになっていたようです。その範囲の中で、自治体としてでき得ることをまず、実施していく、それで今後の区の施策で生かせるものがあれば生かしていくというものです。","id":"exchange-064"},{"speaker":"安藤委員","kind":"質問・要望","question":"どうでしょうか、お考えを聞かせてください。過去２回行いましたが、なぜそのときはそのような調査を入れることになったのか、その経緯と理由というのを改めて伺わせていただきたいなと思います。","respondent":"小林地域産業振興課長","answer":"今後国が実施する調査の中で、どのように対応されることとなるのか、きちんと見たいと考えています。その上で、制度導入の直前の時点ではもう９８％、９９％が対応済みといいますか、そのような対応をしていたと承知しております。","id":"exchange-065"},{"speaker":"安藤委員","kind":"質問","question":"伺いたいのは、区としては、このインボイスという制度が区内の事業者にどういう影響を与えているのかというのをどう考えているのですか。それで、影響があるとしたら、どういうところに影響があるのではないかと考えているのか、そこら辺の区の考えについてお伺いしたいと思います。","respondent":"小林地域産業振興課長","answer":"さらには、これはインボイスに対応するかしないかに関係なく、事業者の資金ニーズにいろいろ対応して使える制度ですので。融資、あるいは相談対応を進めているところですので、ご相談があればお勧めしていきたいと考えています。","id":"exchange-066"},{"speaker":"安藤委員","kind":"質問","question":"少し分かりづらい質問ですけれど、影響の重い、軽いも含めて区としてはどう考えているのでしょうか。どういう面で、フリーランスに影響を与えているとお考えなのかという、区の考えを伺いたいです。","respondent":"小林地域産業振興課長","answer":"ただいまご質問いただいた点が、まさに国と自治体の対応の本質的な違いに当たる部分かと考えております。専門家派遣、ウェブ相談なども含めて、これはコロナ対応のときには１万件に近いような経営相談を受けております。","id":"exchange-067"},{"speaker":"ゆきた委員","kind":"質問","question":"陳情第４号のほうに、ここについての区の認識をお聞きしたいと思います。こちらお願いします。","respondent":"小林地域産業振興課長","answer":"これに関しては午前中もご説明申し上げましたけれども、事業者の方が金融機関から資金を調達する際に、あっ旋状というものを区から出します。これは全体の中で１割前後と認識しています。","id":"exchange-068"},{"speaker":"ゆきた委員","kind":"確認","question":"今のお話からも、逆に９割は融資を行っている点と、さらには経営計画を見直すようなアドバイスを行っている点も確認させていただきました。さらに区の経営相談の中でインボイスに係る相談がどれだけあったのか、この２点についてお聞きできればと思います。","respondent":"小林地域産業振興課長","answer":"原材料価格の高騰、あるいは人手不足、それに伴う売上げの減少などを挙げられている方が圧倒的に多くあります。インボイスに係る事務負担が今後大きくなるというようなことは１件、物価高騰ですとか、人手不足を挙げる意見が多いと認識しております。","id":"exchange-069"},{"speaker":"ゆきた委員","kind":"確認","question":"インボイスについては１件ということで、現状確認できました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-070"},{"speaker":"おぎの委員","kind":"質問","question":"どういったアウトリーチで、２０２４年にこの制度が始まってから新たに課税事業者になった事業者というのは、聞き取りに行ったりとかフォローアップをこちらからするということをされたりなどはどうか尋ねました。","respondent":"小林地域産業振興課長","answer":"自宅、あるいは事業所から区に相談して、あっ旋状の受取り自体も電子で、わざわざこちらに来なくても取れるような形で資金繰り対応もしてまいります。様々な相談対応もやっており、利便性やスピード感を重視しながら、区内中小企業の支援をしっかり進めていきたいと考えています。","id":"exchange-071"},{"speaker":"おぎの委員","kind":"質問","question":"すごい熱意を持ってされているなというのは伝わってくるのですけれども、それぐらい熱意があったら実態調査できるのではないのかなと思うのですが、やはり物理的に難しいのか尋ねました。","respondent":"小林地域産業振興課長","answer":"冒頭の説明において申し上げましたけれども、国は前回１１月にインボイスの影響調査をする際に免税事業者を対象として調査を考えていたようです。このため、まずは国の調査の手法なり、その内容、結果というのを…","id":"exchange-072"},{"speaker":"石田（し）委員","kind":"質問","question":"もう一つが、この陳情第４号にも書かれていますけれど、いわゆる昨年は、過去１０年で最多の倒産件数だったりしているわけです。こういったことがどういう原因として区は今、捉えているのかというのをまず、説明を求めました。","respondent":"小林地域産業振興課長、高橋（伸）委員長","answer":"何か大きな制度変更に関わるものがですけれど、直近今、何か国の法律や制度が変わることを対象とした調査はないと認識しています。２点目については… 課長、インボイス制度の変更に関わらず、ほかの制度変更によって、アンケートをこれまで実施したのかについては。 私が本日持っている直近３四半期の調査の範囲で申し上げますと、例えば人材不足なり、経済状況の変化に関する調査が中心になっているところです。","id":"exchange-073"},{"speaker":"石田（し）委員","kind":"質問","question":"いわゆる経済がどういった動きになっていくかというのは見て、僕がさっき話したとおり２,４８０億円という大きなお金が動いている制度ですから。どういうふうな影響が、単体ではなくてもいいからやるべきだと僕は思うのだけれど、その辺の考え方を説明を求めました。","respondent":"小林地域産業振興課長","answer":"年間３,０００件、コロナのときは１万件の経営相談を実施していたとご説明申し上げましたけれども、いろいろお困り事をお話しいただいております。税制度やインボイスに関連して、我々としては、普段からいただいている多くの声についてはしっかり対応していきたいと思っていま…","id":"exchange-074"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"この背景に何があるのかというのをぜひ調査をかけていただきたいと思うし、中小企業センターに来てくださいね、ですよね。それはぜひ把握をしていただきたいし、皆さんが持っているデータとはどういったものがあるのか、最後に説明を求めました。","respondent":"小林地域産業振興課長","answer":"今年度で言えばチャレンジ支援資金を通じて、そういう中小企業の事業者負担を減らしていくにはどうしたらいいかをずっと考えてまいりました。１００％対応できているとは思っておりませんので、そういった声に少しでも対応できるようにしっかりやっていきたいと考えています。","id":"exchange-075"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"そこをもう１回原点に戻っていただいて、品川の各企業がこのことによって影響があるよというのを突きつけたら、それは変わるのではないですか。その品川をぜひ実現してほしいと求めましたので、最後要望になりますけれど、。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-076"},{"speaker":"藤原委員","kind":"質問・要望","question":"手法の一つ、なぜならまだ、結果どうなるか分からないではないですか。課長、少しかみ合わないと思うかもしれませんが、その辺についてはいかがか尋ねました。","respondent":"小林地域産業振興課長","answer":"我々も、職員総動員でいろいろ声を聞いているところではあります。国の調査の中で、そういう中でどのような実態把握があり得るのかについては、引き続き考えていきたいと考えています。","id":"exchange-077"},{"speaker":"藤原委員","kind":"意見","question":"だから、そういう意味において、１軒１軒行くわけではないです。だから私はやるべきだと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-078"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"どういう項目を盛り込むべきだろうかというような確認は来ないのでしょうかという、やはり、肌感覚で把握しているのは自治体だと思うのです。先ほどの最初のご説明だと、ほとんどその確認もなく、その辺の国と自治体との関係はどうなっているのか教えていただけますか。","respondent":"小林地域産業振興課長","answer":"国であれば調査のやりっ放しということはなくて、その調査結果などを踏まえたヒアリング、アフターフォローもやっていると認識しています。これはインボイスへの対応だけではなくて、経済状況が大変厳しい中でありますので、そのことは全般的に考えていきたいと考えています。","id":"exchange-079"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"それはぜひ求めていっていただきたいなと思うのですが、そういうのを自治体のほうから国に求めるというのは難しいのでしょうか。でも、自分たちのそういう情報とかを生かしてほしいというのは言っていっていただきたいのですけれど、その辺についてもう１回伺います。","respondent":"小林地域産業振興課長","answer":"そういう中で、何か国の支援の中で使える制度が区内事業者向けに何かありますか、というような意見交換はしっかりやっていきたいと思います。そういう声を受けて、国がどのように判断されていくのかということはありますが…","id":"exchange-080"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"でも、ぜひその辺については、その視点を持って中小零細の事業者とか１人で事業をやっているような方たちに向き合っていただきたいなと思います。その点については要望でとどめておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-081"},{"speaker":"せお委員","kind":"質問・要望","question":"それはうそではないでしょうから、それと同じになるのではないですか、と思うのです。結局結果が求められているものにならないというか、正確性がないというところになるのではないかなと、そもそもそう思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-082"},{"speaker":"ゆきた委員","kind":"意見","question":"３,６００件前後の経営相談を１件１件個人事業主からも相談を受けているということで、これはまず、まさにこれが区の実態状況把握だと思います。国の調査結果を踏まえて区としても把握していくことが必要だと思われますので、今回の影響調査に関する陳情については…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-083"},{"speaker":"吉田副委員長","kind":"意見","question":"もし調査するとしても、区としての活用も難しいかなあということです。私自身としては、もっとふわっとした調査でもいいから、会派全体としての結論は不採択となりましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-084"},{"speaker":"安藤委員","kind":"意見","question":"それは、地域産業振興課として本当にやらなくてはいけない仕事なのではないかと考えていますので、採択を主張したいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-085"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"区長の施政方針でも、「区民の不安や不満といった『不』を取り除き、未来に希望の持てる社会をつくるべく」、というふうに言っています。ぜひ、フリーランスや零細企業、中小企業の皆さんの不況の「不」を取り除くためにも、実態調査に踏み切ってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-086"},{"speaker":"おぎの委員","kind":"意見","question":"これで落札で１,１００万円なのかと思って、これで実態がきちんと把握できると思っていたのかなというのが、少し心配になりました。今この瞬間も倒産している企業があるなと思うと、インボイス含め全般的に踏み込んだ調査を区がやったほうがいいと思いますので…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-087"},{"speaker":"ゆきた委員","kind":"確認","question":"本日結論を出すで、不採択でお願いします。そこについては、融資以外の取組についても前向きに取り組んでいる区の姿勢を確認できていますので、この陳情については不採択でお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-088"},{"speaker":"安藤委員","kind":"意見","question":"本日結論を出すで、採択なのですが、必要なことだと思いますし、すぐにできてしまうことだと思いますので、すぐやるべきだと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-089"},{"speaker":"おぎの委員","kind":"質問・要望","question":"理由は先ほどと同じで、しっかりと把握して声を拾っていただきたいなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-090"}]},{"id":"topic-05","title":"令和７年陳情第１３号、就職困難な新卒者への支援を求める陳情","agenda":"令和７年陳情第１３号、就職困難な新卒者への支援を求める陳情","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"陳情に、大手映画編集企業や現像会社があった関係でとあるのでお伺いしたのですけれども、分かれば教えていただきたいなと思います。様々事業の紹介があったのですけれども、そういう直接、マッチングといいますか集団就活説明会みたいなことを区としてやっているのかどうか伺います。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"それから、映像関係ですとかＩＴの会社が一定数、集積しているということは認識しています。説明会を直接区がやっているのかというところにつきましては、区で直接やっているということはございません。","id":"exchange-091"},{"speaker":"安藤委員","kind":"質問","question":"今、やはり、区として区内の若者を区内の業者とマッチングさせるというのは非常に重要な事業なのではないかと思います。このような状況というのを、区は、一定声としてつかんでいたり把握しているようなところというのはあるのか尋ねました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"今のこういった物価高騰だとかといった状況で新卒が採れないというお声はもちろん、認識しています。やはりどうしても中途に流れてしまうというお声も一方で聞こえてくることは認識していますので、中小企業がどうやって人材確保、定着。","id":"exchange-092"},{"speaker":"ゆきた委員","kind":"質問","question":"ここについての実績と、あと、就業相談のオンラインについても状況が分かればお聞きできればと思います。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"令和６年度については、１月末時点で２３９人、３４４件のご相談がございました。すみません、３点目の質問は何でしたか。","id":"exchange-093"},{"speaker":"ゆきた委員","kind":"質問","question":"だとすると、職業相談は大体１日２０件から２５件以上受けているという成果が出ていると思います。５２３件だとすると、１日２件ぐらいの一定の成果が出ているのかなと思いますけれども、この辺についてお聞きいたします。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"実施しておりまして、今年度につきましては、約６０名のご相談があったといったところです。はＳＮＳを用いての周知をしていますけれども、ＳＮＳ、Ｘだとかといったところの発信をより強化してまいりたいとは考えています。","id":"exchange-094"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"やってほしいとお願いして、そこを改めて教えていただきたいのと、それを改めて教えていただきたいのと。一定分かるのですけれど、その大きい枠で考えたときに、今どういう状況だと区は考えているのか教えていただきたいのが２点です。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"新年度予算で女性デジタル人材の育成事業というのを新規でやることを予定しているのですが、いわゆる、人材を採用したいけれど採れない中小企業。２点目の、なかなか、ケース・バイ・ケースなのかなといったところです。","id":"exchange-095"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"ここはぜひやっていただきたいし、この陳情者の方がまさにそこを危惧されているので、そこの気持ちというのはとても分かるのです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-096"},{"speaker":"せお委員","kind":"質問","question":"先ほど理事者からご説明がありましたように、相談の問題とか融資あっ旋、若者の声を聞くというところをやっていただいていると。職業相談も６,０００件を超えているというところで、個別の状況を見ていただいて、それに引き続き対応していただけたらなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-097"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"取組として進められていることが確認できましたので、この陳情については不採択でお願いします。今後さらなる周知については要望させてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-098"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"その辺の認識が、自分が転職を求めているわけではないので実態がよく分からないのですが、区としては難しいのではないか。その２つが合わさって、ご本人の希望も聞きながらやっていただきたいということを前提に、不採択といたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-099"},{"speaker":"安藤委員","kind":"提案","question":"本日結論を出すで、これは採択すべきだと思うのですけれども、かなり具体的でリアルな実態、状況を告発されています。かなりユニークな提案ではないかと思うのですが、行政としても議会としてもあるのかなと思いますので、採択を主張しますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-100"},{"speaker":"藤原委員","kind":"質問・要望","question":"就職を求める人はきちんと研修を受けて、中小企業の方たちもお見えになっていろいろ教えてくれて、間違いなく品川区に。その辺についてはまた、要望していきますので、どうか検討していってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-101"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"第２の就職氷河期世代なんかつくりたくはないから、ぜひそういったところは頭の片隅にしっかり残しながら、施策を実施していただきたいなと思います。それは要望で終わりますけれど、不採択です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-102"},{"speaker":"おぎの委員","kind":"質問・要望","question":"中小企業が今、もうそうできないというのが、根本だと思うのです。今されている３つの支援のほうをより幅を広げてやっていただきたいなと思いますので、これは不採択ですが、。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-103"}]},{"id":"topic-06","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"２月１９日の若林ひろき議員の代表質問と、２月２０日の澤田えみこ議員の一般質問で、品川でデフリンピックの会場が新たに設置されることになったことについての質疑がありましたが、その経緯とか内容、それについて伺いたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-104"},{"speaker":"高橋（伸）委員長","kind":"質問","question":"澤田議員の一般質問にあった、東京２０２５デフリンピックに関連する報告が予定されているので、その中で質問いただくということにしたいと考えていますがよろしいか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-105"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/414982?Template=document&Id=6959#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":72713,"voices":270}},{"id":"r07-20250225-7","meetingId":"r07-cm02","date":"2025年2月25日","dateIso":"2025-02-25","committee":"厚生委員会","time":"午前１０時００分～午後 ４時００分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を100件整理しています。","topics":[{"id":"topic-01","title":"知的障害者グループホーム条例の一部を改正する条例、(3)第２４号議案、品川区立知的障害者福祉施設条例の一部を改正する条例、(4)第２５号議案…","agenda":"知的障害者グループホーム条例の一部を改正する条例、(3)第２４号議案、品川区立知的障害者福祉施設条例の一部を改正する条例、(4)第２５号議案…","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"多分、３万円というのが維持されるのかというところがどうなるのかというのを伺いたいと思います。規則を確認していないのですが、その数も分かったら教えていただきたいのと、その点についても伺います。","respondent":"松山障害者支援課長","answer":"家賃の額も、先ほどご説明させていただきましたように、３万円ということは維持し、特段、ご利用者に何ら不利になるようなことはございません。グループホーム第７条、別途、こちらには特に定めているものではありません。","id":"exchange-001"},{"speaker":"鈴木委員","kind":"確認","question":"そうしますと、条例のほうは変わるけれども、規則で定めているというところは、規則は今までのそのまま踏襲されるということでいいのか、その確認だけお願いします。","respondent":"松山障害者支援課長","answer":"今、収入の部分につきましては、やはり家賃について別途定めなければならないので、区の歳入ではないということで、条例ではなく、今のところ、規則というより要領に定めて、来年度、新たに指定管理者と協議する協定書のところにも定める予定です。","id":"exchange-002"},{"speaker":"鈴木委員","kind":"確認","question":"そうしますと、家賃の減免というのは実際に使われていて、それがその後も同じように継続を担保されるということで確認させていただいていいということですね。","respondent":"松山障害者支援課長","answer":"家賃の減額については、毎年行っているものでして、前年度の収入、所得によりまして、減免しています。ほとんどの方が減免対象になっていて、家賃３万円を支払っている方はいらっしゃいません。","id":"exchange-003"},{"speaker":"ひがし委員","kind":"質問・要望","question":"公開などもされるのかというところも確認をさせてほしいと求めました。第５条に、その承認を受けなければならないと書いてありますが、今まではその承認を受けていたということで認識は合っているのかも説明を求めました。","respondent":"松山障害者支援課長","answer":"実際の運用につきましては、障害者総合支援法に基づく障害福祉サービスの提供について、区は指定管理者へ委任を通じて行っております。ただし、それに対して、実際には何ら区民に対して支障はございませんでしたので、運用してきたものです。","id":"exchange-004"},{"speaker":"ひがし委員","kind":"質問","question":"条例にはこの文言が残っていたけれども、少し制度が変わってきて、実は承認はしていなかったということで合っているということですね。だとしたら、いつからその承認を行わなくなったのかというところも、分かる範囲で教えてほしいと求めました。","respondent":"松山障害者支援課長","answer":"事実としてきちんと何年ですというのはお伝えはできませんけれども、また、区としても改正する必要があると強く認識しておりました。できる限りやはり誤解のないようにということで規定整備に努めてまいりましたが、このたび。","id":"exchange-005"},{"speaker":"ひがし委員","kind":"質問・要望","question":"今お話しした感じだと、指定管理者との契約でということで、これは指定管理者に移るのかというところを確認させていただきたいです。第１０条のところの指定管理者の行う業務というところに、誰がその入居選考を行うのかというところについても確認をさせてください。","respondent":"松山障害者支援課長","answer":"１点目、上位法の障害者総合支援法で、現在もサービス提供を行っているというものです。区としては、条例に必要な事項につきましては規定しているものと認識しております。","id":"exchange-006"},{"speaker":"ひがし委員","kind":"確認","question":"今、対等な関係で指定管理者と契約を結ぶということを確認させていただきました。地方自治法にも反していないということでよろしいのかというのを最後に確認をさせてください。","respondent":"松山障害者支援課長","answer":"今後とも区としても、ご希望に添えるよう、またグループホームの整備・運営に努めてまいります。ぐるっぽ条例につきましては既に対応済みでございまして、区の中でも対応している条例と、今回ご提案する条例はまだ対応ができていなかった条例です。","id":"exchange-007"},{"speaker":"若林委員","kind":"確認","question":"一応、参考までに、手数料はどういう扱いをしていたのかという、この２つを確認させていただいて、一遍に聞いてしまいます。いわゆる指定管理者が直接収受するということになっているかどうかの確認を、以上３点、お聞きします。","respondent":"松山障害者支援課長","answer":"指定管理者への振込ですが、半年に１回〔同日後刻に「四半期ごとに１回」と答弁訂正あり〕という形を取っております。３点目ですけれども、障害者支援課では、全て利用料金として指定管理者の収入になるというものです。","id":"exchange-008"},{"speaker":"若林委員","kind":"確認","question":"これはここで言うと、所管で言うと、高齢者施設であったり、障害のある方の施設だったり、指定管理はその２つぐらいですかね。保健は関係ない……、厚生委員会の所管の中でそういう条例を抱えている、課長のもしまだあるのですということがあれば、確認だけはしておきたいと。","respondent":"松山障害者支援課長、菅野高齢者福祉課長、樫村高齢者地域支援課長、若生健康課長","answer":"障害者分野では、委員おっしゃられるようなものはございません。今回改正のご議決をいただければ、全て改正後は指定管理者の収入としてなるものです。 食費や居住費などの、ご本人が負担していただくものについても、全て指定管理施設のほうで収入しております。 使用料ですね。団体、お部屋の利用料とかです。 健康推進部では、健康センターが指定管理になっていますけれども、健康センターについては、利用料収入は全て指定管理者の収入になっております。","id":"exchange-009"},{"speaker":"若林委員","kind":"確認","question":"収入になっているのは分かっているのだけれども、きちんと指定管理が直接収受しているのかということの確認です。","respondent":"若生健康課長","answer":"指定管理者が直接収受しております。","id":"exchange-010"},{"speaker":"石田（秀）副委員長","kind":"確認","question":"１つだけお聞きしたいのですが、指定管理者が様々、事務的なことも含めて簡素化されるのだと。それでその選択をしていけるわけだけれども、それでその施設を利用したときに、そごがないように、今以上になれますというところだけの確認をしたい。","respondent":"松山障害者支援課長","answer":"やはり総合支援法に沿ったものでの条例の立てつけを変えるというところで、利用しやすくなるように運営努力をやはり図っていただくというものです。指定議案のところでご説明するのですが、それも含めまして…","id":"exchange-011"},{"speaker":"石田（秀）副委員長","kind":"質問","question":"我々も利用者の方々から、いろいろ直接的にお話を伺うときがあるときに、いい話ばかりではないわけです。そこはせっかくこういう議案があるので、条例改正もするので、ぜひよくなるようにお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"筒井委員","kind":"確認","question":"確認として、もう少し地方自治体も条例を整理してくれとか、そういった要請というのはなかったのでしょうか。それとも、完全に今回品川区の独自の判断なのか尋ねました。","respondent":"松山障害者支援課長","answer":"条例の一部を改正するに至った経緯ですが、特に国のほうから各自治体の条例を変えてくれということの要請はございませんで、それぞれ各自治体の判断で、今回は品川区として条例の規定を整備し、指定管理者の運営努力の推進を図るために改正していこうというものです。","id":"exchange-013"}]},{"id":"topic-02","title":"第２６号議案、品川区介護保険制度に関する条例の一部を改正する条例、(7)第２８号議案、品川区後期高齢者医療に関する条例の一部を改正する条例の２議案","agenda":"第２６号議案、品川区介護保険制度に関する条例の一部を改正する条例、(7)第２８号議案、品川区後期高齢者医療に関する条例の一部を改正する条例の２議案","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"４、なぜ標準システムというのは１０回払いではなくて９回ということになったのか、そこら辺のところが分かったら教えてほしいと求めました。改正はないということなのですが、２か月ごとに年金が入るので、そこから天引きされるという仕組みが変わらないということでいいのか尋ねました。","respondent":"菅野高齢者福祉課長、池田国保医療年金課長","answer":"そういった方たちには、納付相談があった場合には、未納等、柔軟に対応していきたいとは思っているところです。まずは７月の通知のときに、令和８年度の４月には送らないということになりますので… ６月から翌年の３月までの１０回ということで、それから賦課計算という形になってまいりますので、どうしても７月からの９回払いという形になってしまいます。","id":"exchange-014"},{"speaker":"鈴木委員","kind":"質問","question":"もう一つ、介護保険のほうははっきりそのように運営状況の中で示されているので、普通徴収の人がどれくらいというのはすぐ分かるのですけれども、後期高齢のほうは、特別徴収と普通徴収の人数とか割合というのはどれぐらいなのか、教えていただけたらと思います。","respondent":"池田国保医療年金課長","answer":"普通徴収が約２万２,０００人、特別徴収も約２万２,０００人ということで、ほぼ同じ数字の割合の方で徴収をさせていただいているところです。特別徴収の方については、介護保険と同様に年６回のお支払いということで、これは変わりはございません。","id":"exchange-015"}]},{"id":"topic-03","title":"の順番を一部変更し、(8)第４１号議案および(9)第４２号議案、指定管理者の指定","agenda":"の順番を一部変更し、(8)第４１号議案および(9)第４２号議案、指定管理者の指定","exchanges":[{"speaker":"鈴木委員","kind":"確認","question":"ここにも継続的な積立金の取り崩しが確認され注意が必要だということで委員の意見もあるのですけれども、また、伺いたいと思います。そこら辺のところ、区としての捉え方がどうなのかという点も伺えたらと思います。","respondent":"東野福祉計画課長、菅野高齢者福祉課長","answer":"それから、八潮地域に根差した事業活動を行っている者として、新規参入の事業者については難しいところがあると考えております。ですが、今回、応募に際しましては、説明会に参加した事業者もいらっしゃいました。 モニタリング評価の部分についてのお話がありましたので、１点、補足説明をします。併設する特別養護老人ホーム八潮南、特養の会計のほうに一括して計上されているものでありますので、決してゼロ円ではないというところで補足します。","id":"exchange-016"},{"speaker":"鈴木委員","kind":"質問","question":"２６点になったというのは、２６点ということになったという、そんな感じで捉えればいいのでしょうか。支援すべきところは支援していただくというところで、必要なのかという思いがしていますけれども、その点も伺えたらと思います。","respondent":"東野福祉計画課長","answer":"それから、支援すべきところは支援をです。区としてできるものはどういうことかというものを考えていければと考えています。","id":"exchange-017"},{"speaker":"筒井委員","kind":"意見","question":"どのようにお考えなのかということと、説明会には３者いらしたということで、その３者というのはどのようなところだったのかお知らせくださいとの意見を述べました。","respondent":"東野福祉計画課長","answer":"それから、事前の説明会に来られた事業者につきましては、２者です。そういう事情はありますが、説明を聞いてご辞退をされたというのが経緯です。","id":"exchange-018"},{"speaker":"筒井委員","kind":"質問・要望","question":"３ページの収支計画のところで、人件費比率が平均に比べて高い点が見受けられたというのですけれども、具体的にどの程度、品福は人件費が高いのか。どの辺りの役職のところが高いのか、その点、分かれば説明を求めました。","respondent":"東野福祉計画課長","answer":"例えば、派遣の方を雇ったり、そういうことをしているということで伺っております。その辺が高くなっている一つの理由かとは思っております。","id":"exchange-019"},{"speaker":"やなぎさわ委員","kind":"確認","question":"財務評価について確認なのですけれども、１.５倍とか、そんなに上下幅が出るものではないのかとは思います。２６点だということで、こういった財務に関わる評価というのは、本審査でやったような基準で今後はやっていくという理解でよろしいか尋ねました。","respondent":"東野福祉計画課長","answer":"１０点ほど差が出ているというところで、１点の方が何人いて、１点分が２点分がというところでの差が開いてきたというものです。今後経済状況が変わってくる可能性もありますが、当面はこういった形での選定方式といいますか、点数の方式になってくると思っているところです。","id":"exchange-020"},{"speaker":"やなぎさわ委員","kind":"提案","question":"１つ気になるのが、今回１者だけだったのでよかったのですけれども、何者もあって、一次選考で何者か落としたりということもあると思うのです。足切りされてしまうということにもなりかねないと思うので、その辺、ある程度の統一化を図られるべきではないかということで提案しますとの意見を述べまし…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"石田（秀）副委員長","kind":"質問","question":"あそこは個室しつらえだから、金額の問題もあったりというのもあるから、相当、あの１列をよく、今、大変なわけではないですか。数をどうするかという、利益は上がらないと思うので、ぜひそこら辺は今後の一つの課題として考えてほしいと。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"鈴木委員","kind":"質問","question":"１５年間たって、その結果は報告書に１者からの応募だったということは書いたほうがいいのではないかと思うのですけれども、その点も伺います。この８割を超えるというのは総合点数のことで、４００点満点のところで８割を超えるということの捉え方でいいのか、伺いたいと思います。","respondent":"松山障害者支援課長","answer":"もちろん新しい事業者に参入いただいたほうが、選択肢としては選べるというのがありますけれども、なかなか説明会にもご参加はなかったです。４００点中、それぞれ８割を超えるということで、かなり高い得点率になったという結果です。","id":"exchange-023"},{"speaker":"鈴木委員","kind":"意見","question":"介護でも障害者でも、１者しか来ないという状況ですので、そういう中でこういう状況というのはやむを得ないかという思いがしています。そのような中で、すごく高い点数で８割を超えるというところが、評価すべきところだろうと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"１点だけ。職員の離職率が低いというところが挙げられているのですけれども、具体的にどれぐらいのパーセンテージなのかを教えていただきたいです。","respondent":"松山障害者支援課長","answer":"北品川つばさの家は、指定管理業者が社会福祉法人げんきなのですが、離職率のパーセントとしては、７.６９％ということで、かなり低いパーセンテージだと評価しております。","id":"exchange-025"},{"speaker":"やなぎさわ委員","kind":"確認","question":"重ねて確認ですが、離職率は、得点の中のどれぐらいのパーセンテージというか、何点とかで評価されているのか、確認でお願いします。","respondent":"松山障害者支援課長","answer":"３の公の施設の管理を安定して行う物的能力および人的能力を有しているものであることの中の(3)、福祉サービスを円滑かつ継続的に提供できる人的体制があるかというのが１０点満点でありますので、１０点の中に含まれているものです。","id":"exchange-026"},{"speaker":"鈴木委員","kind":"質問・要望","question":"保健センターの建て替えの影響もあるのではないかと思うのですが、その点の影響というのはどう考えられているのか伺いたいと思います。報告書の３ページのところに、これはどのように区としては見通しについても考えているのか、伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"光熱水費等の支援金をさせていただいたり、あと、コロナの中でもサービスを継続していただいたことへの支援金もさせていただいたこともありますので。こちらの法人も居住支援手当は支給をさせていただいているということもありますので、今後も…","id":"exchange-027"},{"speaker":"鈴木委員","kind":"確認","question":"１００点満点とすると４０点という状況になるのが、基金の継続的な取崩しが確認されるなど、区は把握しているのか。人件費比率が高いということで書かれていますが、そういうことでこれだけ低い点数になるのか、その理由についても伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"少し厳しい答えが出たというところもございましたので、予備委員会は１２点、選定委員会のほうも２０点という点にはさせていただきました。ただ、こちらの事業者に任せられるだけの体力があるという判断に至っております。","id":"exchange-028"},{"speaker":"筒井委員","kind":"質問","question":"４８号議案以外は公募をされたということなのですけれども、これも１事業者からの応募ということになりましたが、説明会とかにほかの業者がいらしたりはしなかったのか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"公募した施設につきましては、説明会には実はもう１事業者、それぞれの施設、いらっしゃいまして、説明等は一緒にお聞きいただいております。結果的には、そちらの事業者は応募しなかったため、１事業者の応募となった次第です。","id":"exchange-029"},{"speaker":"筒井委員","kind":"質問","question":"いずれにせよ、もう１者しか説明会に来られなかったということなのですけれども、やはり事業的にやりたいという事業者がそもそも少ないのですか。その辺り、どのように区として見ておられるのか、お聞きしたいと思います。","respondent":"菅野高齢者福祉課長","answer":"そのような期待値はあるのですが、現実的には、現行の応募者、運営事業者が応募するのみにとどまっているということになります。介護保険制度が２０００年に創設されてから、２６年目になるのですけれども、注視していかなければいけないところだとは捉えております。","id":"exchange-030"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"４６号および４９号議案のところの３ページの委員の意見のところなのですが、(2)のところで、どういったものになっているのでしょうか。その効果がもし分かれば教えていただきたいのですけれども。","respondent":"菅野高齢者福祉課長","answer":"東京都の認証は、ＴＯＫＹＯ働きやすい福祉の職場宣言というのを令和４年度にこちらの施設は取得したと、提案書には書いてあります。その後、何とか雇用につなげるなど、幅広い取組をしているとは聞いております。","id":"exchange-031"},{"speaker":"やなぎさわ委員","kind":"質問","question":"そういったところの現実的な人手不足というよりは、こういった都の取組にエントリーしているとか認証を受けているということのほうが、どちらかというと評価基準としては上になるという理解でよろしいか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"人手不足に関しては、この法人、この施設が何か悪いというより、介護業界全体の慢性的な人手不足というのがありますので、その中でそういったいろいろなことにチャレンジをされて、少しでも人材の確保に努めているというところは評価すべき点だと捉えております。","id":"exchange-032"},{"speaker":"やなぎさわ委員","kind":"質問","question":"そのような中、外国人人材を積極的に受け入れているというところなのですけれども、そこを受け入れてもなお人手不足になっているというのが、この三徳会の現状だということでよろしいか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"今も、三徳会に勤めている外国人の方はその資格も取られたというところで、すごく支援されていると捉えています。引き続き外国人人材だけではなく、安定的な施設運営ができるような人材確保策、法人ができるように、区としても支援していきたいと考えています。","id":"exchange-033"},{"speaker":"やなぎさわ委員","kind":"質問","question":"では、三徳会の外国人人材の人数ですとか、給料、平均賃金とかという話が分かれば、教えてほしいのですが。いきなり数字を出してしまって申し訳ないのですが、もし分かればでいいのですけれども、お伺いします。","respondent":"菅野高齢者福祉課長","answer":"三徳会の中での、今、区として捉えている外国人の数は、たしか１３人だったと捉えております。賃金につきましては、外国人の方に幾らというのを日本人の方と分けているのかとか、その辺りについては確認は取れておりません。","id":"exchange-034"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"既に働いている方と外国人人材、特定技能とか、様々な要件で入ってこられる方との賃金の差というのをしっかり確認してほしいと求めました。直接来てほしいという要望は強くあります。","respondent":"菅野高齢者福祉課長","answer":"今、区は居住支援手当を、職員の方は月額１万円という手当を支給しています。これだけではなく、これからも事業者の声に耳を傾け、支援に努めてまいりたいと思います。","id":"exchange-035"},{"speaker":"鈴木委員","kind":"質問","question":"委員長、すみません。これは第４６号、第４９号、第４７号、第５０号、第４８号、全て一括でという意味か尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-036"},{"speaker":"鈴木委員","kind":"意見","question":"それであれば、第４６号、第４９号、第４７号、第５０号については賛成です。第４８号については、株式会社に委託ということで、区が指定管理者として委託する場合は、営利目的の株式会社はなじまないということで、反対ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-037"}]},{"id":"topic-04","title":"高齢者地域支援課所管分といたしまして、(18)第５１号議案、指定管理者の指定","agenda":"高齢者地域支援課所管分といたしまして、(18)第５１号議案、指定管理者の指定","exchanges":[{"speaker":"やなぎさわ委員","kind":"提案","question":"１つだけすみません。８ページのところのｅスポーツを利用した事業実施というところなのですけれども、具体的に今どのような提案というか、教えてほしいと求めました。","respondent":"樫村高齢者地域支援課長","answer":"ソフトですとか、そういった具体的な提案というのはないのですけれども、多世代交流支援施設というところで、高齢者だったり、それ以外の世代の方が一緒に共通して楽しめる取組ということでご提案をいただいているところです。","id":"exchange-038"},{"speaker":"やなぎさわ委員","kind":"提案","question":"具体的にもし提案というか、いろいろ提案をもらいつつ、よいものを築き上げていってほしいと求めました。要望ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-039"}]},{"id":"topic-05","title":"続きまして、(19)第５６号議案、品川区国民健康保険条例の一部を改正する条例","agenda":"続きまして、(19)第５６号議案、品川区国民健康保険条例の一部を改正する条例","exchanges":[{"speaker":"鈴木委員","kind":"提案","question":"今回、なぜ下がったのかという、その理由を伺いたいと思います。１２ページのところに、Ａ３判で、確認させてほしいと求めました。","respondent":"池田国保医療年金課長","answer":"今回、剰余金１５６億円を保険料のほうにつぎ込むということになりましたので、保険料の部分が下がったという形になっています。１２ページの部分で、私どものほうで、上がる方はいないということで見ているところです。","id":"exchange-040"},{"speaker":"鈴木委員","kind":"質問・要望","question":"活用されるのが１５６億円ということなので、この差額というのですか、それはどのように使われるのかについても伺いたいと思います。平均だと、これが２.２３％と低いのですが、この違いというのは何なのかお聞かせほしいと求めました。","respondent":"池田国保医療年金課長","answer":"令和５年度につきましては６％増えるというような見込みを立てていたところですけれども、実は令和４年度はマイナスの見込みを立てていたところ。実際、実際に東京都の計算ではマイナスの５.５％と大きい数字ではありますけれども…","id":"exchange-041"},{"speaker":"鈴木委員","kind":"質問・要望","question":"先ほど令和６年、６％上がるということで見込んだものが、令和５年度は実際は何％だったのかというのが分かったら、教えてほしいと求めました。この１％分というのは、品川区の法定外繰入れは幾らになるのかについても説明を求めました。","respondent":"池田国保医療年金課長","answer":"１人当たりおよそ１,６００円ほど一般財源から入るような形になっておりまして、１億円ほど、こちらのために一般財源のほうをつぎ込む形になります。","id":"exchange-042"},{"speaker":"鈴木委員","kind":"質問・要望","question":"この法定外繰入れをさらに増やして、保険料引下げに区としても努力するというふうにぜひしてほしいと求めましたが、その点も伺いたいと思います。２ページの軽減のところなのですけれども、この軽減の額が増えることによって対象となる人がどれぐらい増えるのかについても伺いたいと思います。","respondent":"池田国保医療年金課長","answer":"２つご質問いただいたと思いますけれども、１つ目の保険料の軽減、そこはできないということでご理解いただければと思います。今回の改正で１５５世帯ほど増加ということになりまして、２割の軽減をされる方につきましては、６８世帯ほど増えるという形で計算上なっています。","id":"exchange-043"},{"speaker":"鈴木委員","kind":"提案","question":"区長会や課長会でもぜひ提案をしてほしいと求めましたが、いかがでしょうか。島根県知事は、これが８月からの実施ということになるわけですが、この影響についてどう考えられているかについても伺いたいと思いますとの意見を述べました。","respondent":"池田国保医療年金課長","answer":"これまで１年間に多回、それでいろいろと国のほうでまた考え直すようなことをやっているのかもしれませんけれども、国の制度です。あくまでもセーフティネットということでの国の制度ですので、こちらの制度について見守っていくような形をする次第です。","id":"exchange-044"},{"speaker":"鈴木委員","kind":"質問・要望","question":"これをぜひ２３区からなくして、ぜひ声を上げていただきたいということで、この要望もしておきます。国のあれを見守るというだけではなく、一番当事者に関わる自治体としても声を上げていただきたいということで、要望をします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-045"},{"speaker":"鈴木委員","kind":"質問・要望","question":"国に公費の増額を求めるのは当然のことですが、保険料の引下げ、それから子どもの国保料の無料化を要望をしたいと思います。それから、高額療養費の自己負担引上げは、今からでも中止の決断をすべきだと述べておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-046"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"そういった方たちが自己負担が非常に重いということになっておりますので、ぜひ法定外繰入れを元に戻すような措置も検討してほしいと求めました。賛成です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-047"}]},{"id":"topic-06","title":"続きまして、(6)第２７号議案、品川区公衆浴場の設置場所の配置および衛生措置等の基準に関する条例の一部を改正する条例","agenda":"続きまして、(6)第２７号議案、品川区公衆浴場の設置場所の配置および衛生措置等の基準に関する条例の一部を改正する条例","exchanges":[{"speaker":"筒井委員","kind":"質問","question":"今回の改正によって、現在、品川区の公衆浴場に対する検査とかもこれが反映されて厳しくなるとか、今のこの改正によって何か影響があるとか、そういったことは考えておりますか尋ねました。","respondent":"赤木生活衛生課長","answer":"委員ご指摘の、厳しくなったというよりも、より正確に検査ができるようになったとご理解いただければと思います。","id":"exchange-048"},{"speaker":"筒井委員","kind":"質問","question":"従来、そういう検査を行っていたかと思うのですけれども、この新しい基準による検査というのは、今後、いつ行われますか尋ねました。","respondent":"赤木生活衛生課長","answer":"条例の施行が令和７年４月１日よりとなっておりますので、来年度の検査からこの指標を用いて検査するような形になります。","id":"exchange-049"},{"speaker":"鈴木委員","kind":"質問","question":"その検査なのですけれども、保健所がやっている検査になるのか。どこが年何回ぐらい、どういう形でやっているのかについて、検査の現状を説明を求めました。","respondent":"赤木生活衛生課長","answer":"検査自体は、生活衛生課の検査担当で実際に検査をさせていただいておりまして、公衆浴場の水質検査というのを、年２回、一斉検査という形でやらせていただいている中で、そういった部分で採水をしたものを検査をしています。","id":"exchange-050"}]},{"id":"topic-07","title":"令和７年請願第６号、国に対して訪問介護の基本報酬引き上げを求める意見書の提出を求める請願","agenda":"令和７年請願第６号、国に対して訪問介護の基本報酬引き上げを求める意見書の提出を求める請願","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"せっかく意見陳述をしていただけるということですので、審査に私はぜひ参考にしたいと思いますので、審査の前に意見陳述をしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-051"},{"speaker":"ひがし委員","kind":"質問・要望","question":"先ほどの説明の中で１点だけ確認したかったのですけれども、課長会などの機会を狙って要望していくというお話があったと思うのですが、これ。現在、課長会だったり何かの審議会で、介護報酬引上げについて区から何か発言をしたとか、要望したということがあったら、ぜひ説明を求めました。","respondent":"菅野高齢者福祉課長","answer":"令和６年１１月に、全国市長会でも、国にそういった要望をさせていただいた経過があります。品川区としても、事業者が経営が困っているというようなところも踏まえて、応援意見という形のような部分で意見は申し上げている次第であります。","id":"exchange-052"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そこのところをどう考えられるかということが１つと、何人もの方からお話を伺いましたけれども、本当に現場は大変なのです。それなので、そこのところをまずは区としてもつかんでいただきたいと思うのですけれども、その点についても伺います。","respondent":"菅野高齢者福祉課長","answer":"予定としましては、１２月１３日まで期限を延ばして、何回か区市町村のほうに周知をしてほしいというような投げかけもあった調査です。予定としては、区内には２０か所の在宅介護支援センターもありまして…","id":"exchange-053"},{"speaker":"鈴木委員","kind":"質問・要望","question":"今度３月に閉鎖するというところもお話を伺いましたけれども、このままにするわけにはいかないというのが、改めて要望させてほしいと求めました。地域に根差した小規模の事業所が倒産、その１２か所というところに対して、区としてどう捉えられているかも伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"区としては、今後も必要な方のニーズに的確に対応し、質の高い介護サービスを提供していけるよう支援していく必要があると捉えております。廃止の件数が１２か所というところなのですけれども、あとは従業員のホームヘルパーの高齢化などが挙げられていると認識しております。","id":"exchange-054"},{"speaker":"鈴木委員","kind":"質問","question":"なぜ人員不足になっているのかということを考えると、人員不足に拍車をかけたのが、この介護報酬引下げなのです。今回で３回目になりますけれども、ぜひご質問をいただけたらと思いますし、。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-055"},{"speaker":"やなぎさわ委員","kind":"質問","question":"理事者の方にお伺いしますけれども、廃業なりが増えるというお考えというか……、という風には思っていらっしゃらないのか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"リンクしているところとリンクしていないところ、いろいろあるとは思いますが、経営の悪化イコール人員不足に直結しているわけではないのかと。いろいろな理由があるのかと捉えております。","id":"exchange-056"},{"speaker":"やなぎさわ委員","kind":"質問","question":"非常に少し考えると、１００％ではないけれども、かなり大きい割合を占めているのだということはぜひ考慮ほしいと求めました。地域の実情や事業所規模等を踏まえた持続的なサービス提供の在り方に関する調査研究事業という項目のアンケート調査でよろしいか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"国のほうで１２月１３日まで回答期限を延ばした、こちらの予定を見ますと、２月から３月の国の審議会等に公表される予定と出ておりますので。","id":"exchange-057"},{"speaker":"やなぎさわ委員","kind":"確認","question":"なので、これをまた５月に調査をやって、その後アンケート集計して結果を待ってなどといったら、来年になってしまうのですかという話もあり得ます。こういった調査が、今私が申し上げたようなことで間違いないのかということを確認したいのですけれども、いかがか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"委員のおっしゃるとおりで、おおむね合っているとは思います。一応、あくまでも国の責任において実施するものであると考えているところですので、引き続き区内事業所の実態を注視していきたいという考えです。","id":"exchange-058"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"要介護者の方の要望にかなわないような時間だったり、どうしてもケアマネも、現状を聞いてほしいと求めました。１年で１つでも廃業、休止になるということが非常に大きなことなのだとぜひ捉えてほしいと求めましたが、いかがか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"そういった意味では、そういった高齢者の方が安心してサービスを受けられるように努めていかなくてはいけないかとは思っているところです。そういったところで、区としては、今後も地域の実情を十分に把握しつつ、支援が必要なときには適宜対応していきたいと考えています。","id":"exchange-059"},{"speaker":"鈴木委員","kind":"質問","question":"予算規模は約３５７億円ですということで書いてあるのですけれども、成立を後押しする声をどれだけ上げられるかがポイントだと書かれているのです。これが本当に後押しになって、そのように一緒に力を合わせられたらうれしいと思っているのですけれども、どうか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-060"},{"speaker":"ひがし委員","kind":"質問・要望","question":"先ほどお話でありました全国市長会だったり、あとは、特別区の中の課長会でも要望を伝えてくれているというところは確認をさせていただきました。介護事業者全体で居住支援の件についても事業を進めているということで確認をしていますので、まずは区としてできるところというのを。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-061"},{"speaker":"鈴木委員","kind":"質問・要望","question":"本当に皆さんに聞いていただきたいと思って準備をしてきてくれていると思いますので、その声は議会としても受け止めるということが当たり前だと思いますので、ぜひ意見陳述を受けていきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-062"},{"speaker":"やなぎさわ委員","kind":"意見","question":"１時間２時間しゃべるわけではございません。反対する方はいないと思いますけれども、ぜひ聞ければと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-063"},{"speaker":"石田（秀）副委員長","kind":"質問","question":"今回もこれだけ署名をされて、皆さん勉強されてきたのでしょう。私はその中で行っていくということですから、意見陳述は受ける必要はないと考えていますので、ぜひそれでお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-064"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"これは国でやっていくべき話であって、それをしっかり見守って、それでその後どうしていくのだということをやっていく。基本報酬引上げを求める意見書の提出、前回もずっといろいろ言ってきたけれども、不採択の意見は変わらないということです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-065"},{"speaker":"若林委員","kind":"質問","question":"３定でしたか、今まさに年度内、加算が申請しやすいように取り組んでいると伺っております。様々質問をしたり、私どもとしても、不採択で結構かと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-066"},{"speaker":"ひがし委員","kind":"質問・要望","question":"現在、区でも居住支援などを含めて施策を進めているということを確認できましたので、今回の請願には添い難いという結論をします。ぜひこれからも区内事業者と意見交換を行いながら、現在行っている事業に加えて、さらに検討いただくようにということは改めて要望します。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-067"},{"speaker":"鈴木委員","kind":"提案","question":"共産党の提案でもありますけれども、これは一致できるのではないかと思うのです。先ほど申し上げましたように、僅か４％の、それで本当に現場の状況が分かるのですかということになると思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-068"},{"speaker":"筒井委員","kind":"意見","question":"魅力を感じる職場でならなくてはいけないということで、これは根本的に基本報酬を引き上げる必要があると考えます。その中で、やはり区から国に対して意見を言っていくということも一つの方策かと思いますので、採択でお願いしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-069"},{"speaker":"やなぎさわ委員","kind":"質問","question":"れいわ新選組と共産党はなぜか呼ばれなかったのですけれども、こういったものを通していける、そういったものの後押しになり得ると思っています。言っていることではなくて、やっていることがその人の本質だと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-070"}]},{"id":"topic-08","title":"令和７年陳情第７号、ネズミ駆除対策を要望する陳情","agenda":"令和７年陳情第７号、ネズミ駆除対策を要望する陳情","exchanges":[{"speaker":"やなぎさわ委員","kind":"質問","question":"そもそも集合住宅等にネズミの調査みたいなことを、今まで区としてやられたご経験というのは、実績というのはあるのか尋ねました。","respondent":"赤木生活衛生課長","answer":"集合住宅に対する調査の実績についてのご質問ですけれども、集合住宅に関する調査というのは、区で実施した実績というのはございません。","id":"exchange-071"},{"speaker":"ひがし委員","kind":"質問","question":"実際に月にどのぐらい相談が来ているのかというお話が分かれば、教えてください。集合住宅の調査というものが実際に可能なのかということも併せて説明を求めました。","respondent":"赤木生活衛生課長","answer":"相談件数ですけれども、月によってばらつきはありますが、約２０件から３０件程度、保健所のほうで相談、苦情を受け付けております。２点目につきまして、集合住宅の調査を実施することが可能かどうかですけれども、現実的には難しいかと考えております。","id":"exchange-072"},{"speaker":"ひがし委員","kind":"質問","question":"月に２０件から３０件というと、私は多いのかと感じるのですけれども、区として、他区と比べた状況でも構いませんが、相談が来ている２０件から３０件というのをどのように評価しているのか、見解を説明を求めました。","respondent":"赤木生活衛生課長","answer":"件数につきましては、２０件から３０件というので、営業日当たりにすると、１日１件以上というところにはなってくるというところではあります。今年度は１月末時点で２１３件というところになりますので、こちらは…","id":"exchange-073"},{"speaker":"鈴木委員","kind":"質問","question":"今伺って思ったのですけれども、年間２３２件もあるネズミの相談というのは、具体的にはどんな相談なのか。先ほど地域のネズミ対策、地域でネズミが住みにくい環境をつくるという、そこら辺のところをもう少し具体的にお聞かせいただけたらと思います。","respondent":"赤木生活衛生課長","answer":"２点目のご質問ですけれども、ネズミは餌があるところであったり、巣の材料があるところに集まる傾向があります。は、それと同時に、地域全体としてネズミの発生を抑えるようなところの部分につながってこようかと考えております。","id":"exchange-074"},{"speaker":"鈴木委員","kind":"質問","question":"ここの陳情で、そういうのは区としても把握されているのか。区として把握されている部分というのはあるのか尋ねました。","respondent":"赤木生活衛生課長","answer":"逆を返せば、隙間が空いているというところになりますので、ネズミが侵入できるところがあると。そういうネズミが増える原因となるものが置いてあるというところになりますので、発生の原因としては考えられるかと考えています。","id":"exchange-075"},{"speaker":"鈴木委員","kind":"意見","question":"マンション建築のときにはごみ置場を密閉するようにみたいな、そういう指導みたいなものというのは入れることが、ここじゃないかな。こういうので陳情に出されているので、対策としてどんな手があるかというのが区としてもあったら、お聞かせいただけたらと思いますとの意見を述べました。","respondent":"赤木生活衛生課長","answer":"そういったところに密閉するごみ集積所の設置を義務づけるというところで、指針か何かに盛り込むというお話ですけれども。住民全体として、先ほど申し上げたような、まずは管理組合様のほうで話し合っていただくというところが重要になってこようかと考えています。","id":"exchange-076"},{"speaker":"筒井委員","kind":"質問","question":"相談、月２０件から３０件ということなのですけれども、集合住宅の住民からのご相談の割合、もしくは管理組合からのご相談というのはどのぐらいなのか尋ねました。","respondent":"赤木生活衛生課長","answer":"委員からのご質問の件数の内訳ですけれども、申し訳ございません、集合住宅でというところからの受付というところでは統計を取っていないもので、内訳については把握しておりません。","id":"exchange-077"},{"speaker":"筒井委員","kind":"質問","question":"把握できていないということで、そんなに割合としては多くないのかと推測されるのですけれども、また、基本的に区の方針としては、防除方法を教える、また、駆除業者を教えるということで、基本的にそうした情報提供をして、そちらでやっていただくというスタンスでよろしいか尋ねました。","respondent":"赤木生活衛生課長","answer":"委員おっしゃるとおりです。","id":"exchange-078"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。いかがお考えなのかということと、いかがお考えなのか、説明を求めました。","respondent":"赤木生活衛生課長","answer":"１点目の地域のネズミ対策支援事業ですけれども、町会・自治会長様を通じてという形にはなりますけれども、当該事業をご利用いただくことは可能です。こちらとしても当然対応させていただきたいと考えていますが、広報等で周知をさせていただいているですので…","id":"exchange-079"},{"speaker":"石田（秀）副委員長","kind":"意見","question":"もう１人の人にかけたら、そこは、ある程度扉を直したと。これは議会で我々がどうという意味での、これの陳情を採択というわけにはなかなかいかないので、不採択でお願いしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-080"},{"speaker":"若林委員","kind":"意見","question":"要するに、個別のマンションが、管理人がいるところ、いないところあると思いますけれども、一生懸命やられていますよね。個別のご努力にこれはお任せするということだと思いますので、不採択でお願いしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-081"},{"speaker":"ひがし委員","kind":"質問・要望","question":"先ほどのご答弁で、区として集合住宅を全て把握しているというわけではなくて、実際に調査が難しいというお話を伺いました。区として地域ネズミ対策支援事業というのも行っているということを確認しましたので、また、個別の対応を丁寧にしていただくように求めします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-082"},{"speaker":"鈴木委員","kind":"質問","question":"結論を出すということで、趣旨採択でお願いしたいと思います。そういう状況もあるということですので、ネズミの対策というのは一定必要かと思いますので、趣旨採択でお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-083"},{"speaker":"筒井委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いします。この陳情者のご要望の、個別相談を区にすればいいだけの話なので、今回は不採択とします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-084"},{"speaker":"やなぎさわ委員","kind":"意見","question":"本日結論を出すで、趣旨採択でお願いいたします。月に２０件から３０件と、いいのかと思いますので、趣旨採択でお願いしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-085"}]},{"id":"topic-09","title":"令和７年陳情第１２号、世代間の分断を助長する「長寿祝い金」事業の廃止及び、住民税均等割りの減税を求める陳情","agenda":"令和７年陳情第１２号、世代間の分断を助長する「長寿祝い金」事業の廃止及び、住民税均等割りの減税を求める陳情","exchanges":[{"speaker":"筒井委員","kind":"質問","question":"陳情理由の２番で、財務省解体デモというのも最近話題になっておりますけれども、それが今の日本の現状かと考えております。去年の１２月、区としていかがお考えなのか、説明を求めました。","respondent":"東野福祉計画課長","answer":"そういった意味から、金品そのもの、商品券そのものをなくすということは考えてはおりません。そうしたことから、お金の使い方につきましては、きちんと予算編成の中で行っているものとして考えているものです。","id":"exchange-086"},{"speaker":"筒井委員","kind":"質問","question":"それはどうなのかと思いますし、喜びが減ったとか、そういうことになるのか。その点、岐阜県郡上市の場合、どうお考えなのか、改めてお聞きします。","respondent":"東野福祉計画課長","answer":"この長寿お祝い事業だけでなく、様々な施策として利用されているものですから、そこの考え方を述べたものになります。それから、岐阜県郡上市のお考えにつきましては、特に把握しているところではございません。","id":"exchange-087"},{"speaker":"筒井委員","kind":"質問・要望","question":"こうした非常に現役世代中心に不満な状況ということを踏まえて考えていっていただきたいと思うのですけれども、その点についてはどうお考えなのか。本当に世代間のバランスということを今後考えなければいけないと思うのですけれども、その辺り、どうお考えなのか、説明を求めました。","respondent":"東野福祉計画課長","answer":"例えば子育て世代に対しましては、いろいろな所得制限の撤廃ですとか、そういったような無償化の取組なども併せて行っている。区としての政策をきちんと行っているということで私どもは考えてあります。","id":"exchange-088"},{"speaker":"鈴木委員","kind":"質問・要望","question":"１人当たり幾らぐらいになるかという計算はされていないでしょうか……、私、計算してみたのです。１か月１１円の減税をするために、高齢者のささやかな楽しみを奪うのですかというのが、私はこの陳情の中身なのではないかと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-089"},{"speaker":"やなぎさわ委員","kind":"質問","question":"この間の予算の推移というのはすごく２倍に増えているとか、減っているとか、その辺の数字というのがもし分かれば教えてください。分からなければ、直近５年ぐらいで構いませんけれども。","respondent":"東野福祉計画課長","answer":"８０歳廃止ですとか、その前につきましては、７５歳以上の方については皆さんにお渡ししていたとかというときもございました。その辺を順次見直しをしてきたものです。","id":"exchange-090"},{"speaker":"やなぎさわ委員","kind":"質問","question":"ということは、高齢者はどんどんどんどん増えてきているけれども、これだけ予算額が本当に４分の１ぐらいになっているということは、その分、いわゆる受け取る額といいますか、お一人お一人が受け取るそういった額とかもある程度絞ってきたという現状ということでよろしいか尋ねました。","respondent":"東野福祉計画課長","answer":"金額につきましては、見直しをした結果減らしているもの、または、逆に対象年齢の見直しにより減ったもの、それから、若干増やしたもの、様々です。その年代年代で、必要な形で、こちらのほう、予算上、お祝い金の設定をしてきたところです。","id":"exchange-091"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"今、その中で高齢者世帯は５人に１人が貧困という調査がありますので、高齢者世帯が潤っているということはないのかと考えています。この内容自体が安否確認の事業ということで、意外と安否確認は実はできていないというお話もあったのですけれども、お聞かせいただきたいのですが。","respondent":"東野福祉計画課長","answer":"そのようなことから、令和６年度、今年度につきましても、郵送で実は行いました。その際の見守り活動というのができるものとして考えているものです。","id":"exchange-092"},{"speaker":"やなぎさわ委員","kind":"確認","question":"やはり安否確認事業というと、郵送になっていたり、どういった事業名にするかというところは工夫の余地があるのかと。これは安否確認だというと、それこそいろいろご意見が出てきたりするのかと思いますので、ぜひそこら辺の名称を検討されてみてはいかがかと思います。","respondent":"東野福祉計画課長","answer":"こちら、同様の請願が出てきた際に、ちょうど予算編成の時期でもございましたので、令和７年度予算をどうするかというところで検討を行いました。検討の余地があるのかと思っておりましたが、その中で検討した結果として、安否確認事業に収まったというものです。","id":"exchange-093"},{"speaker":"やなぎさわ委員","kind":"提案","question":"かしこまりました。要望ですけれども、そのままずばり長寿お祝い事業などとしてみてはいかがかということで、提案だけしておきますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-094"},{"speaker":"石田（秀）副委員長","kind":"質問","question":"１つは、現役世代がどうだという話があったけれども、基本は相互扶助。私はそれが人に対する温かみのある行政だと思っているので、それはそれでしっかり残してもらいたいと思っているので、不採択です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-095"},{"speaker":"ひがし委員","kind":"意見","question":"本日結論を出す、不採択でお願いいたします。見守りの観点のほかにも、敬意の意を示すというような目的も果たしている大切な事業だと考えていますので、今回の陳情には添い難いと結論しますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-096"},{"speaker":"鈴木委員","kind":"意見","question":"結論を出すで、不採択でお願いしたいと思います。敬老の意を表するということで、大事な事業で、ずっと続けるべき事業だと思っていますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-097"},{"speaker":"筒井委員","kind":"質問","question":"郵送方式に変わったということで、見守りという効果が果たして実効性あるものになるのか、非常に疑わしいものになったということであります。一方、しっかりと代わりに、一番今負担を強いられている現役世代中心に減税をする必要があるということの理由で、採択でお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-098"},{"speaker":"やなぎさわ委員","kind":"意見","question":"やはりこういった長寿お祝い事業を通じて、高齢者の方に敬老の意を表するということは非常に大事なことだと考えております。こういった事業をなくすことで、その財源を給食費に充てるなどということをすると、むしろそれが分断につながるのではないかと考えますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-099"}]},{"id":"topic-10","title":"その他","agenda":"その他","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"保健師が足りないということをどうしていくのかという質問があったと思うのですけれども、また、そこら辺のところの中身をお聞きできたらと。お願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-100"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/238890?Template=document&Id=6957#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":85971,"voices":395}}]);
